export const KNOWLEDGE_SOURCES: readonly { file: string; source: string }[] = [
 {
  "file": "entries/accessibility/a11y-checklist.md",
  "source": "---\nid: a11y-checklist\ntitle: Accessibility checklist for generated sites\ncategory: accessibility\nsummary: The minimum every generated page meets: landmarks, headings, alt text, contrast, keyboard, focus, forms, motion, language and zoom.\nintents: [review, fix-accessibility, build-site]\ntags: [accessibility, a11y, wcag, checklist, screen-reader]\nphases: [build, review]\npriority: 5\nrelated: [color-contrast-rules, a11y-keyboard-focus, a11y-semantics]\nversion: 1\n---\n1. `lang` on html; one `h1` per page; headings in order without skipping levels for style.\n2. Landmarks: `header`, `nav` (labelled when more than one), `main`, `footer`. A skip link to main.\n3. Images: meaningful `alt`, empty alt for decoration, no text baked into images without an alternative.\n4. Contrast: 4.5:1 text, 3:1 large text and UI, including on images and hover states.\n5. Keyboard: everything interactive reachable and operable in a logical order; no traps; visible focus.\n6. Forms: labels, error messages linked to fields, no placeholder only labels.\n7. Motion: reduced motion respected; anything moving over 5 seconds can be paused; nothing flashes more than 3 times per second.\n8. Media: captions for video with speech, no autoplay with sound.\n9. Zoom: page works at 200% zoom and 320px width without horizontal scroll.\n10. Links: say where they go (\"Read the menu\", not \"Click here\"); external links that open new tabs say so.\n11. Names: icon buttons have accessible names; dynamic updates announced via live regions.\n"
 },
 {
  "file": "entries/accessibility/a11y-content.md",
  "source": "---\nid: a11y-content\ntitle: Accessible content and copy\ncategory: accessibility\nsummary: Alt text that helps, link text, plain language, readable lengths, and not conveying meaning with colour, shape or position alone.\nintents: [write-copy, review, fix-accessibility]\ntags: [alt-text, link-text, plain-language, readability, content]\nphases: [build, review]\npriority: 3\nrelated: [core-copywriting, a11y-checklist]\nversion: 1\n---\n- **Alt text**: what the image shows that matters here. A product photo: \"Olive linen overshirt, front view\". A coach portrait on the about page: \"Sam Reid in the studio\". Decorative textures: `alt=\"\"`. Do not start with \"Image of\".\n- **Link text**: unique and meaningful out of context. Several \"Read more\" links get a visually hidden suffix (\"Read more about the spring retreat\").\n- **Plain language**: short sentences, common words, explain jargon once. Helps everyone, especially non native speakers.\n- **Not colour alone**: sale prices, errors, availability and required fields also use text or icons.\n- **Not position alone**: \"click the button on the right\" fails on phones and screen readers.\n- **Numbers and dates**: write them so they read naturally (\"14 June 2026\"), use `<time datetime>`.\n"
 },
 {
  "file": "entries/accessibility/a11y-keyboard-focus.md",
  "source": "---\nid: a11y-keyboard-focus\ntitle: Keyboard use and focus management\ncategory: accessibility\nsummary: Tab order, focus-visible styles, managing focus for overlays and dynamic content, roving tabindex and skip links.\nintents: [fix-accessibility, build-component]\ntags: [keyboard, focus, tab-order, focus-trap, skip-link, focus-visible]\ncomponents: [dialog, drawer, menu, tabs]\nphases: [build, review]\npriority: 4\nrelated: [a11y-checklist, component-dialog, state-interactive-matrix]\nversion: 1\n---\n- **Order**: DOM order is tab order. Do not use positive `tabindex`. Visual reordering (CSS order, grid placement) must not scramble it.\n- **Focus style**: `:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }`. On dark sections, the focus colour must still be 3:1.\n- **Skip link**: first focusable element, visible on focus: `<a class=\"skip\" href=\"#main\">Skip to content</a>`.\n- **Overlays**: on open, move focus inside; trap it (native dialog does this); on close, return focus to the trigger. Use `inert` on the background.\n- **Dynamic content**: after an action that replaces content (form success, filter results), move focus to the new heading or announce it.\n- **Composite widgets** (tabs, toolbars, radio like pickers): one tab stop for the group, arrow keys within (roving tabindex).\n- **Custom controls**: Space and Enter activate buttons; Escape closes; never require a mouse for drag only interactions without an alternative.\n"
 },
 {
  "file": "entries/accessibility/a11y-motion-media.md",
  "source": "---\nid: a11y-motion-media\ntitle: Motion, media and sensory accessibility\ncategory: accessibility\nsummary: Vestibular safety, pausing moving content, flashing limits, captions and transcripts, and audio etiquette.\nintents: [add-motion, review, fix-accessibility]\ntags: [reduced-motion, vestibular, captions, transcripts, flashing, autoplay]\ncomponents: [media-player, carousel, marquee]\nphases: [build, review]\npriority: 4\nrelated: [motion-principles, component-media-player, motion-marquee]\nversion: 1\n---\n- **prefers-reduced-motion**: remove parallax, large movement, zooms and auto advancing; keep instant state changes and fades under 200ms if needed.\n- **Pause, stop, hide**: anything that moves, blinks or scrolls automatically for over 5 seconds (marquees, carousels, background video) needs a pause control.\n- **Flashing**: nothing flashes more than three times per second; avoid strobe effects even for nightlife sites.\n- **Video**: captions for speech; audio description or a text alternative for important visual information; transcripts for podcasts and long audio.\n- **Autoplay**: never with sound. Muted background video only, paused under reduced motion, with a pause button.\n- **Large scrolling effects**: provide a way to read the content without them (static fallback).\n"
 },
 {
  "file": "entries/accessibility/a11y-semantics.md",
  "source": "---\nid: a11y-semantics\ntitle: Semantic HTML before ARIA\ncategory: accessibility\nsummary: Using native elements for structure and controls, the few ARIA attributes generated code actually needs, and common misuse.\nintents: [build-component, fix-accessibility]\ntags: [semantics, html, aria, landmarks, native-elements]\nphases: [build, repair]\npriority: 4\nrelated: [a11y-checklist, debug-common-markup]\nversion: 1\n---\n**Native elements first**: `button`, `a`, `details/summary`, `dialog`, `input type=...`, `select`, `table`, `ul/ol`, `figure/figcaption`, `blockquote`, `time`, `nav`, `main`. They come with keyboard support and roles.\n\n**ARIA you will actually use**: `aria-label` (icon buttons), `aria-labelledby` and `aria-describedby`, `aria-expanded` and `aria-controls` (disclosures), `aria-current=\"page\"`, `aria-pressed` (toggles), `aria-invalid`, `aria-live` / `role=\"status\"`, `aria-hidden=\"true\"` (decorative duplicates), `aria-busy`.\n\n**Common misuse**\n- `role=\"button\"` on a div instead of a button.\n- `aria-label` on a div or span with no role (ignored).\n- `aria-hidden=\"true\"` on focusable elements (creates ghosts).\n- `role=\"menu\"` for site navigation.\n- Headings chosen for size (an `h4` because it looks small). Style the right level instead.\n- Lists of links without a list element.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-default-fonts.md",
  "source": "---\nid: anti-slop-default-fonts\ntitle: Default fonts and fixed type sizes\ncategory: anti-slop\nsummary: Inter, Poppins or Montserrat as the headline face, three fixed pixel sizes and browser tracking are the first sign a site was generated; pick a type system and a fluid scale.\nintents: [choose-fonts, review, fix-design]\ntags: [fonts, inter, poppins, montserrat, roboto, system-ui, type-scale, clamp, tracking, default]\ncomponents: [typography]\nphases: [concept, build, review, repair]\npriority: 5\nrelated: [typography-type-library, typography-scale, typography-tracking-measure]\nversion: 1\n---\n**The habit**: headings in Inter, Roboto, Open Sans, Lato, Montserrat, Poppins, Arial, Helvetica or plain system-ui; sizes like 48px, 32px, 18px written as fixed pixels; letter spacing and line height left at the browser default; bold everywhere because nobody chose a weight.\n\n**Why it reads as slop**: these are what every template and every model reaches for first, so the site looks like everything else before a visitor reads a word. Fixed sizes break on phones (a 64px headline wraps into five lines) or look timid on wide screens.\n\n**Checked**: the anti-slop check flags a default display face as an error (slop.default-fonts), fixed display sizes with nothing fluid as an error and default tracking on big type as a warning (slop.type-scale). The concept check refuses a default display face unless allow includes \"default-fonts\", which is only for a creator who asked for that face by name.\n\n**Fix**: choose a system from typography-type-library for the concept's voice, set it with set_tokens fonts, put a clamp() scale on the section root, give display type its own tracking (-0.01em to -0.045em lowercase, +0.06em to +0.2em caps and small labels) and leading (0.86 to 1.05), and choose weights on purpose. A default face can stay as the body text.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-empty-words.md",
  "source": "---\nid: anti-slop-empty-words\ntitle: Empty marketing words\ncategory: anti-slop\nsummary: The vocabulary that marks machine copy, why it fails, and how to replace it with specifics from the business.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, copy, buzzwords, marketing-words, words]\nphases: [concept, build, review]\npriority: 5\nrelated: [core-copywriting]\nversion: 1\n---\n**Flagged words and phrases**: unlock, elevate, seamless(ly), powerful, effortless(ly), supercharge, transform(ative), empower, streamline, revolutionise, game changer, next level, cutting edge, state of the art, world class, unleash, harness, leverage, robust, innovative, delve, embark, journey (metaphorical), tapestry, testament, in today's fast paced world, take it to the next level, look no further, whether you're X or Y.\n\n**Why they fail**: they could describe any product, so they tell the visitor nothing, and readers have learned to recognise them as generated.\n\n**Fix**: replace each with the specific thing. Ask \"what does this actually do, for whom, how long, how many, made of what?\"\n- \"Seamless booking\" -> \"Pick a time, pay, get a calendar invite.\"\n- \"Powerful presets\" -> \"14 presets for overcast street photography.\"\n- \"Elevate your wardrobe\" -> \"Heavyweight cotton basics, cut in Porto.\"\n\nThe evaluator counts them in visible text; one or two can be accidents, a pattern is an error.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-excessive-radius.md",
  "source": "---\nid: anti-slop-excessive-radius\ntitle: Excessive corner radius\ncategory: anti-slop\nsummary: Everything rounded to 24px or more, pill buttons on serious brands, rounded photos; matching radius to the concept.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, radius, rounded, border-radius, rounded-3xl]\nphases: [concept, build, review]\npriority: 3\nrelated: [style-luxury, style-swiss, anti-slop-pill-badges]\nversion: 1\n---\n**The pattern**: cards at 24 to 32px radius, buttons as pills, inputs as pills, images rounded, sections rounded, all at once and regardless of brand.\n\n**Evaluator checks**: the distribution of radius values; a high share at 20px or more (or `rounded-2xl`, `rounded-3xl`) without a playful or wellness concept.\n\n**Fix**: pick a radius system in the concept: 0 for Swiss, editorial, luxury and brutalist; 2 to 6px for most product and service sites; 8 to 16px for friendly and wellness; pills only for playful systems. Photos are usually square cornered. Nested radii follow `inner = outer - padding`.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-fake-proof.md",
  "source": "---\nid: anti-slop-fake-proof\ntitle: Fabricated testimonials and metrics\ncategory: anti-slop\nsummary: Invented quotes, names, ratings, counts and logos: how to spot them in generated output and what to show instead.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, fake-proof, testimonials, metrics, stats, logos, reviews]\nphases: [concept, build, review]\npriority: 5\nrelated: [storelib-honest-data, component-testimonials, component-stats]\nversion: 1\n---\n**Signals the evaluator looks for**: round marketing numbers (\"10,000+\", \"500+ clients\", \"98% satisfaction\", \"4.9/5\") not present in store data; testimonial blocks with generic names (Sarah J., John D., Emily R.) and job titles; \"Trusted by\" or \"As seen in\" followed by logos or brand names; star ratings without a review source; \"Join thousands of\"; placeholder avatars.\n\n**Why it matters**: it is false information on a real business's site, and visitors can tell. It also creates legal risk for the creator.\n\n**Fix**\n- Remove numbers not supplied by the store or creator.\n- Remove testimonials the creator did not provide; keep the section as an editor only prompt.\n- Replace logo strips with real collaborations or nothing.\n- Use proof that exists: the creator's own work, a real quote, real product details, years active if the creator said so.\n\nNever excused by a concept.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-floating-cards.md",
  "source": "---\nid: anti-slop-floating-cards\ntitle: Excessive floating cards and card nesting\ncategory: anti-slop\nsummary: Cards everywhere: floating stat cards around images, cards inside cards, every block on a raised surface; when cards earn their place.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, floating-cards, cards, nesting, shadows, card-in-card]\nphases: [concept, build, review]\npriority: 4\nrelated: [component-cards, layout-floating]\nversion: 1\n---\n**The pattern**: small cards hovering over a hero image (\"+32% growth\", a fake notification), every section wrapped in a white rounded box with shadow, cards containing cards, a grid of cards for content that is just text.\n\n**Evaluator checks**: count of absolutely positioned elements with shadows or card classes over media; nested card containers; the share of sections that are wrapped in a bordered or shadowed rounded container; floating animations (`translateY` loops).\n\n**Fix**: remove decorative floating elements; keep one only if it carries real information. Replace text cards with plain typography on a grid. Let sections sit on the page background and separate them with space, rules or background changes. Reserve cards for distinct, clickable objects (products, posts, plans).\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-generic-hero.md",
  "source": "---\nid: anti-slop-generic-hero\ntitle: The generic hero\ncategory: anti-slop\nsummary: The default centred hero (eyebrow pill, big gradient heading, grey paragraph, two buttons, floating screenshot) and how to pick a hero that belongs to the business.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, hero, centred-hero, two-buttons, eyebrow]\nphases: [concept, build, review]\npriority: 4\nrelated: [component-hero, hero_editorial, hero_immersive]\nversion: 1\n---\n**Template signature**: a small rounded badge above the heading (\"New: AI powered\"), a centred two line heading with a gradient word, a grey subheading, a primary and a ghost button side by side, a mockup with a glow, a logo strip.\n\n**Evaluator checks**: in the first section, a pill or badge before the h1, two or more buttons together, centred text, a gradient or glow, and generic heading words.\n\n**Fix**: decide what the visitor must see first for this business: the place (immersive photo), the product (product hero), the person (portrait led split), the statement (type led), the next date (event hero). Write a heading that only this business could use. One primary action; a secondary link only if it serves a different real need (for example \"See the menu\" next to \"Book a table\").\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-identical-saas.md",
  "source": "---\nid: anti-slop-identical-saas\ntitle: Identical SaaS layouts\ncategory: anti-slop\nsummary: The landing page assembly line (hero, logos, three feature cards, alternating rows, testimonials, three tier pricing, FAQ, CTA band) and how to break it.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, saas-template, feature-grid, three-cards, landing-template]\nphases: [concept, build, review]\npriority: 4\nrelated: [industry-saas, core-content-hierarchy]\nversion: 1\n---\n**The sequence**: hero, logo cloud, \"Features\" with three or six icon cards, two alternating image and text rows, testimonial carousel, three pricing tiers with the middle one raised, FAQ, gradient CTA band, four column footer.\n\n**Evaluator checks**: three or more repeated sibling blocks with identical structure (icon plus heading plus paragraph), multiple sections of the same shape in a row, the presence of most items in the sequence.\n\n**Fix**: start from what the visitor needs (core-content-hierarchy). Show the actual product or work instead of describing features; use a list instead of cards; let the number of items come from the content (two, four, seven); merge sections that say the same thing; drop the logo cloud if there are no real logos; vary section density and alignment.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-pill-badges.md",
  "source": "---\nid: anti-slop-pill-badges\ntitle: Pill badge overuse\ncategory: anti-slop\nsummary: Rounded chips above headings, on cards and in heroes that carry no information; when a badge is useful.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, pills, badges, chips, eyebrow, tags]\nphases: [concept, build, review]\npriority: 3\nrelated: [typography-hierarchy-labels, anti-slop-excessive-radius]\nversion: 1\n---\n**The pattern**: a pill above every heading (\"Features\", \"Pricing\", \"Why us\"), badges on every card (\"New\", \"Popular\") without data, rows of tag chips as decoration, numbered chips 01 02 03.\n\n**Evaluator checks**: elements with `border-radius` of 999px or 9999px or `rounded-full` with short text and a background, counted per page and per section.\n\n**Fix**: delete badges that repeat the heading. Keep badges that show real state from data (Sold out, In stock, a real category filter). Labels that carry information can stay as plain small text (no pill).\n\n**Allowed by**: playful and creator concepts where pills are a declared system element, used consistently.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-purple-gradients.md",
  "source": "---\nid: anti-slop-purple-gradients\ntitle: Gradients, purple and blue defaults and glow\ncategory: anti-slop\nsummary: Repeated decorative gradients, the default purple to blue palette, gradient text and glowing blobs; when they are a choice and when they are slop.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, gradient, purple, blue, indigo, violet, glow, neon, blur-blob]\nphases: [concept, build, review]\npriority: 5\nrelated: [color-palettes-by-mood, color-accent-use, style-glassmorphism]\nversion: 1\n---\n**The pattern**: `linear-gradient(135deg, #6366f1, #8b5cf6)` style fills on buttons, headings and backgrounds; gradient text on the hero; blurred purple and blue blobs or radial glows behind content; box shadows tinted violet; neon on near black.\n\n**Why it is slop**: it is the most common default colour story in generated interfaces, so it signals \"made by a tool\" and erases the brand.\n\n**Evaluator checks**: count of gradient declarations; share of colours in the violet and indigo hue range (about 230 to 290 degrees) with medium to high saturation; `background-clip: text` with gradients; large blur filters and coloured glow shadows (`0 0 40px rgba(139,92,246,...)`).\n\n**Fix**: take the palette from the brand or the concept (see color-palettes-by-mood). Replace gradient buttons with a solid accent; replace glows with nothing or a solid surface; replace gradient text with weight or size. If the concept wants a gradient, use one, made from brand colours, in one place, with purpose (a sky in a weather brand, a print overlay in a music release).\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-random-icons.md",
  "source": "---\nid: anti-slop-random-icons\ntitle: Random icon collections\ncategory: anti-slop\nsummary: Icons beside every heading and in every card, mixed icon sets, emoji as icons; when icons help and how to use them consistently.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, icons, icon-grid, emoji, icon-tiles, decorative-icons]\nphases: [concept, build, review]\npriority: 3\nrelated: [component-cards, anti-slop-identical-saas]\nversion: 1\n---\n**The pattern**: a different icon above each feature card (lightning, shield, rocket, sparkles), icons in tinted rounded squares, mixed stroke and fill styles, emoji used as bullet icons, icons beside every label in the footer.\n\n**Evaluator checks**: count of icon elements (svg in tiles, icon font classes, lucide or heroicons classes, emoji) relative to text blocks; icon tiles (icon inside a coloured rounded box) repeated in grids; emoji in headings.\n\n**Fix**: remove icons that only decorate. Keep icons that aid recognition (cart, search, menu, play, social logos, a real category system). Use one set, one stroke width, one size scale, and give interactive icons accessible names.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-relative-judgement.md",
  "source": "---\nid: anti-slop-relative-judgement\ntitle: Judging slop relative to the concept\ncategory: anti-slop\nsummary: Slop is a choice made by default, not a banned technique; how the evaluator and the agent weigh a finding against the declared visual concept.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, concept, relative, allowances, judgement]\nphases: [concept, build, review]\npriority: 5\nrelated: [core-visual-concept-first, style-combining]\nversion: 1\n---\nNothing on these lists is forbidden. A gradient, a pill button, glass panels, a bento grid or a marquee can all be right. They become slop when they appear **because they are the default**, not because the concept chose them.\n\n**How judgement works**\n- The visual concept declares styles, signature moves and explicit allowances (`allow: [\"gradients\", \"glass\"]`). A finding that matches an allowance is downgraded to info.\n- Style implies allowances: glassmorphism allows blur; neo brutalism allows offset shadows and thick borders; playful allows pills and larger radius; dark cinematic allows dark backgrounds and a single soft light; experimental allows unusual layout and motion.\n- What the creator explicitly asked for always wins.\n- Some findings are never excused by a concept: fabricated proof, weak mobile, missing reduced motion, empty marketing words, contrast failures.\n\n**When reviewing**: for each finding, ask \"did the concept choose this?\" If yes, check it is executed well (see the style entry). If no, apply the fix.\n\nThe evaluator lives at `lib/ai-builder/slop.ts` (`evaluateSlop`, and `slopIssues` for the agent's validate step).\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-repetitive-structure.md",
  "source": "---\nid: anti-slop-repetitive-structure\ntitle: Repetitive section structures\ncategory: anti-slop\nsummary: Every section built the same way (centred heading, paragraph, grid of three) so the page has no rhythm.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, repetition, sections, rhythm, same-layout]\nphases: [concept, build, review]\npriority: 4\nrelated: [core-content-hierarchy, layout-spacing-rhythm]\nversion: 1\n---\n**The pattern**: section after section with the same skeleton: centred heading, centred sub paragraph, grid of equal items. Or the same image left, text right row repeated four times.\n\n**Evaluator checks**: a structural fingerprint per section (heading alignment, element sequence, grid column count); three or more consecutive sections with the same fingerprint, or more than half the page sharing one.\n\n**Fix**: vary deliberately: a full bleed image band after a dense list; left aligned text after a centred statement; one large item instead of three small; a quote set huge; a table instead of cards. Each section's form should come from its content.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-stock-imagery.md",
  "source": "---\nid: anti-slop-stock-imagery\ntitle: Stock image clichés\ncategory: anti-slop\nsummary: Handshakes, laptops with coffee, people pointing at screens, generic gym models: why they hurt and how to direct imagery instead.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, stock-photos, imagery, unsplash, cliche, photography]\nphases: [concept, build, review]\npriority: 3\nrelated: [core-visual-concept-first, responsive-images]\nversion: 1\n---\n**Clichés**: handshake, team high five, laptop and coffee flat lay, person pointing at a whiteboard, smiling headset support agent, lightbulb, rocket, puzzle pieces, glowing brain, generic city skyline, model lifting a dumbbell in a clean gym, lotus pose on a beach.\n\n**Evaluator checks**: image alt text and file names matching cliché terms; the same placeholder service used for every image; hero images with no relation to the stated industry.\n\n**Fix**: use the creator's own photos first. When searching open licence images (the AI builder uses Openverse), write queries from the concept's imagery direction: subject, light, crop, mood (\"chalk dusted hands on a barbell, side light, close crop\"). Fewer, better images beat many generic ones. Credit images as their licence requires.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-typography-chaos.md",
  "source": "---\nid: anti-slop-typography-chaos\ntitle: Inconsistent typography\ncategory: anti-slop\nsummary: Too many font families, sizes and weights, arbitrary pixel values, and headings that do not follow a scale.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, fonts, font-sizes, font-families, type-scale, typography]\nphases: [concept, build, review]\npriority: 4\nrelated: [typography-scale, typography-pairings]\nversion: 1\n---\n**Signals**: more than two families (plus a mono), more than about 8 to 10 distinct font sizes on a page, sizes like 13px, 15px, 17px, 19px, 21px all used together, weights 300 to 900 all present, headings of the same level at different sizes in different sections.\n\n**Evaluator checks**: unique `font-family` stacks (by first family), unique `font-size` values, unique `font-weight` values, compared with the concept's type system.\n\n**Fix**: define the scale (typography-scale) and map every text style to it as tokens (`--step-0` to `--step-5`); two families; three weights. Replace near duplicates (15 and 16px) with one value. Headings at the same level look the same everywhere.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-unbalanced-spacing.md",
  "source": "---\nid: anti-slop-unbalanced-spacing\ntitle: Unbalanced spacing\ncategory: anti-slop\nsummary: Arbitrary spacing values, random section padding, cramped groups next to huge gaps; signals and fixes.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, spacing, padding, margins, whitespace, arbitrary-values]\nphases: [concept, build, review]\npriority: 3\nrelated: [layout-spacing-rhythm]\nversion: 1\n---\n**Signals**: many unique margin and padding values (13px, 27px, 42px, 70px), sections with wildly different padding for no reason, related items far apart and unrelated ones close, padding on phones equal to desktop.\n\n**Evaluator checks**: unique spacing values in CSS and how many are off the 4px grid; section padding variance; absence of smaller spacing in phone media queries.\n\n**Fix**: a spacing scale (4, 8, 12, 16, 24, 32, 48, 64, 96, 128) as tokens; fluid section padding with clamp; proximity rules (closer inside a group, larger between groups). Deliberate variation (a tight band, a spacious hero) is fine when named in the concept.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-unnecessary-animation.md",
  "source": "---\nid: anti-slop-unnecessary-animation\ntitle: Unnecessary animation\ncategory: anti-slop\nsummary: Everything fading, floating, pulsing or bouncing; infinite loops; animations without reduced motion; how much motion the concept allows.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, animation, motion, overanimation, reduced-motion, infinite]\nphases: [concept, build, review]\npriority: 4\nrelated: [motion-principles, a11y-motion-media]\nversion: 1\n---\n**Signals**: infinite animations on decorative elements (floating cards, pulsing buttons, rotating badges), entrance animations on every element, long durations over 1s for UI, animated gradients, missing `prefers-reduced-motion` handling.\n\n**Evaluator checks**: number of `@keyframes` and infinite animations, number of elements with transitions or reveal attributes, durations, and whether a reduced motion query exists. Compared against the concept's motion stance (none, subtle, expressive, cinematic).\n\n**Fix**: keep motion that explains or confirms; keep at most one ambient loop and only if the concept is expressive or cinematic; shorten UI transitions to under 300ms; add reduced motion handling. Missing reduced motion support is never excused by a concept.\n"
 },
 {
  "file": "entries/anti-slop/anti-slop-weak-mobile.md",
  "source": "---\nid: anti-slop-weak-mobile\ntitle: Weak mobile\ncategory: anti-slop\nsummary: Desktop layouts shrunk onto phones: no media queries, fixed widths, tiny text, side scrolling, hover only actions.\nintents: [review, anti-slop, redesign]\ntags: [anti-slop, slop, generic, mobile, responsive, media-queries, phone]\nphases: [concept, build, review]\npriority: 5\nrelated: [responsive-mobile-first, responsive-touch]\nversion: 1\n---\n**Signals**: no `@media` or `@container` rules in a multi column layout; fixed widths over 400px; `grid-template-columns: repeat(3, 1fr)` with no smaller alternative; font sizes under 14px for body; `100vw` widths; hover reveal of actions; tap targets under 44px.\n\n**Evaluator checks**: presence of responsive rules relative to layout complexity, fixed pixel widths, multi column grids without a fallback, tiny font sizes.\n\n**Fix**: write phone styles as the base (responsive-mobile-first); add breakpoints for wider screens; use `minmax` and `auto-fill`; fluid type; check 320 and 375px widths for overflow.\n\nNever excused by a concept.\n"
 },
 {
  "file": "entries/color/color-accent-use.md",
  "source": "---\nid: color-accent-use\ntitle: Using an accent colour with discipline\ncategory: color\nsummary: Where an accent belongs (primary actions, focus, one signature element), how much of the page it should cover, and how to avoid accent everywhere.\nintents: [choose-palette, review]\ntags: [accent, brand-colour, highlight, cta-colour, 60-30-10]\nphases: [plan, build, review]\npriority: 4\nrelated: [color-palettes-by-mood, anti-slop-purple-gradients]\nversion: 1\n---\nAn accent works by scarcity. If everything is accented, nothing is.\n\n**Belongs on**: the primary action, the focus ring, links in body text, the active state of navigation, one signature element per page (a date, a price highlight, a rule).\n\n**Coverage**: roughly 60% background neutrals, 30% text and secondary surfaces, under 10% accent. A full accent band (one section with an accent background) is fine once per page as a rhythm change.\n\n**Don't**: colour every icon, heading and border with the accent; use the accent for both success messages and primary buttons (users read colour as meaning); use a second accent for decoration.\n\n**States**: hover darkens or lightens the accent by about 8 to 12% lightness; active by about 15%; disabled drops to a neutral, not a faded accent.\n\n```css\n.btn-primary { background: var(--accent); color: var(--accent-text); }\n.btn-primary:hover { background: color-mix(in oklab, var(--accent), black 10%); }\n```\n"
 },
 {
  "file": "entries/color/color-contrast-rules.md",
  "source": "---\nid: color-contrast-rules\ntitle: Contrast rules that are not negotiable\ncategory: color\nsummary: WCAG thresholds for text, large text, UI components and focus, common failures (grey on white, text on photos) and fixes.\nintents: [choose-palette, review, fix-accessibility]\ntags: [contrast, wcag, accessibility, legibility, overlay]\nphases: [build, review, repair]\npriority: 5\nrelated: [a11y-checklist, color-palettes-by-mood]\nversion: 1\n---\n- Body text: at least **4.5:1**. Large text (24px regular or 18.66px bold and up): at least **3:1**.\n- Interactive component boundaries and icons that convey meaning: **3:1** against adjacent colours.\n- Focus indicator: **3:1** against both the component and the background.\n- Placeholder text is still text: 4.5:1 if it carries information, and never the only label.\n- Disabled controls are exempt, but must still look clearly disabled.\n\n**Common failures and fixes**\n- `#999` on white is 2.8:1. Use `#595959` (7:1) or `#6b6b6b` (5.3:1) for muted text.\n- White text on a photo: add an overlay sized to the text area (`linear-gradient(to top, rgba(0,0,0,.6), transparent 60%)`) or a solid backing; check the brightest part of the image behind the text.\n- Accent buttons: a light accent (yellow, mint) needs dark button text. Compute; do not guess.\n- Dark mode muted text: `#8a8a8a` on `#0e0e10` passes; `#666` does not.\n\nThe Storelib theme has a contrast checker (lib/storelib-theme/contrast.ts); colour schemes must pass its read pairs.\n"
 },
 {
  "file": "entries/color/color-dark-mode.md",
  "source": "---\nid: color-dark-mode\ntitle: Dark palettes and dark sections\ncategory: color\nsummary: Building dark surfaces with layered greys, reducing saturation of accents, image treatment and contrast pitfalls on dark backgrounds.\nintents: [choose-palette, build-section]\ntags: [dark-mode, dark, night, surfaces, elevation]\nstyles: [dark-cinematic]\nphases: [plan, build]\npriority: 3\nrelated: [style-dark-cinematic, color-contrast-rules]\nversion: 1\n---\n- **Not pure black** for large areas: `#0e0e10` to `#161618`. Pure black next to white text causes halation for many readers.\n- **Elevation by lightness**, not shadow: background `#0e0e10`, surface `#18181b`, raised `#222226`. Shadows barely show on dark.\n- **Text**: off white `#ecebe8` for body, `#a1a1a6` for muted (check 4.5:1).\n- **Accents**: desaturate slightly; fully saturated colours vibrate on dark. Pastels or warm metallics read better.\n- **Borders**: `rgba(255,255,255,.08)` to `.14`.\n- **Images**: reduce the brightness of very bright photos a little (`filter: brightness(.92)`) so they do not overpower; never invert.\n- **Mixed pages**: alternating light and dark sections creates rhythm (the Storelib presets' sectionRhythm does this). Two dark sections in a row are fine; switching every section is tiring.\n"
 },
 {
  "file": "entries/color/color-imagery-led.md",
  "source": "---\nid: color-imagery-led\ntitle: Taking colour from imagery and product\ncategory: color\nsummary: Deriving the palette from the creator's photos, cover art or products so the site and its imagery feel like one thing.\nintents: [choose-palette, build-site]\ntags: [palette, imagery, cover-art, brand, extraction]\nphases: [concept, plan]\npriority: 3\nrelated: [color-palettes-by-mood, industry-music-producer, industry-fashion]\nversion: 1\n---\nWhen a creator has strong imagery (album covers, product photography, a signature wardrobe), the palette should come from it, not from a preset.\n\n**Method**: pick the dominant dark (becomes text or dark surface), the dominant light (background), and one saturated colour that appears in small amounts (accent). Ignore colours that appear in only one image.\n\n**Per collection or release**: let a collection page or a release page take its accent from its own cover, while the site frame stays neutral. Pass the accent as a section colour setting so the creator can change it.\n\n**Check**: the derived accent still needs a contrast safe text colour on top; derived greys still need 4.5:1 for text.\n\n**Do not** sample colours that only exist because of a bad white balance, or a stock photo's colours. Real brand material only.\n"
 },
 {
  "file": "entries/color/color-neutrals-and-surfaces.md",
  "source": "---\nid: color-neutrals-and-surfaces\ntitle: Neutrals, surfaces and borders\ncategory: color\nsummary: Picking warm or cool greys, surface steps, border strength and how to separate areas without cards and shadows.\nintents: [choose-palette, build-section]\ntags: [neutrals, greys, surfaces, borders, background, separation]\nphases: [plan, build]\npriority: 3\nrelated: [color-palettes-by-mood, anti-slop-floating-cards]\nversion: 1\n---\n- **Temperature**: tint neutrals toward the brand. Warm brands use greys with a little yellow or red (`#f4f1ec`, `#e7e2da`, `#5f5a52`); cool brands use blue grey (`#eef1f4`, `#d9dee4`, `#56606b`). Pure `#f5f5f5` greys look default.\n- **Surface steps**: background, one surface step (about 3 to 5% darker or lighter), one border. Three levels are enough for almost any site.\n- **Borders**: 1px at about 1.3:1 to 1.6:1 against the background for structure lines; stronger (3:1) for input boundaries.\n- **Separation without cards**: whitespace, a hairline rule, a change in background between sections, alignment. Use a card only when the item is a distinct, clickable object (a product, a post, a plan).\n- **Shadows**: if used, one soft elevation (`0 1px 2px rgba(0,0,0,.06), 0 4px 12px rgba(0,0,0,.05)`) for raised overlays like menus and dialogs, not for every block.\n"
 },
 {
  "file": "entries/color/color-palettes-by-mood.md",
  "source": "---\nid: color-palettes-by-mood\ntitle: Palettes by mood\ncategory: color\nsummary: Ready palettes (background, surface, text, muted, accent) for common moods with hex values that pass contrast, and how to adapt one from a brand colour.\nintents: [choose-palette, choose-style, build-site]\ntags: [palette, colour, color, mood, scheme, hex]\nphases: [concept, plan]\npriority: 5\nrelated: [color-contrast-rules, color-accent-use, editorial_ink, quiet_luxury]\nversion: 1\n---\nEach row: background / surface / text / muted text / accent. All text pairs pass 4.5:1 on the background.\n\n| Mood | Values |\n| --- | --- |\n| Warm editorial | `#f7f3ec` / `#efe8dc` / `#1d1a16` / `#5c554b` / `#a33b20` |\n| Quiet luxury | `#f4f1ea` / `#e9e4da` / `#1c1b19` / `#5d5952` / `#5a1a1a` |\n| Mineral calm | `#eceae6` / `#dfddd8` / `#22272a` / `#53595c` / `#2f6f6a` |\n| Swiss signal | `#ffffff` / `#f2f2f2` / `#111111` / `#555555` / `#d92b1c` |\n| Night cinema | `#0e0e10` / `#18181b` / `#ecebe8` / `#9a9a9f` / `#e0a050` |\n| Forest | `#13201b` / `#1c2c25` / `#e7efe9` / `#a5b6ad` / `#d9b26b` |\n| Pop | `#fff8ec` / `#ffe9c7` / `#1a1a1a` / `#4d4d4d` / `#ff4f8b` |\n| Workshop | `#f1f0ec` / `#e4e2dc` / `#1b1b1b` / `#575757` / `#ff5a1f` |\n\n**From a brand colour**: keep the brand colour as the accent. Derive neutrals by mixing a little of its hue into grey (warm brand, warm greys). Check the accent against both background and the text you will put on it.\n\n**Count**: background, surface, text, muted, border, accent, and accent text. Seven tokens. Add a second accent only if the concept names a reason.\n"
 },
 {
  "file": "entries/component/component-accordion.md",
  "source": "---\nid: component-accordion\ntitle: Accordions and FAQs\ncategory: component\nsummary: Disclosure lists with details and summary, animation of height, icons, first item open and FAQ content rules.\nintents: [build-component, build-section]\ntags: [accordion, faq, details, summary, disclosure, collapse, expand]\ncomponents: [accordion, faq]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [state-interactive-matrix, faq, curriculum]\nversion: 1\n---\n**Native first**: `<details>` and `<summary>` are keyboard and screen reader accessible with no JS.\n\n```html\n<details class=\"faq\" {% if forloop.first and settings.first_open %}open{% endif %}>\n  <summary>{{ block.settings.question }}</summary>\n  <div class=\"answer\">{{ block.settings.answer }}</div>\n</details>\n```\n```css\n.faq summary { list-style: none; cursor: pointer; padding: 18px 0; display: flex; justify-content: space-between; gap: 16px; font-weight: 500; }\n.faq summary::-webkit-details-marker { display: none; }\n.faq summary::after { content: \"+\"; transition: transform .2s; }\n.faq[open] summary::after { transform: rotate(45deg); }\n.faq summary:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }\n```\n\n**Animating height**: `interpolate-size: allow-keywords` with `::details-content` transitions where supported; otherwise animate the answer's opacity and translate only. Instant under reduced motion.\n\n**States**: collapsed, expanded, hover, focus. The indicator must change shape, not only colour.\n\n**FAQ content**: real questions people ask (delivery, refunds, level, access), answered in two or three sentences. Questions come from blocks so the creator can edit them.\n"
 },
 {
  "file": "entries/component/component-buttons.md",
  "source": "---\nid: component-buttons\ntitle: Buttons\ncategory: component\nsummary: Button hierarchy, sizes, every state with CSS, icon buttons, and when a link is the right element.\nintents: [build-component, build-section]\ntags: [button, cta, action, link-button]\ncomponents: [button, cta]\ncapabilities: []\nphases: [build, review]\npriority: 5\nrelated: [state-interactive-matrix, color-accent-use]\nversion: 1\n---\n**Element**: `<button>` for actions on the page, `<a href>` for navigation. Never a div with a click handler.\n\n**Hierarchy**: one primary (filled) per view, secondary (outline or tonal), tertiary (text with underline). Destructive actions get their own style, not the accent.\n\n**Sizes**: height 40 to 48px desktop, at least 44px on touch; horizontal padding 16 to 24px; text 15 to 16px medium. Radius follows the concept (0 to 10px typically; pills only when the concept uses them throughout).\n\n**States**\n```css\n.btn { background: var(--accent); color: var(--accent-text); border: 0; border-radius: var(--radius-btn, 6px); padding: 12px 20px; font: 500 1rem/1.2 var(--font-body); cursor: pointer; transition: background-color .15s, transform .1s; }\n.btn:hover { background: color-mix(in oklab, var(--accent), black 10%); }\n.btn:active { transform: translateY(1px); }\n.btn:focus-visible { outline: 2px solid var(--focus, currentColor); outline-offset: 3px; }\n.btn:disabled, .btn[aria-disabled=\"true\"] { background: var(--muted-bg); color: var(--muted); cursor: not-allowed; transform: none; }\n.btn[data-loading=\"true\"] { color: transparent; position: relative; pointer-events: none; }\n@media (prefers-reduced-motion: reduce) { .btn { transition: none; } }\n```\n\n**Loading**: keep the width (no jump), show a spinner or the label \"Saving\", set `aria-busy=\"true\"`.\n\n**Copy**: verb plus object (\"Book a session\"). No \"Click here\", no \"Learn more\" five times on a page.\n"
 },
 {
  "file": "entries/component/component-cards.md",
  "source": "---\nid: component-cards\ntitle: Cards\ncategory: component\nsummary: When a card is the right container, anatomy, clickable cards done accessibly, and avoiding cards inside cards.\nintents: [build-component, build-section]\ntags: [card, tile, item, grid-item]\ncomponents: [card]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [anti-slop-floating-cards, color-neutrals-and-surfaces]\nversion: 1\n---\n**Use a card** when the item is a distinct object with several attributes that people compare or open: a product, a post, a plan, an event. Not for every paragraph.\n\n**Anatomy**: media (consistent ratio), title, one or two meta lines, optional action. Visual containment by background or border, or none at all (image plus text aligned to a grid is often better).\n\n**Whole card clickable**: put the link on the title and stretch it, so screen readers hear one link:\n\n```css\n.card { position: relative; }\n.card a.title::after { content: \"\"; position: absolute; inset: 0; }\n.card:focus-within { outline: 2px solid var(--focus); outline-offset: 2px; }\n```\nSecondary buttons inside need `position: relative; z-index: 1` to stay clickable.\n\n**Grids**: equal heights by grid, not fixed heights; clamp long titles to 2 or 3 lines (`-webkit-line-clamp`). Number of columns from the content count, not always three.\n\n**Avoid**: card inside card, shadows plus borders plus radius plus gradients on one card, icon tiles on top of every card.\n"
 },
 {
  "file": "entries/component/component-carousel.md",
  "source": "---\nid: component-carousel\ntitle: Carousels and sliders\ncategory: component\nsummary: When a carousel is worth it, accessible controls, no autoplay by default, and native scroll snap instead of heavy libraries.\nintents: [build-component, build-section]\ntags: [carousel, slider, slideshow, swiper, rail]\ncomponents: [carousel, slider]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [layout-horizontal-scroll, motion-principles]\nversion: 1\n---\n**Question first**: would a grid or a scroll row show the content better? Carousels hide content; most visitors see only the first slide.\n\n**Good uses**: product image galleries on phones, a row of related products, a lookbook sequence, reviews when there are many real ones.\n\n**Requirements**\n- Previous and next buttons with labels (\"Previous slide\"), at least 44px.\n- Slide position announced (\"3 of 7\") via a visually hidden live region or visible counter.\n- Swipe on touch (native scroll snap gives this), arrow keys when focused.\n- **No autoplay** by default. If the creator asks for it: pause on hover and focus, a visible pause button, at least 5 seconds per slide, disabled under reduced motion.\n\n**Implementation**: a scroll snap rail (see layout-horizontal-scroll) plus buttons that scroll by one slide width. Embla (already a dependency in the app) is fine inside the app; generated sections should use native scroll.\n\n**Avoid**: fade carousels for hero messages (\"slider heroes\"); dots as the only control; infinite loops that clone slides confusing screen readers.\n"
 },
 {
  "file": "entries/component/component-charts.md",
  "source": "---\nid: component-charts\ntitle: Charts and data display\ncategory: component\nsummary: Charts only for real data: chart choice, colour, labels, accessibility, and why marketing pages rarely need them.\nintents: [build-component, build-section]\ntags: [chart, graph, data-viz, stats, numbers]\ncomponents: [chart]\ncapabilities: []\nphases: [build, review]\npriority: 2\nrelated: [anti-slop-fake-proof, component-tables]\nversion: 1\n---\n**Only with real data** from the store or supplied by the creator. Decorative charts with invented trends are fabricated proof.\n\n**Choice**: bars for comparing categories, lines for change over time, a single big number with context for one figure. Avoid pie charts with more than 3 slices, 3D, dual axes.\n\n**Style**: direct labels instead of legends where possible, one highlight colour with the rest in neutrals, gridlines light, axis starts at zero for bars.\n\n**Accessibility**: a text summary of the takeaway, the data available as a table, patterns or labels not colour alone, SVG with `role=\"img\"` and an `aria-label`.\n\n**In the app**: Recharts is a dependency of the Storelib app (dashboards). Generated site sections should render simple charts in SVG or CSS themselves.\n"
 },
 {
  "file": "entries/component/component-dialog.md",
  "source": "---\nid: component-dialog\ntitle: Dialogs and modals\ncategory: component\nsummary: Native dialog element usage, focus management, sizes, when not to use a modal, and newsletter popup rules.\nintents: [build-component, build-section]\ntags: [dialog, modal, popup, lightbox, confirm]\ncomponents: [dialog, modal]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [component-drawer, a11y-keyboard-focus]\nversion: 1\n---\n**Prefer the native element**: `<dialog>` with `showModal()` gives focus trapping, Escape to close, and an inert background for free.\n\n```html\n<dialog id=\"size-guide-{{ section.id }}\" aria-labelledby=\"sg-title-{{ section.id }}\">\n  <h2 id=\"sg-title-{{ section.id }}\">Size guide</h2>\n  ...\n  <form method=\"dialog\"><button>Close</button></form>\n</dialog>\n```\n```css\ndialog { border: 0; border-radius: 12px; padding: 24px; width: min(560px, calc(100vw - 32px)); max-height: calc(100svh - 32px); }\ndialog::backdrop { background: rgb(0 0 0 / .5); }\n```\n\n**Focus**: the opening button gets focus back on close. Initial focus on the first meaningful control (or the dialog heading for long content).\n\n**When not to**: do not use modals for content that deserves a page, for multi step flows, or as an interruption on page load. A newsletter popup, if the creator wants one, waits for real engagement (scroll 50% or 30 seconds), shows once per session, and closes easily.\n\n**Phones**: large dialogs become bottom sheets or full screen.\n"
 },
 {
  "file": "entries/component/component-drawer.md",
  "source": "---\nid: component-drawer\ntitle: Drawers and sheets\ncategory: component\nsummary: Side drawers and bottom sheets for carts, filters and menus: sizes, focus, scroll lock, drag to close and the Storelib cart panel.\nintents: [build-component, build-section]\ntags: [drawer, sheet, side-panel, bottom-sheet, cart-drawer]\ncomponents: [drawer, sheet]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [component-dialog, storelib-checkout-cta, header-mobile-menu]\nversion: 1\n---\n**Uses**: cart, filters, menu, quick view. Content that relates to the current page and closes back to it.\n\n**Sizes**: side drawers 360 to 440px wide desktop, 85 to 100% on phones. Bottom sheets up to 90svh with a visible handle and rounded top corners.\n\n**Behaviour**: same as a modal: focus moves in, trapped, Escape and backdrop close, focus returns. Lock page scroll; let the drawer body scroll with `overscroll-behavior: contain`. Use `inert` on the page behind.\n\n**Motion**: slide 250 to 320ms ease out on open, 200ms on close; backdrop fades. Instant under reduced motion.\n\n**Bottom sheet safe area**: `padding-bottom: calc(16px + env(safe-area-inset-bottom))`.\n\n**Storelib cart**: a section can provide its own cart panel (`data-storelib-cart-panel` with `data-open`), lines from the real cart template, subtotal and a checkout button; the built-in drawer is used otherwise.\n"
 },
 {
  "file": "entries/component/component-forms.md",
  "source": "---\nid: component-forms\ntitle: Forms\ncategory: component\nsummary: Short forms that work: field count, layout, submit behaviour, success and error states, spam and Storelib form binding.\nintents: [build-component, build-section]\ntags: [form, contact-form, enquiry, signup, booking-form, multi-step]\ncomponents: [form]\nphases: [build, review]\npriority: 5\nrelated: [component-inputs, state-form-validation, storelib-forms]\nversion: 1\n---\n**Fewer fields**: every field costs completions. Contact: name, email, message. Enquiry: add one question that routes the request. Ask for phone only if you will call.\n\n**Layout**: one column. Two short related fields side by side only on desktop (first and last name). Labels above fields. Submit button aligned with the fields, full width on phones.\n\n**Submit flow**\n1. Validate on submit, then live once a field has been touched and is invalid.\n2. Submitting: disable the button, label \"Sending\", `aria-busy` on the form.\n3. Success: replace the form with a confirmation that says what happens next (\"Thanks, Maya will reply within two days\"), move focus to it.\n4. Error: keep all values, show a message at the top listing problems with links to fields, plus messages under each field.\n\n**Multi step**: only for long forms (booking with options). Show step count, keep back navigation, save progress.\n\n**Storelib**: forms are real Storelib forms (`data-storelib-form`, or a form picker); submissions reach the creator's responses. Never a `<form action=\"#\">` that goes nowhere, never a mailto as the only route. Honeypot and rate limits are handled by the form engine.\n"
 },
 {
  "file": "entries/component/component-gallery.md",
  "source": "---\nid: component-gallery\ntitle: Image galleries and lightboxes\ncategory: component\nsummary: Gallery layouts for different ratios, lightbox behaviour, captions, lazy loading and image sizes.\nintents: [build-component, build-section]\ntags: [gallery, lightbox, images, photos, grid]\ncomponents: [gallery, lightbox]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [layout-masonry, industry-photography, gallery]\nversion: 1\n---\n**Layouts**: uniform grid (one ratio, cropping acceptable for products), masonry or justified (mixed ratios, no cropping), editorial sequence (varied sizes with captions).\n\n**Images**: `width` and `height` attributes always (prevents layout shift); `loading=\"lazy\"` except the first row; `srcset` and `sizes` that match the column width (`sizes=\"(min-width: 1000px) 33vw, 50vw\"`); `alt` describing the content, or empty `alt=\"\"` for purely decorative repeats.\n\n**Lightbox**: opens as a modal dialog; arrows and swipe for next and previous; Escape closes; focus returns to the thumbnail; image fits the viewport (`object-fit: contain`, max 100svh); caption and counter visible; preload the next image only.\n\n**Hover**: subtle (scale 1.02 to 1.04 inside an overflow clip, or a caption reveal). No heavy zoom or rotations.\n\n**Storelib**: gallery images are block image_pickers the creator manages, not hard coded URLs.\n"
 },
 {
  "file": "entries/component/component-hero.md",
  "source": "---\nid: component-hero\ntitle: Hero sections\ncategory: component\nsummary: Hero types matched to purpose (immersive, editorial, split, product, statement), what belongs in the first screen and how to avoid the generic hero.\nintents: [build-component, build-section]\ntags: [hero, above-the-fold, first-screen, intro, banner]\ncomponents: [hero]\ncapabilities: []\nphases: [build, review]\npriority: 5\nrelated: [hero_immersive, hero_editorial, hero_split, hero_product, anti-slop-generic-hero]\nversion: 1\n---\n**Choose by purpose**\n- *Immersive*: the image is the product (venues, travel, fashion). Full bleed, short heading, one action.\n- *Editorial*: type and one photograph composed as a spread. For considered brands.\n- *Split*: promise one side, proof or product picture the other. For services and courses.\n- *Product*: one product with price and buy, above the fold.\n- *Statement*: a large typographic line, no image. For studios and writers.\n\n**First screen must contain**: what it is, who it is for (explicit or obvious), the one action. On phones: heading, one line, the button within about 560px of height.\n\n**Heading**: specific to the business (see core-copywriting); 3 to 10 words.\n\n**Avoid the default**: centred eyebrow pill, two line gradient heading, grey paragraph, two buttons side by side, a screenshot floating with glow, logos strip. If your hero matches that list, pick another type.\n\n**Media**: preload the hero image (`fetchpriority=\"high\"`, no lazy loading), sized for the viewport with srcset.\n"
 },
 {
  "file": "entries/component/component-inputs.md",
  "source": "---\nid: component-inputs\ntitle: Text inputs and fields\ncategory: component\nsummary: Field anatomy (label, control, hint, error), sizes, every state, input types and autocomplete for fast entry.\nintents: [build-component, build-section]\ntags: [input, text-field, select, checkbox, radio, textarea, field]\ncomponents: [input, select, checkbox, radio, textarea]\ncapabilities: []\nphases: [build, review]\npriority: 5\nrelated: [component-forms, state-form-validation]\nversion: 1\n---\n**Anatomy**: visible label above, the control, optional hint, error message slot. Placeholder is an example, not the label.\n\n```html\n<div class=\"field\">\n  <label for=\"email-{{ section.id }}\">Email</label>\n  <input id=\"email-{{ section.id }}\" name=\"email\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" required aria-describedby=\"email-hint-{{ section.id }}\">\n  <p id=\"email-hint-{{ section.id }}\" class=\"hint\">We only use it to send your booking.</p>\n</div>\n```\n\n**Specs**: height 44 to 48px; font 16px minimum (smaller zooms the page on iOS); border 1px at 3:1 contrast; radius matching buttons.\n\n**States**: hover (border darker), focus-visible (2px ring), filled, disabled (muted background, not just lower opacity), invalid (`aria-invalid=\"true\"`, red border plus icon plus message; never colour alone), read only.\n\n**Types**: `email`, `tel`, `url`, `number` only for quantities (not phone numbers or card numbers), `date` where native pickers are acceptable. Use `autocomplete` tokens (name, email, tel, street-address, postal-code).\n\n**Choices**: radios for 2 to 5 options visible at once; a select for longer lists; checkboxes for independent options. Group with `<fieldset>` and `<legend>`.\n"
 },
 {
  "file": "entries/component/component-interactive-library.md",
  "source": "---\nid: component-interactive-library\ntitle: Interactive components that run in Storelib, ready to adapt\ncategory: component\nsummary: Fourteen complete .storelib sections for the interactions sites keep asking for (reveals, marquee, sticky stack, sideways gallery, hover index, staggered text, before and after, tabs, accordion, counters, parallax, video opening, own header and footer); ask search_knowledge for one by id.\nintents: [build-section, add-motion, add-interaction, build-header, build-footer, build-site]\ntags: [interactive, example, examples, components, working code, marquee, tabs, accordion, faq, slider, before after, gallery, sticky, parallax, counters, video, mega menu, mobile menu, cart drawer, search, popover, scroll reveal]\ncomponents: [header, footer, tabs, accordion, carousel, gallery, hero, stats]\nphases: [plan, build]\npriority: 5\nrelated: [motion-in-storelib-runtime, storelib-own-chrome, motion-principles, component-tabs, component-accordion]\nversion: 1\n---\nAsk search_knowledge with the id to get the whole file (template, scoped style, script when needed, schema). Each one compiles, draws and passes the checks your files are held to. Adapt type, colour, spacing, words and the ai_ name to the concept; never paste one unchanged, and never use more than two or three kinds of motion on a page.\n\n| Id | What it is | How it works |\n| --- | --- | --- |\n| ai_scroll_reveal | chapters that rise into view | CSS view timeline, still without support |\n| ai_marquee | a running line of real words | CSS loop, paused on hover and focus, wraps still for reduced motion |\n| ai_sticky_stack | panels that stick and stack | position sticky with a growing top |\n| ai_hscroll_gallery | sideways gallery with a progress line | scroll snap, focusable track, named scroll timeline |\n| ai_hover_reveal_list | text index, image of the hovered row | :hover, :focus-within and :has() |\n| ai_split_text | staggered headline, one line per block | CSS delays per line |\n| ai_before_after | compare two photos | a real range input and a three line script |\n| ai_tabs | tabs with arrow keys and no script | a radio group and :has() |\n| ai_faq_accordion | questions, one open at a time | details name and ::details-content |\n| ai_counters | figures that count up | @property integer and a view timeline, real numbers only |\n| ai_parallax_media | a full bleed photo that drifts | view timeline on a transform |\n| ai_video_hero | an opening over the creator's video | native controls so it can be paused |\n| ai_site_header | own header: mega menu, mobile menu, search window, cart drawer, language and currency | popover API and the page's hooks |\n| ai_site_footer | own footer: sign up, two menus, language and currency, the name set huge | data-storelib-form subscribe and the page's hooks |\n\n**Why these techniques**: a section's script runs in a sandbox on a copy of its markup, so it cannot measure the page, observe intersections, focus elements or play a video. Scroll-driven CSS, :has(), details, popover and sticky run on the real page with no script, work by keyboard, and are easy to switch off under prefers-reduced-motion.\n"
 },
 {
  "file": "entries/component/component-loading.md",
  "source": "---\nid: component-loading\ntitle: Loading indicators and skeletons\ncategory: component\nsummary: Choosing between spinners, skeletons and progress bars, timing thresholds, and avoiding layout shift.\nintents: [build-component, build-section]\ntags: [loading, spinner, skeleton, progress, shimmer, placeholder]\ncomponents: [loading, skeleton, spinner, progress]\ncapabilities: []\nphases: [build, review]\npriority: 3\nrelated: [state-async, motion-loading]\nversion: 1\n---\n**Thresholds**: under about 300ms show nothing (a flash of spinner looks worse); 300ms to 2s spinner or skeleton; over 2s a progress indicator with text, and over about 10s, what is happening and the option to keep browsing.\n\n**Skeletons**: match the final layout exactly (same sizes and ratios) so content replaces them without shift. Neutral blocks at low contrast; shimmer optional and stopped under reduced motion.\n\n```css\n.skeleton { background: var(--surface); border-radius: 4px; }\n@media (prefers-reduced-motion: no-preference) { .skeleton { background: linear-gradient(90deg, var(--surface) 0, var(--surface-2) 50%, var(--surface) 100%) 0 0 / 200% 100%; animation: sk 1.4s linear infinite; } }\n@keyframes sk { to { background-position: -200% 0; } }\n```\n\n**Spinners**: inside the element that is busy (a button), with `aria-busy=\"true\"` on the region and a text alternative.\n\n**Pages**: do not put full page preloaders in front of content that is already rendered; they only delay it.\n"
 },
 {
  "file": "entries/component/component-media-player.md",
  "source": "---\nid: component-media-player\ntitle: Audio and video players\ncategory: component\nsummary: Audio previews and video: native controls or custom ones that are accessible, one player at a time, no autoplay with sound.\nintents: [build-component, build-section]\ntags: [audio, video, player, preview, waveform, embed]\ncomponents: [media-player, audio, video]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [industry-music-producer, motion-performance]\nversion: 1\n---\n**Video**: `<video controls playsinline preload=\"metadata\" poster=\"...\">`. Background loops only muted, short (under 20s), compressed (under 3 to 5MB), paused when off screen and under reduced motion, with a visible pause button. Provide captions for speech.\n\n**Audio previews** (sample packs, beats): a play button per track with the track name as its label, duration, progress that can be scrubbed by pointer and keyboard (`input type=\"range\"` styled works well), and only one track playing at a time.\n\n```js\nroot.querySelectorAll('audio').forEach(a => a.addEventListener('play', () => root.querySelectorAll('audio').forEach(o => o !== a && o.pause())));\n```\n\n**Custom controls**: `<button aria-pressed>` or label switch Play and Pause; announce state; keyboard Space toggles when focused.\n\n**Embeds** (YouTube, Vimeo, SoundCloud): use Storelib's allowed embed path; lazy load with a click to load facade showing the poster to save weight; title attribute on iframes.\n\n**Never** autoplay audio.\n"
 },
 {
  "file": "entries/component/component-navigation-menus.md",
  "source": "---\nid: component-navigation-menus\ntitle: Navigation menus and dropdowns\ncategory: component\nsummary: Dropdown and mega menu behaviour: disclosure pattern, hover intent, keyboard, and reading the menu from the Storelib link list.\nintents: [build-component, build-section]\ntags: [menu, dropdown, mega-menu, submenu, navigation]\ncomponents: [navigation, menu, dropdown]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [header-mobile-menu, header-minimal]\nversion: 1\n---\n**Pattern**: site navigation submenus use the disclosure pattern (a button with `aria-expanded` that shows a list of links), not the ARIA `menu` role, which is for application menus.\n\n```html\n<li class=\"has-sub\">\n  <button aria-expanded=\"false\" aria-controls=\"sub-{{ forloop.index }}\">Shop</button>\n  <ul id=\"sub-{{ forloop.index }}\" hidden>{% for child in link.links %}<li><a href=\"{{ child.url | url }}\">{{ child.title }}</a></li>{% endfor %}</ul>\n</li>\n```\n\n**Behaviour**: click or Enter toggles; Escape closes and returns focus; clicking outside closes. On hover devices, open on hover with a 100 to 150ms intent delay and keep a hover bridge so the menu does not close when the pointer crosses the gap.\n\n**Mega menu**: only when there are many categories; group by real collections; include images only if they help choosing.\n\n**Storelib**: menus come from a link_list (`settings.menu.links`, children in `link.links`), never typed in markup.\n"
 },
 {
  "file": "entries/component/component-notifications.md",
  "source": "---\nid: component-notifications\ntitle: Notifications, toasts and banners\ncategory: component\nsummary: Feedback messages: inline alerts, toasts for background events, announcement bars, timing and live regions.\nintents: [build-component, build-section]\ntags: [toast, notification, alert, banner, announcement, snackbar]\ncomponents: [toast, alert, banner]\ncapabilities: []\nphases: [build, review]\npriority: 3\nrelated: [state-async, announcement]\nversion: 1\n---\n**Inline alert**: for messages about a specific area (form errors, payment problems). Stays until resolved. Icon plus text plus colour.\n\n**Toast**: brief confirmation of something that happened elsewhere (\"Added to bag\"). Appears bottom (phones) or bottom right, 4 to 6 seconds, pauses on hover and focus, dismiss button, never the only place important info appears. Announce with a polite live region (`role=\"status\"`).\n\n**Announcement bar**: one true line (shipping, next date). Dismissible if it is promotional. Not a rotating carousel of offers.\n\n**Errors that block**: `role=\"alert\"` (assertive) only for urgent problems.\n\n**Copy**: what happened and what to do next. \"Could not add to bag. Try again.\" not \"Oops! Something went wrong.\"\n"
 },
 {
  "file": "entries/component/component-pricing.md",
  "source": "---\nid: component-pricing\ntitle: Pricing and plans\ncategory: component\nsummary: Pricing layouts for one, two or three real offers, highlighting, billing periods, comparison tables and honest copy.\nintents: [build-component, build-section]\ntags: [pricing, plans, tiers, packages, membership-pricing, comparison]\ncomponents: [pricing, plans]\ncapabilities: [products]\nphases: [build, review]\npriority: 4\nrelated: [industry-saas, storelib-memberships, pricing]\nversion: 1\n---\n**Number of plans comes from the store.** One offer: a single focused panel with what is included. Two: side by side. Three: the classic row, with the recommended one marked only if the creator recommends it.\n\n**Each plan**: name, price with period (from the product), who it is for in one line, 3 to 7 included items (specific: \"4 live calls a month\", not \"Premium support\"), action.\n\n**Highlight**: a border or background shift and a text label \"Recommended\" (not a glowing gradient card raised 20px).\n\n**Billing toggle**: monthly and yearly only if both prices exist. Show the real difference, not an invented \"Save 20%\".\n\n**Comparison table**: for 3 or more plans with many features: rows of features, columns of plans, check marks with text alternatives, sticky header row on scroll.\n\n**Phones**: stack plans; put the recommended one first only if that matches the DOM order; keep the price visible near each button.\n\n**Avoid**: fake strikethrough prices, \"Most popular\" without data, more than 7 bullet points per plan.\n"
 },
 {
  "file": "entries/component/component-product-showcase.md",
  "source": "---\nid: component-product-showcase\ntitle: Product showcases\ncategory: component\nsummary: Presenting store products: grids, featured product sections, quick add, variant pickers, prices and availability from real data.\nintents: [build-component, build-section]\ntags: [product, product-grid, product-card, featured-product, shop, quick-add]\ncomponents: [product-card, product-grid, product-showcase]\ncapabilities: [products]\nphases: [build, review]\npriority: 5\nrelated: [storelib-products, style-contemporary-ecommerce, product_grid]\nversion: 1\n---\n**Featured product**: large gallery, name, real price (and compare at price if set), short description from the product, variant buttons, add to cart or buy now (checkout_url), delivery info from policies.\n\n**Grid card**: image (consistent ratio across the grid), name (2 lines max), price, optional second image on hover (desktop), sold out state from availability, quick add only for single variant products (otherwise open the product).\n\n**Variant pickers**: buttons (radio group semantics) for size and colour when there are few options; show unavailable options as disabled with a strike or label, never hidden silently; update price and image on change.\n\n**Prices**: print the formatted value from the store. Never compute, round or type a price. Compare at prices only from the product.\n\n**Buy buttons**: `data-storelib-add-to-cart` behind `{% if block.settings.available %}`; when unavailable, a disabled \"Sold out\" button.\n\n**Empty**: no products yet shows an editor only note (\"Your published products appear here\"), nothing for visitors.\n\n**Avoid**: star ratings with no reviews, \"Bestseller\" badges without data, countdown timers, fake stock counts.\n"
 },
 {
  "file": "entries/component/component-reviews.md",
  "source": "---\nid: component-reviews\ntitle: Reviews and ratings\ncategory: component\nsummary: Showing real reviews from the store: rating summary, review list, verification, empty state, and never fabricating.\nintents: [build-component, build-section]\ntags: [reviews, ratings, stars, product-reviews, social-proof]\ncomponents: [reviews, ratings]\ncapabilities: [products]\nphases: [build, review]\npriority: 4\nrelated: [anti-slop-fake-proof, component-testimonials]\nversion: 1\n---\n**Only real reviews.** Read them from the store. If there are none, show nothing (or an editor only placeholder), never a placeholder with stars.\n\n**Summary**: average to one decimal with the count (\"4.7 from 23 reviews\"); a distribution bar chart only with 10 or more reviews.\n\n**Stars**: rendered from the real value; accessible text \"Rated 4.7 out of 5\"; star icons `aria-hidden`.\n\n**List**: name or initials as given, date, rating, text, verified purchase mark if the data provides it. Show 3 to 5, then \"Show more\".\n\n**Sorting**: most recent and most helpful if the data supports it; never filter to only 5 star reviews by default.\n\n**Schema**: product rich results only with real aggregate ratings.\n"
 },
 {
  "file": "entries/component/component-stats.md",
  "source": "---\nid: component-stats\ntitle: Stats and numbers\ncategory: component\nsummary: Numbers as content: only real figures, how to set them typographically, counters, and alternatives when there are no numbers.\nintents: [build-component, build-section]\ntags: [stats, numbers, metrics, counters, figures, kpi]\ncomponents: [stats]\ncapabilities: []\nphases: [build, review]\npriority: 3\nrelated: [anti-slop-fake-proof, stats]\nversion: 1\n---\n**Only real numbers**: from the store (products sold, members, sessions) or supplied by the creator. \"10k+ happy customers\" invented by a model is a fabricated claim.\n\n**Setting them**: big tabular numerals in the display face, a short label underneath that says what was counted and when (\"312 students since 2021\"). Two to four figures, not six.\n\n**Counters**: animate from 0 only once on entry, 800 to 1400ms, ease out; render the final value in the HTML so it is correct without JS and under reduced motion.\n\n**No numbers**: drop the section. Replace it with something real: a short list of where the work has appeared, a single quote, the creator's credentials.\n"
 },
 {
  "file": "entries/component/component-tables.md",
  "source": "---\nid: component-tables\ntitle: Tables\ncategory: component\nsummary: Real tables for real data: semantics, alignment, numeric formatting, responsive strategies and sticky headers.\nintents: [build-component, build-section]\ntags: [table, data-table, comparison, spec-table, schedule]\ncomponents: [table]\ncapabilities: []\nphases: [build, review]\npriority: 3\nrelated: [typography-tracking-measure, component-pricing]\nversion: 1\n---\n**Use a table** for data with rows and columns that people compare: schedules, specs, size charts, comparisons. Not for layout.\n\n**Semantics**: `<table>`, `<caption>`, `<thead>` with `<th scope=\"col\">`, row headers `<th scope=\"row\">`.\n\n**Style**: left align text, right align numbers, tabular numerals, row separators as 1px rules, no zebra unless rows are long, padding 10 to 14px.\n\n**Responsive**: wrap in a scroll container with a visible edge shadow and `tabindex=\"0\"` plus an `aria-label`; or for 2 to 3 columns, stack rows into labelled blocks on phones (`data-label` attributes rendered via `::before`).\n\n```css\n.table-wrap { overflow-x: auto; }\ntable { border-collapse: collapse; width: 100%; font-variant-numeric: tabular-nums; }\nth, td { padding: 12px; border-bottom: 1px solid var(--border); text-align: left; }\ntd.num { text-align: right; }\nthead th { position: sticky; top: 0; background: var(--bg); }\n```\n"
 },
 {
  "file": "entries/component/component-tabs.md",
  "source": "---\nid: component-tabs\ntitle: Tabs\ncategory: component\nsummary: When tabs help (parallel content of equal weight), the ARIA tabs pattern with arrow keys, and phone alternatives.\nintents: [build-component, build-section]\ntags: [tabs, tablist, segmented, switcher]\ncomponents: [tabs]\ncapabilities: []\nphases: [build, review]\npriority: 3\nrelated: [component-accordion, a11y-keyboard-focus]\nversion: 1\n---\n**Use when** content splits into 2 to 5 parallel views people switch between (monthly vs yearly, menus by meal, sizes by region). Do not hide essential content in later tabs.\n\n**Pattern**: `role=\"tablist\"` containing `role=\"tab\"` buttons with `aria-selected` and `aria-controls`; panels `role=\"tabpanel\"` with `aria-labelledby`. Left and Right arrows move between tabs, Home and End jump; only the active tab is in the tab order (`tabindex=\"0\"`, others `-1`).\n\n**Visual**: the active tab clearly marked (underline 2px or filled segment), inactive tabs still 4.5:1. Segmented controls fit 2 to 3 short options.\n\n**Phones**: if labels do not fit, scroll the tab list horizontally, or switch to an accordion.\n\n**No JS fallback**: render all panels with headings, then enhance into tabs.\n"
 },
 {
  "file": "entries/component/component-testimonials.md",
  "source": "---\nid: component-testimonials\ntitle: Testimonials and quotes\ncategory: component\nsummary: Presenting quotes the creator supplied: attribution, layout options beyond the carousel, and what to do when there are none.\nintents: [build-component, build-section]\ntags: [testimonials, quotes, client-quotes, social-proof]\ncomponents: [testimonials, quote]\ncapabilities: []\nphases: [build, review]\npriority: 4\nrelated: [anti-slop-fake-proof, testimonials]\nversion: 1\n---\n**Source**: quotes the creator supplied as blocks. Each has real attribution (name, and role or context like \"Client since 2022\" if given). The AI never writes testimonial text or names.\n\n**Layouts**\n- One large quote set in the display face, attribution below. Strong when there is one great quote.\n- Two or three quotes in a row of plain text blocks (no cards needed) separated by rules.\n- A quote paired with a photo of the person (if supplied).\n- Many short quotes as a slow marquee only if there are at least 8 real ones.\n\n**Copy**: keep the quote specific; trim with an ellipsis rather than rewriting the person's words.\n\n**None yet**: leave the section out of the generated site, or include it with editor only guidance (\"Add a quote from a client\"); never sample quotes visible to visitors.\n\n**Markup**: `<figure><blockquote>...</blockquote><figcaption>Name, context</figcaption></figure>`.\n"
 },
 {
  "file": "entries/component/component-timeline.md",
  "source": "---\nid: component-timeline\ntitle: Timelines and process steps\ncategory: component\nsummary: Sequential content as ordered lists: vertical timelines, step lists, schedules, numbering that means something.\nintents: [build-component, build-section]\ntags: [timeline, process, steps, history, roadmap, schedule]\ncomponents: [timeline, process]\ncapabilities: []\nphases: [build, review]\npriority: 2\nrelated: [process, layout-sticky-storytelling]\nversion: 1\n---\n**Use for** genuinely sequential content: how working together goes, a course week by week, a brand history, an event day schedule.\n\n**Markup**: an ordered list `<ol>` so order is announced; each item has a heading (or time) and text.\n\n**Layout**: vertical with a 1 to 2px line connecting markers on the left; time or step label in a fixed width column; on desktop, alternating sides only for history timelines with images.\n\n**Numbers**: step numbers only when order matters to the visitor. Use the real time for schedules (\"19:00 Doors\").\n\n**Motion**: items can fade in as they enter; the line can draw with `scaleY` driven by scroll if the concept is expressive. Static under reduced motion.\n"
 },
 {
  "file": "entries/component/component-tooltip.md",
  "source": "---\nid: component-tooltip\ntitle: Tooltips and popovers\ncategory: component\nsummary: Tooltips for short labels only, popovers for richer content, touch alternatives and the anchor positioning cautions.\nintents: [build-component, build-section]\ntags: [tooltip, popover, hint, info]\ncomponents: [tooltip, popover]\ncapabilities: []\nphases: [build, review]\npriority: 2\nrelated: [a11y-keyboard-focus]\nversion: 1\n---\n**Tooltip**: a short text label for an icon button or an abbreviation. Shows on hover and on keyboard focus, hides on Escape, does not contain links or buttons. Reference it with `aria-describedby` (or use it as the accessible name with `aria-labelledby` for icon only buttons).\n\n**Popover**: richer content (a size note, a definition) opened by click. The native `popover` attribute with `popovertarget` handles light dismiss and top layer.\n\n```html\n<button popovertarget=\"fit-{{ section.id }}\">Fit notes</button>\n<div id=\"fit-{{ section.id }}\" popover>Cut for a relaxed fit. Take your usual size.</div>\n```\n\n**Touch**: hover does not exist; never put essential information only in a tooltip.\n\n**Delay**: 300 to 500ms before showing a tooltip on hover, none on focus. Keep tooltips under about 80 characters.\n"
 },
 {
  "file": "entries/core/core-agent-loop.md",
  "source": "---\nid: core-agent-loop\ntitle: How the website agent works a brief\ncategory: core\nsummary: The order of work for a whole site: understand, decide a concept, plan pages, build, check, repair. Never start with components.\nintents: [build-site, plan-site, generate-page]\ntags: [workflow, process, agent, planning, brief]\nphases: [concept, plan, build]\npriority: 5\nrelated: [core-visual-concept-first, core-self-review]\nversion: 1\n---\nWork a brief in this order and do not skip ahead.\n\n1. **Read what is real.** Products, prices, communities, forms, bookings and blog posts come from the store. Write down what exists before designing anything, because the page structure depends on it (a coach with a booking form gets a booking flow; a coach without one gets an enquiry form).\n2. **Fill the visual concept** (see `core-visual-concept-first`). Name, mood, type, palette, layout principles, motion stance, imagery, two or three signature moves.\n3. **Plan pages as jobs to be done.** For each page, write the one action it exists for and the order of evidence a visitor needs before taking it. Sections come from that order, not from a template list.\n4. **Build the most important section first** (usually the hero plus the primary offer) and judge the concept on it before writing the rest. A concept that does not survive the first section will not survive ten.\n5. **Check** with the anti-slop evaluator and the compiler, then look at a phone width.\n6. **Repair the smallest thing that fixes the finding.** Do not regenerate a section to fix a colour.\n\nDo: keep a short decision log (why this font, why this layout) so follow-up edits stay consistent.\nDon't: retrieve every knowledge entry up front, add sections because \"sites usually have them\", or invent content to fill a planned section that has no real data behind it. Drop the section instead.\n"
 },
 {
  "file": "entries/core/core-content-hierarchy.md",
  "source": "---\nid: core-content-hierarchy\ntitle: Ordering a page by what a visitor needs next\ncategory: core\nsummary: Sequence sections as answers to the visitor's questions (what, for whom, proof, how, price, doubts, act) instead of a fixed template order.\nintents: [plan-page, generate-page, structure]\ntags: [hierarchy, structure, sections, order, narrative, conversion]\nphases: [plan]\npriority: 4\nrelated: [core-agent-loop, anti-slop-repetitive-structure]\nversion: 1\n---\nA visitor arrives with questions in a rough order. A page is the answers, in that order, each as short as it can be.\n\n1. What is this and is it for me? (hero: offer plus audience)\n2. Why should I believe it? (real proof: work, results, press, reviews that exist)\n3. How does it work? (process, curriculum, menu, what is in the pack)\n4. What does it cost and what do I get? (pricing from the store)\n5. What might stop me? (FAQ, policies, guarantee if one exists)\n6. Do it. (one clear action, repeated at the end)\n\nAdapt per business. A restaurant reorders: hours and location come second because that is the first doubt. A portfolio has no price; the work is the proof and the action is contact. A music producer's sample pack page puts audio previews before any text because hearing is the proof.\n\nRules: one primary action per page, repeated at most three times. Never two adjacent sections answering the same question. If a step has no real content (no reviews yet), skip it rather than faking it; the page is shorter and better. Alternate density: a dense section (curriculum list) after an open one (single image and line) keeps rhythm.\n"
 },
 {
  "file": "entries/core/core-copywriting.md",
  "source": "---\nid: core-copywriting\ntitle: Writing site copy that sounds like a person\ncategory: core\nsummary: Specific, plain copy in the creator's voice; banned marketing words, headline formulas and fake urgency to avoid, with rewrites.\nintents: [write-copy, generate-page, review]\ntags: [copy, voice, writing, headline, words, tone]\nphases: [build, review]\npriority: 5\nrelated: [anti-slop-empty-words, anti-slop-fake-proof]\nversion: 1\n---\nCopy is half of whether a page reads as made by a person.\n\n**Do**\n- Name the thing that happens: \"Twelve week strength block, three sessions a week\" beats \"Transform your fitness journey\".\n- Use the creator's own words from their bio, products and posts. Their spelling, their jokes.\n- Headlines under about eight words. Body lines that say one thing.\n- Buttons as verbs with objects: \"Book a session\", \"Get the sample pack\", \"Read the menu\".\n- Numbers only when they are real and come from the store.\n\n**Don't**\n- The words that mark machine copy: unlock, elevate, seamless, powerful, effortless(ly), supercharge, transform, empower, streamline, revolutionise, next level, game changer, cutting edge, world class, unleash, journey (as a metaphor), curated (unless it is literally a curation).\n- Formulas: \"X meets Y\", \"Not just A. B.\", \"Where A meets B\", three adjective triplets (\"Bold. Simple. Yours.\"), rhetorical questions as headlines.\n- Em dashes and decorative hyphens. Use a full stop or a comma.\n- Fake urgency: \"Only 3 left!\" without stock data, countdowns to nothing.\n\n**Rewrite examples**\n- \"Elevate your sound with our powerful sample packs\" -> \"Drum breaks and textures recorded on tape in Glasgow\".\n- \"Unlock your potential with seamless coaching\" -> \"One to one coaching for runners coming back from injury\".\n"
 },
 {
  "file": "entries/core/core-diversity.md",
  "source": "---\nid: core-diversity\ntitle: Making two similar businesses look different\ncategory: core\nsummary: How to pick a distinct direction per site by moving along concrete axes (tone, era, density, temperature, type voice) instead of reusing the category default.\nintents: [plan-site, choose-style, redesign]\ntags: [diversity, concept, direction, variety, axes]\nphases: [concept]\npriority: 4\nrelated: [core-visual-concept-first, style-combining]\nversion: 1\n---\nThe fastest route to a generic site is to take the industry default: every fitness coach gets black, neon green and a condensed sans. Instead, place each concept on five axes and deliberately choose a position.\n\n| Axis | One end | Other end |\n| --- | --- | --- |\n| Tone | quiet, considered | loud, declarative |\n| Era | classic, heritage | contemporary, futurist |\n| Density | airy, few elements | dense, information rich |\n| Temperature | warm neutrals, earth | cool, mineral, high contrast |\n| Type voice | serif, literary | grotesk, condensed, mono |\n\nTwo fitness coaches, same brief:\n- **\"Quiet Strength\"**: quiet, classic, airy, warm, serif. Cream background, deep olive text, a high contrast serif display, photos of slow movement in natural light, no motion beyond fades.\n- **\"Training Log\"**: loud, contemporary, dense, cool, mono. Off white with black rules, a monospace for numbers and schedules, a ticker of session times, hard cut image transitions.\n\nRules: pick at least two axes far from the category default. Use the creator's own material (their photos, their way of talking) to decide which. When a previous concept exists for the same creator or a sibling site, `suggestDirections` in concept.ts avoids its positions. Never vary randomly; every position needs a reason drawn from the brand.\n"
 },
 {
  "file": "entries/core/core-inspiration.md",
  "source": "---\nid: core-inspiration\ntitle: What the best sites in curated galleries do\ncategory: core\nsummary: Lessons from galleries of outstanding sites (style, type and subject), turned into rules: one strong idea, type as image, real content as the hero, a rhythm that changes, restraint in motion, and a header and footer that belong.\nintents: [build-site, plan-site, choose-style, redesign, review]\ntags: [inspiration, gallery, siteinspire, awards, great sites, art direction, taste, original, typographic, minimal, grid, unusual layout, portfolio, ecommerce]\nphases: [concept, plan, review]\npriority: 5\nrelated: [core-visual-concept-first, core-diversity, typography-type-library, component-interactive-library, layout-spacing-rhythm]\nversion: 1\n---\nCurated galleries of web design sort the sites they keep by **style** (minimal, typographic, grid layout, unusual layout, photographic, illustrative, colourful, flat, dark, light, retro, brutalist, fullscreen, horizontal), by **type** (portfolio, e-commerce, agency, magazine, blog, personal, event, product, single page, microsite) and by **subject** (architecture, art, design, fashion, food and drink, photography, music, film, publishing, education, health, travel and hotels, furniture and interiors, non-profit, technology). The sites that get in share habits that have nothing to do with a template:\n\n1. **One idea, held everywhere.** A studio's index set like a drawing register; a bakery's day as a shop board; a label's releases as a crate. Decide the idea in the concept and let every section serve it.\n2. **Type is the image.** Large, tightly set display type in a face with character (typography-type-library), small precise labels, real hierarchy from size jumps. Many of the best sites have almost no decoration.\n3. **The real thing is the hero.** The work, the product, the menu, the timetable, the room. Never an abstract gradient or a stock photo of people pointing at laptops.\n4. **Rhythm changes on purpose.** Full bleed after narrow, dense after airy, one sticky or sideways moment, a list where others would put cards. Sections are different widths and densities because their content is.\n5. **Grids are visible or broken on purpose.** Either a strict 12 column grid you can feel (numbers, rules, aligned captions) or a deliberately unusual layout (overlaps, offsets, a side rail). Never the default centred column for everything.\n6. **Motion is restrained and specific.** A marquee for dates, a hover image reveal on an index, a slow reveal of photos, one view transition. Reduced motion respected.\n7. **Navigation belongs to the design.** A header and footer made for the concept: a text index, a side rail, a huge footer wordmark, the site's own cart and search.\n8. **Copy is specific.** Real names, places, times, materials and prices; headings that name the thing.\n\n**Using the starting directions**: the brief lists directions chosen for the subject (concept.ts DIRECTIONS: style, type, palette, layout moves, motion, imagery, signature). They are seeds. Take one, change it for this creator's material, and make the signature move something a visitor will remember. Never copy a site you have seen; take the principle, not the look.\n"
 },
 {
  "file": "entries/core/core-iteration.md",
  "source": "---\nid: core-iteration\ntitle: Follow up edits without breaking the concept\ncategory: core\nsummary: How to apply a creator's change request with the smallest edit, keep the concept and editable settings intact, and say what changed.\nintents: [edit, iterate, follow-up, change-section]\ntags: [iteration, edit, minimal, follow-up, change]\nphases: [build, repair]\npriority: 4\nrelated: [core-agent-loop, core-self-review]\nversion: 1\n---\nAfter the first build, most work is follow ups: \"make the hero darker\", \"I hate the font\", \"add my booking form\".\n\n- **Classify the change**: content (a setting), style (scheme, token, font), structure (add, remove, reorder a section), or behaviour (a form, a cart, motion). Content goes to settings, never into code.\n- **Change the smallest scope that satisfies it.** \"Darker hero\" changes that section's scheme or overlay, not the site palette. \"I hate the font\" is a site level type change: update the concept's type system and the theme setting, then check every display size still fits.\n- **Keep editable props editable.** A custom component's manifest must keep every prop it had unless the request removes that content. Do not inline a prop's value into the source.\n- **Re-run the checks that the change can affect**: a colour change runs contrast; a layout change runs the phone check; new copy runs the word check.\n- **Say what changed in one or two plain sentences** and what you did not touch. \"Hero background is now the dark scheme, the overlay is 40%. Other sections are unchanged.\"\n\nIf a request contradicts the concept (\"make it playful\" on a luxury site), it wins: update the concept so later edits follow the new direction instead of drifting back.\n"
 },
 {
  "file": "entries/core/core-links-and-actions.md",
  "source": "---\nid: core-links-and-actions\ntitle: Every link and button goes somewhere real\ncategory: core\nsummary: Calls to action, menu links and commerce buttons need real destinations or hooks; placeholders block finish. Which links may stay plain and how in-page anchors pass.\nintents: [build-site, generate-page, review, repair]\ntags: [links, cta, buttons, navigation, commerce, bindings, anchors, checks]\nphases: [build, review, repair]\npriority: 5\nrelated: [core-self-review, debug-common-markup, core-agent-loop]\nversion: 1\n---\nThe render check reads every link and button on a drawn page. A link with a job is held to a real destination, and a broken one blocks finish until it is fixed.\n\n**Links with a job** (an error when they go nowhere, to a page that does not exist, or to an id that is not on the page):\n- calls to action: a link dressed as a button (a class with btn, button, cta, buy, shop, book, join...) or whose words ask for something (Book a class, Shop the program, Get started, Contact);\n- every link in a `<nav>`, and every link in the site's own header and footer;\n- commerce: add to cart, checkout, Buy now.\n\n**How to give them a destination**\n- A url setting with a real default from list_capabilities: a page (`/about`), a product's url, a collection, a form's page. Print it with `| url`. Do not fall back to `'#'`.\n- A button whose setting may be empty is hidden while it is empty: `{% if settings.cta_url and settings.cta_label %}<a class=\"cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}`.\n- Buy now is the product's `checkout_url`; add to cart is `data-storelib-add-to-cart=\"{{ block.id }}\"` inside a product_list loop or `\"{{ settings.product.id }}\"` for a product_picker. A `<button>` needs a hook (`data-storelib-add-to-cart`, `data-storelib-cart`, `data-storelib-menu`, `data-storelib-checkout`), a form, or the section's own script; otherwise make it a link.\n- A bound product list prints `block.settings.title`, `block.settings.price`, `block.settings.url` and `block.id`. Printing `product.title` inside `{% for block in settings.products %}` draws empty titles and prices, which the check reports as `binding.empty`.\n\n**Allowed**\n- In-page anchors to an id that is on the page: `href=\"#classes\"` with a section that has `id=\"classes\"`, or `#section-<section id>`. They pass.\n- `href=\"#\"` on an element with a hook (`data-storelib-cart`, `aria-controls`, `role=\"button\"`).\n- A plain link inside running text with a problem is only a warning, but fix it anyway.\n\nNever: `javascript:` addresses, `href=\"\"`, an `<a>` with no href styled as a button, or a CTA that says something the store cannot do.\n"
 },
 {
  "file": "entries/core/core-prompt-reading.md",
  "source": "---\nid: core-prompt-reading\ntitle: Reading a short or vague prompt\ncategory: core\nsummary: Turn a one line request into a usable brief by inferring audience, offer and tone from store data, and ask nothing that the data already answers.\nintents: [build-site, plan-site, understand-request]\ntags: [prompt, brief, intent, clarify, vague]\nphases: [concept, plan]\npriority: 4\nrelated: [core-agent-loop]\nversion: 1\n---\nMost prompts are one line: \"site for my yoga classes, make it calm\". Extract four things before designing.\n\n1. **Who visits and what they came to do.** Infer from what the store sells: a course product means students deciding to enrol; bookings mean someone choosing a time.\n2. **The one action.** Enrol, book, buy, join, enquire. If the store supports several, rank them by what has real data (a booking form with slots outranks a vague \"contact us\").\n3. **Tone words the creator used.** \"Calm\", \"edgy\", \"premium\". Treat them as constraints on the concept, not as copy. Never print \"calm\" on the page.\n4. **Anything explicitly asked for**, which outranks every default here: \"use a gradient\", \"make it pink\", \"one page only\".\n\nAsk a question only when the answer changes the structure and no data answers it (for example, two unrelated businesses in one store). Otherwise decide, state the assumption in one line in the plan, and continue. Do not ask about colours or fonts; propose them.\n\nDo not inflate a short prompt into a long feature list. \"Site for my yoga classes\" is a home page, a classes or timetable page, an about page and a way to book. Not a blog, a shop and a community unless they exist.\n"
 },
 {
  "file": "entries/core/core-self-review.md",
  "source": "---\nid: core-self-review\ntitle: Reviewing your own output before calling it done\ncategory: core\nsummary: A short checklist run on every generated page: concept fidelity, real data only, mobile, states, contrast, motion safety, copy and the anti-slop evaluator.\nintents: [review, check, qa]\ntags: [review, checklist, qa, quality]\nphases: [review]\npriority: 5\nrelated: [anti-slop-relative-judgement, a11y-checklist, debug-visual-review, core-links-and-actions]\nversion: 1\n---\nBefore reporting a page as finished, check in this order. Fix as you go; do not just list problems.\n\n1. **Concept**: could you point at each signature move on the page? If not, it was dropped. Is the type system the declared one, with no extra families?\n2. **Real data**: every product, price, review, number and logo traces back to the store or the creator. Empty collections show an editor-only placeholder, not invented items.\n3. **Evaluator**: run `evaluateSlop` with the concept. Resolve every error; resolve warnings unless the concept explains them.\n4. **Phone at 375px**: nothing scrolls sideways, text at least 16px for body, tap targets at least 44px, the primary action visible without hunting.\n5. **States**: buttons have hover, focus-visible, active and disabled; forms have error, success and submitting; lists have empty.\n6. **Contrast**: body text 4.5:1, large text 3:1, focus ring 3:1 against its neighbours.\n7. **Motion**: everything that moves stops or simplifies under `prefers-reduced-motion: reduce`; nothing animates layout properties in a loop.\n8. **Copy**: no banned words, no em dashes, buttons say what happens.\n9. **Links and buttons**: every call to action, menu link and commerce button goes to a real page, product, form or in-page id, or has its hook; nothing points at `#` or an empty href (see `core-links-and-actions`). The render check treats these as errors.\n\nIf the answer to \"could this belong to any other business?\" is yes, change the concept's weakest field and rebuild that section.\n"
 },
 {
  "file": "entries/core/core-visual-concept-first.md",
  "source": "---\nid: core-visual-concept-first\ntitle: Decide a visual concept before generating\ncategory: core\nsummary: Every site starts from a filled visual concept (name, mood, type, palette, layout, motion, imagery, signature moves) so choices have a reason and two similar businesses look different.\nintents: [build-site, plan-site, choose-style, redesign]\ntags: [concept, art-direction, diversity, mood, direction]\nphases: [concept, plan]\npriority: 5\nrelated: [style-combining, core-diversity, anti-slop-relative-judgement]\nversion: 1\n---\nA concept is a short art direction, written before any markup. The schema lives in `lib/storelib-ai/library/concept.ts`; fill every field.\n\n- **Name**: two to four words that describe the idea, not the business. \"Chalk and Iron\", \"Morning Pages\", \"Velvet Night Shift\". If the name could be any site's, it is not a concept.\n- **Mood**: three adjectives that pull in different directions (calm, exact, warm), not three synonyms.\n- **Type system**: display face, body face, scale ratio, and one rule about case or tracking.\n- **Palette**: background, text, one accent and where the accent is allowed to appear.\n- **Layout principles**: two or three rules, e.g. \"everything hangs from a 12 column grid with a wide left margin\", \"images bleed off the right edge\".\n- **Motion stance**: none, subtle, expressive or cinematic, plus what moves.\n- **Imagery**: subject, light, crop, colour treatment, and what to avoid.\n- **Signature moves**: one to three things a visitor would remember. A giant outlined numeral, a ticker of class times, captions set like museum labels.\n\nUse the concept to judge every later choice: if a component does not serve one of the principles, change it. The anti-slop evaluator reads the concept, so a declared glassmorphism concept is not penalised for blur, while a quiet editorial one is.\n"
 },
 {
  "file": "entries/debugging/debug-broken-images.md",
  "source": "---\nid: debug-broken-images\ntitle: Missing and broken images\ncategory: debugging\nsummary: Empty image boxes, wrong crops and broken URLs in generated sections; guards, placeholders for editors and credit requirements.\nintents: [debug, repair, fix]\ntags: [debugging, bug, images, broken-image, placeholder, asset]\nphases: [repair, review]\npriority: 3\nrelated: [responsive-images, storelib-honest-data]\nversion: 1\n---\n- **Empty setting renders a broken box**: wrap images in `{% if settings.image %}` and show an editor only placeholder in the else branch.\n- **Wrong crop**: set `object-fit` and `object-position`; for faces, top or a focal point setting.\n- **Remote URLs typed into markup**: images belong in image_picker settings (printed with `| asset`), so they are stored, resized and editable.\n- **Huge files**: use the asset pipeline sizes and `srcset`; never ship 5MB originals.\n- **Open licence photos**: keep the credit (the AI builder writes a photo credits page) and do not strip attribution requirements.\n- **Alt missing**: every image has alt, from a setting when the creator should control it.\n"
 },
 {
  "file": "entries/debugging/debug-common-markup.md",
  "source": "---\nid: debug-common-markup\ntitle: Common markup mistakes in generated code\ncategory: debugging\nsummary: Invalid nesting, divs as buttons, missing alt and labels, duplicate ids, links without href: quick detection and fixes.\nintents: [debug, repair, fix]\ntags: [debugging, bug, markup, html, invalid, nesting, semantics]\nphases: [repair, review]\npriority: 4\nrelated: [a11y-semantics, debug-section-scripts, core-links-and-actions]\nversion: 1\n---\n- **Interactive inside interactive**: a button inside a link, a link inside a link. Pick one element; stretch the link for whole card clicks.\n- **Block inside inline**: a `div` inside a `p` (the browser closes the paragraph early and styles break). Use `span` or restructure.\n- **Clickable divs**: replace with `button` or `a`.\n- **Links without href** (`<a onclick>`, `href=\"#\"`, `href=\"\"`): use a button with a hook, or give the link a real URL. For a call to action, a menu link or a commerce link the render check makes this an error (`core-links-and-actions`).\n- **Buttons with nothing behind them**: a `<button>` with no hook, no form and no script does nothing; the check reports `render.dead_button`.\n- **Images without alt**: add meaningful or empty alt.\n- **Inputs without labels**: add a label with `for`.\n- **Duplicate ids** (a section placed twice): build ids from `{{ section.id }}`.\n- **Heading levels by size**: fix the level, restyle with a class.\n- **Lists without list elements**: wrap in `ul` or `ol`.\n- **Empty headings or buttons** from missing settings: wrap in `{% if %}`.\n"
 },
 {
  "file": "entries/debugging/debug-css-scoping.md",
  "source": "---\nid: debug-css-scoping\ntitle: Styles leaking or not applying\ncategory: debugging\nsummary: Section CSS that leaks to the page or loses to theme styles; scoping, specificity and custom properties.\nintents: [debug, repair, fix]\ntags: [debugging, bug, css, scoping, specificity, leaking-styles, theme-css]\nphases: [repair, review]\npriority: 4\nrelated: [debug-common-markup, color-scheme]\nversion: 1\n---\n**Leaking**: selectors like `h2 { ... }` or `.button { ... }` in a section affect the whole page. Prefix every rule with the section's own class or root, and keep generic element selectors inside it (`.s-hero h2`).\n\n**Not applying**: theme styles with higher specificity win. Raise specificity within the section's scope (`.s-hero .s-hero__title`), not with `!important`. Check that the class names in the template match the CSS (typos are common).\n\n**Colours**: read scheme colours from the section's custom properties so the creator's scheme applies; a hard coded colour does not follow the scheme.\n\n**Order**: a media query written before the base rule it overrides loses. Write base first, then breakpoints ascending.\n\n**Debug**: devtools \"Computed\" panel shows which rule wins and where it comes from.\n"
 },
 {
  "file": "entries/debugging/debug-horizontal-overflow.md",
  "source": "---\nid: debug-horizontal-overflow\ntitle: Horizontal scrolling on phones\ncategory: debugging\nsummary: Finding and fixing the element that makes a page scroll sideways on phones.\nintents: [debug, repair, fix]\ntags: [debugging, bug, overflow, horizontal-scroll, 100vw, mobile-bug]\nphases: [repair, review]\npriority: 4\nrelated: [anti-slop-weak-mobile, responsive-mobile-first]\nversion: 1\n---\n**Find it**: in devtools, run\n```js\n[...document.querySelectorAll('*')].filter(e => e.getBoundingClientRect().right > document.documentElement.clientWidth + 1)\n```\n\n**Usual causes**: `width: 100vw` (includes scrollbar; use `100%`), fixed pixel widths, long unbroken words or URLs (`overflow-wrap: anywhere`), negative margins on full bleed tricks, transforms that move elements off screen, wide tables and code blocks without a scroll wrapper, grids with `minmax(300px, 1fr)` at 320px (use `minmax(min(300px, 100%), 1fr)`), images without `max-width: 100%`.\n\n**Do not** hide it with `overflow-x: hidden` on body; it breaks `position: sticky` and hides the bug. Use `overflow-x: clip` on the specific wrapper if clipping is intended.\n"
 },
 {
  "file": "entries/debugging/debug-layout-shift.md",
  "source": "---\nid: debug-layout-shift\ntitle: Layout shift and jumping content\ncategory: debugging\nsummary: Why content jumps while loading (images without dimensions, late fonts, injected banners, lazy embeds) and how to fix each.\nintents: [debug, repair, fix]\ntags: [debugging, bug, cls, layout-shift, jumping, fonts, images]\nphases: [repair, review]\npriority: 3\nrelated: [responsive-images, typography-loading]\nversion: 1\n---\n**Causes and fixes**\n- Images without `width` and `height` (or `aspect-ratio`): add them; the browser reserves space.\n- Web fonts swapping with different metrics: use fallback metric overrides (`size-adjust`, `ascent-override`) or `font-display: optional` for display faces.\n- Banners or cookie bars inserted above content: reserve space or overlay them at the bottom.\n- Embeds and iframes: wrap in an aspect ratio box.\n- Skeletons that do not match the final size: match dimensions exactly.\n- Animations of `height` or `top`: use transforms.\n\n**Check**: Chrome performance panel \"Layout shifts\" track or the Web Vitals CLS value; aim below 0.1.\n"
 },
 {
  "file": "entries/debugging/debug-section-scripts.md",
  "source": "---\nid: debug-section-scripts\ntitle: Section scripts that break\ncategory: debugging\nsummary: Common failures in section scripts: querying the whole document, duplicate ids, running before markup, listeners that leak, and the sandbox.\nintents: [debug, repair, fix]\ntags: [debugging, bug, javascript, script, sandbox, queryselector, events]\nphases: [repair, review]\npriority: 4\nrelated: [debug-common-markup, multi-instance]\nversion: 1\n---\n- **Query inside the section's root**, never `document.querySelector`: a section can appear twice, and the second instance would control the first.\n- **No fixed ids**; build them from the section id.\n- **Assume the markup can change** in the editor: re-query on updates, do not cache nodes forever.\n- **Clean up**: observers and listeners on window should be disconnected when the section is removed (keep references).\n- **Do not block rendering**: content must be visible and usable without the script; the script enhances.\n- **Sandbox**: section scripts run in a sandbox against a copy of the section; declare the capabilities the schema needs (for example `embed`); remote script imports are not allowed.\n- **Errors**: one exception stops the rest of the script; guard optional elements (`root.querySelector('.x')?.addEventListener(...)`).\n"
 },
 {
  "file": "entries/debugging/debug-stacking.md",
  "source": "---\nid: debug-stacking\ntitle: Z-index and stacking problems\ncategory: debugging\nsummary: Dropdowns hidden behind sections, overlays under headers, and how stacking contexts cause them.\nintents: [debug, repair, fix]\ntags: [debugging, bug, z-index, stacking-context, overlay, dropdown-hidden]\nphases: [repair, review]\npriority: 3\nrelated: [debug-sticky, component-dialog]\nversion: 1\n---\n**Why z-index 9999 does not work**: z-index only competes within the same stacking context. A parent with `transform`, `filter`, `opacity < 1`, `isolation: isolate`, `will-change: transform`, or `position` plus `z-index` creates a new context; children cannot escape it.\n\n**Fixes**\n- Render overlays (menus, dialogs, drawers) in the top layer: native `<dialog>` with `showModal()` or the `popover` attribute. They escape every stacking context.\n- Use a small z-index scale as tokens: base 0, raised 10, sticky 20, header 30, overlay 40, modal 50, toast 60.\n- Remove unnecessary transforms or `will-change` on ancestors of dropdowns.\n- For a section's own overlay, keep it inside the section with `isolation: isolate` on the section so it does not fight the page.\n"
 },
 {
  "file": "entries/debugging/debug-sticky.md",
  "source": "---\nid: debug-sticky\ntitle: Sticky positioning not working\ncategory: debugging\nsummary: The reasons position sticky silently fails and how to fix each.\nintents: [debug, repair, fix]\ntags: [debugging, bug, sticky, position-sticky, overflow]\nphases: [repair, review]\npriority: 3\nrelated: [layout-sticky-storytelling, header-sticky]\nversion: 1\n---\n- **An ancestor has `overflow: hidden`, `auto` or `scroll`**: sticky sticks to that ancestor's scroll box instead. Use `overflow: clip` (which does not create a scroll container) or remove the overflow.\n- **No offset**: sticky needs `top` (or `bottom`).\n- **The parent is not taller than the sticky element**: sticky only moves within its parent. In grids and flex rows, set `align-self: start` on the sticky item so it is not stretched to the full height.\n- **Display contents or tables**: sticky on table rows behaves differently across browsers; apply it to `th` cells.\n- **Header height**: offset sticky elements below a sticky header with `top: calc(var(--header-h) + 16px)`.\n"
 },
 {
  "file": "entries/debugging/debug-template-errors.md",
  "source": "---\nid: debug-template-errors\ntitle: Template and schema compile errors\ncategory: debugging\nsummary: Reading Storelib section compile errors: undeclared settings, wrong filters, unsupported syntax, invalid JSON, and how to repair with minimal edits.\nintents: [debug, repair, fix]\ntags: [debugging, bug, compile, template, schema, liquid-like, undeclared]\nphases: [repair, review]\npriority: 4\nrelated: [core-iteration, debug-section-scripts]\nversion: 1\n---\n- **Undeclared name**: `{{ settings.foo }}` without a schema setting id `foo`. Add the setting (with the right type) or fix the typo; block settings are declared under the block type.\n- **Framework syntax**: `v-if`, `@click`, `:class`, JSX braces are refused. Use `{% if %}`, `{% for %}`, `{{ }}`.\n- **Wrong type**: a picture must be an `image_picker` and printed with `| asset`; a link a `url` with `| url`; a menu a `link_list`.\n- **Raw HTML**: `| raw` only on richtext settings.\n- **Schema JSON**: trailing commas, comments and single quotes make it invalid; validate the JSON.\n- **Unclosed tags**: every `{% if %}` needs `{% endif %}`, every `{% for %}` `{% endfor %}`.\n\n**Repair** the exact line reported; do not rewrite the file. Re-run the compiler after each fix.\n"
 },
 {
  "file": "entries/debugging/debug-visual-review.md",
  "source": "---\nid: debug-visual-review\ntitle: Visual review of generated pages\ncategory: debugging\nsummary: A fast routine for checking generated output in a real browser at several widths and what to look for at each.\nintents: [debug, repair, fix]\ntags: [debugging, bug, visual-review, screenshot, qa, check]\nphases: [repair, review]\npriority: 4\nrelated: [core-self-review, debug-horizontal-overflow]\nversion: 1\n---\n**Widths**: 375 (phone), 768 (tablet), 1280 (laptop), 1440+ (desktop). Also 320 for the worst case.\n\n**At each width look for**: horizontal scroll (scroll the page sideways), text overlapping images, buttons wrapping into two lines, images cropped badly (faces cut), empty boxes where images failed, giant gaps, sections touching with no space, sticky elements covering content.\n\n**Interact**: tab through the page (focus visible, order logical), open menus and dialogs, submit a form with errors, toggle reduced motion in devtools rendering settings, try dark sections for contrast.\n\n**Measure, do not guess**: use the browser to compute contrast and element sizes; the repo's `scripts/check-*.mjs` pattern renders markup in headless Chromium and measures geometry.\n\nReport findings as the measured value and the fix, then re-check after fixing.\n"
 },
 {
  "file": "entries/footer/footer-big-type.md",
  "source": "---\nid: footer-big-type\ntitle: Big type footer\ncategory: footer\nsummary: An oversized wordmark or statement filling the footer width; fitting it responsively and keeping links usable.\nintents: [design-footer, build-section]\ntags: [footer, big-type, wordmark, oversized, statement]\ncomponents: [footer]\nphases: [plan, build]\npriority: 3\nrelated: [style-typography-led, footer-editorial]\nversion: 1\n---\n**Pattern**: the brand name set across the full width at the bottom (often 15 to 25vw), with links and legal above it.\n\n**Fitting the width**: size with viewport units and tune by the word length, or use an SVG `<text>` with `textLength` and `viewBox` so it always spans exactly.\n\n```css\n.wordmark { font-size: clamp(3rem, 19vw, 22rem); line-height: .8; letter-spacing: -.04em; white-space: nowrap; overflow: hidden; }\n```\n\n**Accessibility**: the giant wordmark is decorative if the brand name appears elsewhere: `aria-hidden=\"true\"`.\n\n**Don't**: crop letters so the name becomes unreadable unless the concept explicitly wants a cropped mark.\n"
 },
 {
  "file": "entries/footer/footer-editorial.md",
  "source": "---\nid: footer-editorial\ntitle: Editorial footer\ncategory: footer\nsummary: A footer that reads like a colophon: credits, a short statement, sections and sign up, set with editorial type.\nintents: [design-footer, build-section]\ntags: [footer, editorial, colophon, magazine]\ncomponents: [footer]\nphases: [plan, build]\npriority: 2\nrelated: [style-editorial, footer-big-type]\nversion: 1\n---\n**Contents**: a short line about the publication or brand, sections list, credits (design, photography with licences), newsletter, social.\n\n**Layout**: an asymmetric grid: statement across 6 columns, link groups in narrow columns, rules between rows.\n\n**Type**: the statement in the display or reading serif at 20 to 28px; lists in small caps.\n\n**Good detail**: photo credits for open licence images gathered here or on a credits page (Storelib's AI builder makes a photo credits page for Openverse images).\n"
 },
 {
  "file": "entries/footer/footer-full-bleed.md",
  "source": "---\nid: footer-full-bleed\ntitle: Full bleed footer\ncategory: footer\nsummary: A footer that becomes a final scene: full width colour or image with the closing action and essentials.\nintents: [design-footer, build-section]\ntags: [footer, full-bleed, image, dark-footer, band]\ncomponents: [footer]\nphases: [plan, build]\npriority: 2\nrelated: [layout-full-bleed, footer-big-type]\nversion: 1\n---\n**When**: brand led sites where the footer is the last impression: venues, studios, fashion.\n\n**Shape**: full width background (dark scheme or a photo with overlay), the closing call to action or contact large, essentials (address, hours, links) below in small type.\n\n**Contrast**: text on photo needs an overlay; check the brightest area.\n\n**Rhythm**: if the section above is already dark and full bleed, use a lighter footer to separate them.\n"
 },
 {
  "file": "entries/footer/footer-minimal.md",
  "source": "---\nid: footer-minimal\ntitle: Minimal footer\ncategory: footer\nsummary: One or two lines: brand, essential links, legal and socials; spacing and what must always be there.\nintents: [design-footer, build-section]\ntags: [footer, minimal, simple, legal]\ncomponents: [footer]\nphases: [plan, build]\npriority: 4\nrelated: [footer-multi-column, header-minimal]\nversion: 1\n---\n**Contents**: brand name, 3 to 6 essential links (contact, policies, terms), social links if they exist, copyright with the current year computed, not typed.\n\n**Layout**: one row on desktop (brand left, links right), stacked on phones with 12 to 16px between rows. Padding 32 to 48px top and bottom.\n\n**Type**: 13 to 14px, muted colour that still passes 4.5:1.\n\n**Always**: links to the legal pages the store has (privacy, terms, refund, shipping when selling). Do not invent company numbers or addresses.\n\n```html\n<footer class=\"site-footer\">\n  <p>&copy; <span data-year></span> Studio Name</p>\n  <nav aria-label=\"Footer\"><a href=\"/policies/privacy\">Privacy</a> <a href=\"/policies/terms\">Terms</a></nav>\n</footer>\n```\n"
 },
 {
  "file": "entries/footer/footer-multi-column.md",
  "source": "---\nid: footer-multi-column\ntitle: Multi column footer\ncategory: footer\nsummary: Grouped link columns for sites with many pages; grouping, headings, collapsing to accordions on phones.\nintents: [design-footer, build-section]\ntags: [footer, multi-column, sitemap, links, columns]\ncomponents: [footer]\nphases: [plan, build]\npriority: 3\nrelated: [footer-minimal, component-accordion]\nversion: 1\n---\n**When**: shops and sites with more than about 10 pages worth linking.\n\n**Groups**: 2 to 4 columns with clear headings (Shop, Help, About). Each group 3 to 7 links from real menus (use a footer link_list, not typed links).\n\n**Phones**: either keep groups stacked (fine when short) or collapse each group into a disclosure (`<details>` works without JS). Keep the newsletter and socials always visible.\n\n**Headings**: real headings (`h2` with a visually small style) so screen reader users can jump between groups.\n\n**Avoid**: a fake sitemap of pages that do not exist; columns of a single link.\n"
 },
 {
  "file": "entries/footer/footer-newsletter.md",
  "source": "---\nid: footer-newsletter\ntitle: Newsletter footer\ncategory: footer\nsummary: A footer led by an email sign up: one field, honest promise of frequency, real form handling and states.\nintents: [design-footer, build-section]\ntags: [footer, newsletter, email, signup, subscribe]\ncomponents: [footer]\nphases: [plan, build]\npriority: 3\nrelated: [storelib-forms, component-forms]\nversion: 1\n---\n**Promise**: say what people get and how often (\"A letter when a new pack is out, about once a month\"). No \"Join 10k subscribers\" unless real.\n\n**Form**: one email field with a visible label (can be visually small), a button, privacy note link. States: submitting (button disabled with text \"Signing up\"), success (replace the form with a confirmation), error (message under the field, focus moved to it).\n\n**Storelib**: use `data-storelib-form=\"subscribe\"` so the email reaches the creator's real list; never a form posting nowhere.\n\n**Layout**: heading and promise in 6 columns, form in the other 6 on desktop; stacked on phones with the button full width.\n"
 },
 {
  "file": "entries/footer/footer-none.md",
  "source": "---\nid: footer-none\ntitle: No footer\ncategory: footer\nsummary: When a page can omit the footer and what must still be reachable (legal links, contact) elsewhere.\nintents: [design-footer, build-section]\ntags: [footer, no-footer, minimal, landing]\ncomponents: [footer]\nphases: [plan, build]\npriority: 1\nrelated: [header-none, footer-minimal]\nversion: 1\n---\n**When**: a focused landing page, a checkout step, a full screen experience, a link in bio page.\n\n**Still required**: legal links where the store sells (privacy, terms, refunds) reachable from the page (a small line at the end works); contact for support; the copyright line is optional.\n\n**Never**: remove policies from a page that takes payment.\n\n**Replacement pattern**: end the page with the primary action and a single quiet line underneath: brand name, a contact email, and the policy links, in 13 to 14px muted text. That keeps the page focused while still meeting what a selling site owes its visitors.\n"
 },
 {
  "file": "entries/footer/footer-social.md",
  "source": "---\nid: footer-social\ntitle: Social footer\ncategory: footer\nsummary: Showing social profiles: only real ones from shop.socials, labelled links, sensible icon sizes and order.\nintents: [design-footer, build-section]\ntags: [footer, social, socials, icons, links]\ncomponents: [footer]\nphases: [plan, build]\npriority: 2\nrelated: [footer-minimal, a11y-checklist]\nversion: 1\n---\n**Source**: only profiles the creator has (`shop.socials`); never placeholder links to instagram.com.\n\n**Format**: text links (\"Instagram\", \"YouTube\") are clearer than icons for most audiences; icons need `aria-label` and 24px glyphs in 44px hit areas.\n\n**Order**: by where the audience actually is (a music producer: SoundCloud, YouTube, Instagram).\n\n**Creator sites**: social can be primary content (latest video embed, recent posts) rather than just icons.\n"
 },
 {
  "file": "entries/header/header-animated.md",
  "source": "---\nid: header-animated\ntitle: Animated headers\ncategory: header\nsummary: Headers that shrink, change colour or morph the logo on scroll, with performance and restraint rules.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, animated, motion, shrink, morph]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 2\nrelated: [header-sticky, motion-principles]\nversion: 1\n---\n**Safe animations**: shrink height from 80 to 60px, swap logo size, fade in a background, show a progress bar for long reads. Use transforms and opacity where possible; animating height causes layout work on every frame, so prefer scaling the logo with `transform` and keeping the bar height fixed.\n\n**Scroll driven CSS** (where supported) avoids JS:\n\n```css\n@supports (animation-timeline: scroll()) {\n  .progress { transform-origin: 0 50%; animation: grow linear; animation-timeline: scroll(root); }\n  @keyframes grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }\n}\n```\n\n**Limits**: one header animation. A header that shrinks, changes colour, rotates its logo and slides is distracting. Respect reduced motion.\n"
 },
 {
  "file": "entries/header/header-centered-logo.md",
  "source": "---\nid: header-centered-logo\ntitle: Centred logo header\ncategory: header\nsummary: Logo centred with menu and utilities at the sides or below; classic for boutiques, restaurants and fashion.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, centered, logo, classic, boutique]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 3\nrelated: [header-split, header-editorial]\nversion: 1\n---\n**Variants**: logo centred above a centred link row (two tiers), or logo centred with menu button left and cart right (one tier, common on phones).\n\n**Two tier**: logo 32 to 56px tall, links 12 to 14px caps below with 16px gap. Collapse the top tier on scroll to keep the header short.\n\n**One tier**: grid `1fr auto 1fr` as in the split header so the logo is exactly centred.\n\n**Watch out**: long wordmarks crowd the sides on phones. Set a max width on the logo (40 to 50% of viewport) and use the mobile logo if the theme has one.\n"
 },
 {
  "file": "entries/header/header-editorial.md",
  "source": "---\nid: header-editorial\ntitle: Editorial header\ncategory: header\nsummary: A masthead style header with a large wordmark, a row of section links and dates or issue info, for publishers and editorial brands.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, editorial, masthead, magazine]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 3\nrelated: [style-editorial, header-centered-logo]\nversion: 1\n---\n**Shape**: a wordmark set large (40 to 96px) across the top, a thin rule, then a row of section links in small caps. On scroll, collapse to a compact bar with the small logo.\n\n**Details that carry information**: today's date, the latest issue, a location. Only if real and maintained.\n\n**Type**: wordmark in the display serif; links 12 to 14px caps, tracking 0.1em.\n\n**Phones**: the wordmark shrinks to fit one line (clamp), section links move into a horizontally scrollable row or the menu drawer.\n\n**Avoid**: a masthead that takes more than 30% of the first screen on phones; fake \"Vol. 01\" furniture.\n"
 },
 {
  "file": "entries/header/header-floating.md",
  "source": "---\nid: header-floating\ntitle: Floating header\ncategory: header\nsummary: A detached header bar with margin from the edges; when it fits, and how to stop it becoming the generic floating pill nav.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, floating, detached, pill-nav]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 2\nrelated: [header-sticky, anti-slop-excessive-radius]\nversion: 1\n---\n**What**: a header that floats inset from the viewport edges (12 to 24px), with its own background and maybe a radius.\n\n**When it fits**: over immersive imagery, product sites with a tool feel, or when the concept calls for layers. It is a common machine default (blurred pill nav centred at the top), so choose it deliberately.\n\n**Specs**: inset 12 to 16px on phones, 16 to 24px desktop; solid background (or glass only when the concept is glassmorphism, with a solid fallback); radius consistent with the rest of the site (do not use a 999px pill if buttons are 6px).\n\n**Avoid**: covering content as you scroll (add top padding to the page equal to header height plus inset); low contrast translucent backgrounds.\n"
 },
 {
  "file": "entries/header/header-fullscreen-menu.md",
  "source": "---\nid: header-fullscreen-menu\ntitle: Full screen menu overlay\ncategory: header\nsummary: A menu that takes the whole screen with large links; focus trap, scroll lock, Escape and the motion to open it.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, fullscreen, overlay-menu, menu-takeover, big-menu]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 3\nrelated: [header-mobile-menu, component-dialog, motion-page-transitions]\nversion: 1\n---\n**When**: brand led sites with few pages (studios, events, portfolios); makes navigation an experience.\n\n**Content**: large links (32 to 64px), maybe secondary info (contact, socials, address) in small type. Not a place to cram 20 links.\n\n**Behaviour**: the button has `aria-expanded` and `aria-controls`; open moves focus to the first link; focus is trapped inside; Escape closes and returns focus to the button; page scroll locked while open (`overflow: hidden` on html, with scrollbar gutter compensation).\n\n**Motion**: overlay fades or wipes in 300 to 450ms; links stagger 30 to 50ms each. Under reduced motion, show instantly.\n\n**Storelib**: the built-in menu drawer can be opened with `data-storelib-menu` from a custom header; or render the link_list in the section's own overlay.\n"
 },
 {
  "file": "entries/header/header-minimal.md",
  "source": "---\nid: header-minimal\ntitle: Minimal header\ncategory: header\nsummary: Logo, three to five links and one action; the default good header and its exact spacing.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, minimal, simple, logo-left]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 4\nrelated: [header-mobile-menu, style-minimalism]\nversion: 1\n---\n**Shape**: logo left, links right (or centred), one primary action at the far right. Height 56 to 64px on phones, 64 to 80px on desktop.\n\n**Links**: 3 to 5 top level items in the real menu (link_list). More than 6 means the information architecture needs work or a mega menu.\n\n**Type**: 14 to 16px, regular or medium weight, sentence case or small caps tracked. Active page indicated by underline or weight, plus `aria-current=\"page\"`.\n\n**Spacing**: 24 to 32px between links; padding on each link so the hit area is at least 44px tall.\n\n**Action**: one button (Book, Shop, Join). Cart and account as icons with accessible names if the store has them.\n\n```html\n<header class=\"site-header\">\n  <a href=\"/\" class=\"logo\" aria-label=\"Home\">Studio Name</a>\n  <nav aria-label=\"Main\"><ul><li><a href=\"/work\" aria-current=\"page\">Work</a></li><li><a href=\"/about\">About</a></li></ul></nav>\n  <a class=\"btn\" href=\"/contact\">Get in touch</a>\n</header>\n```\n"
 },
 {
  "file": "entries/header/header-mobile-menu.md",
  "source": "---\nid: header-mobile-menu\ntitle: Mobile menus\ncategory: header\nsummary: Phone navigation patterns (drawer, full screen, bottom bar), the menu button, touch sizes, nested items and closing behaviour.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, mobile, hamburger, drawer, bottom-nav, phone]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 5\nrelated: [header-fullscreen-menu, component-drawer, responsive-touch]\nversion: 1\n---\n**Button**: visible label \"Menu\" or an icon with `aria-label=\"Menu\"`; at least 44x44px; `aria-expanded` reflects state.\n\n**Patterns**\n- *Drawer* from the side or top: good default; 80 to 90% width, the page dimmed behind.\n- *Full screen*: for few links and brand led sites.\n- *Bottom bar*: for app like sites with 3 to 5 destinations used repeatedly (a community). Mind the iOS home indicator: `padding-bottom: env(safe-area-inset-bottom)`.\n\n**Items**: 48px minimum height, 16 to 18px type, nested items as expandable groups (button with aria-expanded), not hover menus.\n\n**Closing**: Escape, close button, tapping the backdrop, and navigating to a link. Return focus to the menu button.\n\n**Primary action**: keep the main action (Book, Shop) visible in the bar, not only inside the menu.\n\n**Storelib**: `data-storelib-menu=\"{{ settings.menu.handle }}\"` opens the built-in drawer; `data-storelib-menu-from` chooses the side.\n"
 },
 {
  "file": "entries/header/header-none.md",
  "source": "---\nid: header-none\ntitle: No header\ncategory: header\nsummary: When to drop the header entirely (single action landing pages, link in bio) and what must still be reachable.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, no-header, headerless, single-page, landing]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 2\nrelated: [header-minimal, footer-minimal]\nversion: 1\n---\n**When**: a single page with one action (a pack launch, an event ticket page, a link in bio page), or an experimental site whose navigation lives elsewhere.\n\n**Still required**: the brand name visible in the first screen; a way to reach important pages (footer links or an in page index); the cart if the site sells (a floating cart button); skip links still valid.\n\n**Don't**: remove the header from a multi page site to look minimal. People rely on it to move around.\n"
 },
 {
  "file": "entries/header/header-side.md",
  "source": "---\nid: header-side\ntitle: Side navigation\ncategory: header\nsummary: A fixed vertical navigation on the left for portfolios and archives; widths, scrolling and phone behaviour.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, sidebar, vertical, side-nav, fixed-left]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 2\nrelated: [style-portfolio, header-mobile-menu]\nversion: 1\n---\n**When**: portfolios, archives, galleries and documentation, where navigation is browsed constantly. Not for typical marketing sites.\n\n**Specs**: width 200 to 280px, fixed, its own scroll if long (`overflow-y: auto; overscroll-behavior: contain`), main content offset by the same width.\n\n**Type**: a compact list, 14 to 15px, active item marked with weight and `aria-current`.\n\n**Phones**: becomes a top bar with a menu button; the vertical list moves into a drawer. Never keep a fixed sidebar on a phone.\n"
 },
 {
  "file": "entries/header/header-split.md",
  "source": "---\nid: header-split\ntitle: Split navigation header\ncategory: header\nsummary: Links divided either side of a centred logo; balancing uneven menus and collapsing on smaller screens.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, split, centered-logo, balanced]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 2\nrelated: [header-centered-logo, header-mobile-menu]\nversion: 1\n---\n**Shape**: half the links left, logo centred, the other half and the action right. Common for hospitality, fashion and luxury.\n\n**Balance**: needs an even number of similar length items. With an odd number, put utility items (search, cart, account) on the right to balance.\n\n**Implementation**: a three column grid keeps the logo truly centred regardless of side widths.\n\n```css\n.split-header { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; }\n.split-header .left { justify-self: start; } .split-header .right { justify-self: end; }\n```\n\n**Collapse**: below about 960px switch to logo centre, menu button left, cart right.\n"
 },
 {
  "file": "entries/header/header-sticky.md",
  "source": "---\nid: header-sticky\ntitle: Sticky and hide on scroll headers\ncategory: header\nsummary: Keeping navigation reachable while scrolling: sticky with position, hide on scroll down and reveal on scroll up, and offsets for anchors.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, sticky, fixed, hide-on-scroll, auto-hide]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 4\nrelated: [header-transparent, header-minimal]\nversion: 1\n---\n**Sticky**: `position: sticky; top: 0; z-index: 50;` on the header (no JS). Make sure no ancestor has `overflow: hidden`.\n\n**Hide on scroll down, show on scroll up** saves space on phones:\n\n```js\nlet last = scrollY;\naddEventListener('scroll', () => { const y = scrollY; header.dataset.hidden = String(y > last && y > 120); last = y; }, { passive: true });\n```\n```css\nheader { transition: transform .25s ease; }\nheader[data-hidden=\"true\"] { transform: translateY(-100%); }\n@media (prefers-reduced-motion: reduce) { header { transition: none; } }\n```\nNever hide it while focus is inside it or a menu is open.\n\n**Anchors**: set `scroll-margin-top` on targets (or `scroll-padding-top` on html) equal to the header height so headings are not hidden under it.\n\n**Height**: a sticky header should be 56 to 72px; taller headers eat phone screens.\n"
 },
 {
  "file": "entries/header/header-transparent.md",
  "source": "---\nid: header-transparent\ntitle: Transparent header over the hero\ncategory: header\nsummary: A header that sits over the first image and turns solid after scrolling; contrast, scroll threshold and implementation.\nintents: [design-header, build-section, navigation]\ntags: [header, navigation, nav, transparent, overlay, hero]\ncomponents: [header, navigation]\nphases: [plan, build]\npriority: 4\nrelated: [hero_immersive, header-sticky, layout-full-bleed]\nversion: 2\n---\n**When**: the first section is a full bleed image or video and the brand wants the image to start at the top edge.\n\n**Contrast**: logo and links must pass 3:1 (icons) and 4.5:1 (text) against every part of the image under them. Add a top scrim (`linear-gradient(to bottom, rgba(0,0,0,.45), transparent)`, 120 to 160px tall) rather than hoping.\n\n**Solid after scroll**: switch to a solid background after about 40 to 80px of scroll with a scroll timeline on the page's scroller, no script (a section's script runs in a sandbox and cannot see the page scroll):\n\n```css\n@supports (animation-timeline: scroll()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .hdr { animation: hdr-solid linear both; animation-timeline: scroll(root); animation-range: 0 80px; }\n    @keyframes hdr-solid { to { background-color: var(--s-bg); color: var(--s-text); box-shadow: 0 1px 0 var(--s-border); } }\n  }\n}\n```\nWithout support (or with reduced motion) start solid instead of transparent, so the text is always readable.\n\n**Logo variants**: provide a light and dark logo or use `currentColor` SVG so it flips with the header.\n\n**Pages without a hero**: the header must be solid there; do not leave white text over a white page.\n"
 },
 {
  "file": "entries/industry/industry-agency.md",
  "source": "---\nid: industry-agency\ntitle: Agencies and studios\ncategory: industry\nsummary: Studio sites that show selected work, how they work and who they are, with a confident point of view rather than service icon grids.\nintents: [build-site, plan-site]\ntags: [agency, studio, consultancy, branding-agency, web-agency, marketing-agency, collective]\nindustries: [agency, studio, consultancy]\nphases: [concept, plan]\npriority: 3\nrelated: [style-agency, industry-portfolio, layout-asymmetric-grid]\nversion: 1\n---\n**Visitor**: a potential client checking taste, relevant experience and whether the people seem good to work with.\n\n**Structure**: a statement of what the studio believes or does, set large -> selected work (three to six case studies, real clients only) -> services as a plain list with one line each, not icon tiles -> approach in a few numbered steps only if the steps are genuinely sequential -> people (real photos) -> recognition only if real -> contact with a direct email and what to include in a brief.\n\n**Visual**: agencies are where trend chasing is most visible. Choose a direction that matches the studio's actual output: a branding studio can be type led and bold; an engineering studio can be precise and Swiss; a production company can be cinematic dark with video. Show their work large; the site frame should be quieter than the work.\n\n**Signature moves** that fit: a running list of clients as a typographic marquee (real clients only), a large index of projects with hover previews, case study pages with project specific colour.\n\n**Avoid**: \"We craft digital experiences\", stats like \"200+ projects\" without basis, three service cards with icons, stock team handshake photos, a contact form with 12 fields.\n"
 },
 {
  "file": "entries/industry/industry-architecture.md",
  "source": "---\nid: industry-architecture\ntitle: Architecture and design studios\ncategory: industry\nsummary: Projects as large single images with a title block of facts; the work is the hero and the type stays out of its way.\nintents: [build-site, plan-site, choose-style]\ntags: [architecture, architect, interior, design-studio, building, landscape, urbanism]\nindustries: [architecture, interior]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a client or a jury comparing studios, on a laptop more often than not, judging taste in the first ten seconds.\n\n**Style**: Swiss or minimal; one neutral ground (bone, concrete grey, off white), one accent taken from a material (patinated copper, brick, oxidised green). Direction seed: Plan and Section.\n\n**Layout moves**: a project index as a text list where the hovered row shows its image; each project a sequence of full bleed and two up images with a title block (year, location, area, status, team) set like a drawing sheet; a horizontal strip for process sketches; generous white space and very few words.\n\n**Type**: Inter Tight or Archivo display set small and tight, or a quiet serif (Instrument Serif) for statements; data in IBM Plex Mono or DM Mono.\n\n**Motion**: none to subtle; images crossfade on the index hover, no parallax on photos of buildings.\n\n**Imagery**: overcast, straight verticals, people small in frame; drawings and models as real content. **Avoid**: renders presented as photos, three service cards (\"Design, Build, Consult\"), awards the studio did not win.\n"
 },
 {
  "file": "entries/industry/industry-beauty-skincare.md",
  "source": "---\nid: industry-beauty-skincare\ntitle: Beauty, skincare and cosmetics\ncategory: industry\nsummary: Clinical calm or sensual richness, never pastel gradients; ingredients and routines as readable, honest tables.\nintents: [build-site, plan-site, choose-style]\ntags: [beauty, skincare, cosmetics, makeup, salon, spa, fragrance]\nindustries: [beauty, skincare, cosmetics]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: wants to know what is in it, whether it suits their skin, and the price, then wants checkout to be quick.\n\n**Style**: minimal contemporary ecommerce or dark luxury; stone, water and skin tones; one cool or one earthy accent. Seeds: Skin Lab, Velvet Room.\n\n**Layout moves**: product first with a texture swatch; an ingredient table (name, what it does, percentage only when supplied); a routine as numbered steps with morning and evening tabs; before and after only with real, supplied photos and a slider that works by keyboard; the site's own cart drawer that shows the routine total.\n\n**Type**: Sora or Instrument Sans for a clinical feel, Bodoni Moda or Cormorant for a fragrance house; text at 16 to 17px.\n\n**Motion**: subtle: images that settle, a soft hover zoom on texture.\n\n**Imagery**: product on stone and water, real skin without retouching, hands applying. **Avoid**: pastel gradients and blobs, \"clean beauty\" claims the store did not make, invented reviews, percentages of results.\n"
 },
 {
  "file": "entries/industry/industry-cafe-bakery.md",
  "source": "---\nid: industry-cafe-bakery\ntitle: Cafes, bakeries and coffee roasters\ncategory: industry\nsummary: Today's bakes and opening hours before anything else; warm, crumbly, neighbourly, set like a shop board.\nintents: [build-site, plan-site, choose-style]\ntags: [cafe, bakery, coffee, roaster, patisserie, brunch, breakfast]\nindustries: [cafe, bakery, coffee, food]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: nearby, on a phone, wants hours, where, and what is out of the oven or on the menu today.\n\n**Style**: organic or playful; a warm cream ground, a crust or espresso brown accent, maybe one fresh colour from the shop front. Seeds: Morning Crumb, Mise en Place.\n\n**Layout moves**: a daily board (bake, time it comes out, sold out state as real text); hours and address pinned in the first screen; the menu as a printed card with dotted leaders; a slow marquee of today's names; beans or bread as products with origin, roast or flour in a small spec list.\n\n**Type**: Fredoka or Young Serif display with Nunito Sans or Libre Franklin text; numerals tabular for prices and times.\n\n**Motion**: expressive but small: a marquee, a press down button. Respect reduced motion.\n\n**Imagery**: crumb and crust close ups, flour on counters, early light through the window, the actual staff. **Avoid**: stock latte art, feature cards (\"Fresh daily\"), invented reviews, hours only in the footer.\n"
 },
 {
  "file": "entries/industry/industry-coaching.md",
  "source": "---\nid: industry-coaching\ntitle: Coaches and consultants (business, life, career)\ncategory: industry\nsummary: Personal service sites built on the person, a clear method and an easy first step, without guru clichés.\nintents: [build-site, plan-site]\ntags: [coaching, coach, consultant, mentor, business-coach, life-coach, career, therapist, advisor]\nindustries: [coaching, consulting]\nphases: [concept, plan]\npriority: 4\nrelated: [coach, industry-fitness-coach, storelib-bookings, storelib-forms]\nversion: 1\n---\n**Visitor**: has a problem and is checking whether this person understands it and is safe to talk to.\n\n**Structure**: the problem in the visitor's words and who you help -> the person (warm portrait, short real story) -> how working together goes (first call, sessions, between sessions) -> offers with price or \"from\" price the creator set -> real client words if any -> booking or enquiry -> FAQ.\n\n**First step**: a free call is booked through a booking form with real availability, or an enquiry form with three or four fields. Do not invent a calendar.\n\n**Visual**: coaching sites default to beige, script fonts and arms-wide stock photos. Better: an editorial personal brand (large portrait, serif, generous margins); a practical consultancy (clean grotesk, structured, data friendly); a bold personality (strong colour from the coach's wardrobe or brand, oversized quotes in their voice).\n\n**Copy**: specific situations (\"You run a team of 6 for the first time\"), not \"Step into your power\". No income claims, no \"6 figure\" promises.\n\n**Proof**: named quotes with permission, media appearances that happened. No made up logos of companies.\n"
 },
 {
  "file": "entries/industry/industry-craft-ceramics.md",
  "source": "---\nid: industry-craft-ceramics\ntitle: Makers, ceramics and craft\ncategory: industry\nsummary: Hands, materials and process; small batches shown honestly, with the making as the story.\nintents: [build-site, plan-site, choose-style]\ntags: [ceramics, pottery, craft, maker, handmade, woodwork, textile, weaving, candles]\nindustries: [craft, ceramics, maker]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: someone who values how a thing is made, browsing slowly, often from social media.\n\n**Style**: organic; clay, stone and linen tones, one fired glaze colour as the accent. Seeds: Clay Studio, Showroom Floor.\n\n**Layout moves**: a process sequence (throwing, drying, glazing, firing) as a horizontal scroll gallery; products in small batches with a sold out state as text; a studio visit or workshop section that links to real bookings; an arch or kiln shaped image mask repeated as the one motif.\n\n**Type**: Fraunces soft display with Karla text, or Gloock with Spectral for a more literary maker.\n\n**Motion**: subtle; a slow reveal of each process step.\n\n**Imagery**: hands at work, raw material, side light, the studio mess. **Avoid**: white background catalogue only, \"handcrafted with love\", invented waitlists.\n"
 },
 {
  "file": "entries/industry/industry-dance-studio.md",
  "source": "---\nid: industry-dance-studio\ntitle: Dance, yoga and movement studios\ncategory: industry\nsummary: The timetable is the product: today first, filters by level, kinetic type and real class names.\nintents: [build-site, plan-site, choose-style]\ntags: [dance, yoga, pilates, barre, movement, studio, classes, martial-arts]\nindustries: [dance, yoga, studio]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: wants the next class they can make, its level and how to book.\n\n**Style**: experimental fitness or calm wellness depending on the studio. Seeds: Studio Floor, Quiet Strength.\n\n**Layout moves**: a timetable board with today first and level filters (tabs that work by keyboard); class types as sticky stacked cards; teachers as a hover image reveal list; pricing as a plain table of passes from the store's products; first class guidance as an accordion.\n\n**Type**: Antonio or Barlow Condensed for kinetic display, Hanken Grotesk text; Fraunces and Karla for a calm yoga studio.\n\n**Motion**: expressive in a dance studio (split text, stagger), barely any in a yoga studio.\n\n**Imagery**: movement with blur, rehearsal rooms, real students. **Avoid**: lotus pose stock, \"transform your body\", invented member counts.\n"
 },
 {
  "file": "entries/industry/industry-digital-creator.md",
  "source": "---\nid: industry-digital-creator\ntitle: Digital product creators\ncategory: industry\nsummary: Selling templates, presets, ebooks, guides and tools: show what is inside, preview it honestly, deliver it clearly.\nintents: [build-site, plan-site, product-page]\ntags: [digital-products, templates, presets, ebook, guide, notion, lightroom, printables, downloads, creator]\nindustries: [digital-products, creator]\nphases: [concept, plan]\npriority: 4\nrelated: [digital_products, creator, storelib-digital-downloads, component-product-showcase]\nversion: 1\n---\n**Visitor**: comparing a few similar products, wants to see inside before buying, worried about getting something thin.\n\n**Product page structure**: name and the specific result (\"A Notion system for running a 2 person studio\") -> previews: real screenshots or page spreads, ideally a scrollable look inside -> what is included as a precise list (pages, files, formats, compatible apps and versions) -> who it is for and who it is not for -> price and buy -> delivery (instant download, link by email) -> refund policy if one exists -> FAQ.\n\n**Home**: the creator (face and voice matter here), featured product, the rest of the catalogue from the store, free resource or newsletter if one exists.\n\n**Visual**: let the product's own look set the site. A minimal planner shop can be paper white and precise; a Lightroom preset shop uses before and after sliders with the creator's own photos; a font or icon shop uses the asset itself as the hero.\n\n**Honesty rules**: no invented download counts or \"bestseller\" labels unless store data supports them; no fake reviews; mockups must show the actual file, not a stock tablet with something else on it.\n\n**Storelib**: digital products deliver files after checkout. Bundles are their own products with their own price.\n"
 },
 {
  "file": "entries/industry/industry-education.md",
  "source": "---\nid: industry-education\ntitle: Online courses, cohorts and education\ncategory: industry\nsummary: Course sales and catalogue pages: outcome first, curriculum, teacher, format, price, and enrolment that matches Storelib's course products.\nintents: [build-site, plan-site, product-page]\ntags: [course, courses, education, cohort, academy, curriculum, lessons, teaching, workshop, class]\nindustries: [education, courses, academy]\nphases: [concept, plan]\npriority: 5\nrelated: [course, curriculum, storelib-programs-courses, component-accordion]\nversion: 1\n---\n**Visitor**: wants a specific outcome and is judging whether this teacher and format will get them there, in the time they have.\n\n**Course page**: the outcome as the headline -> who it is for and the format (self paced, live cohort, start date, hours per week) -> what you will be able to do, as four to six concrete abilities -> curriculum from the course's real modules, expandable -> the teacher -> student work or results if supplied -> price and what is included (lifetime access? community? feedback?) -> FAQ (level, time, refunds, access) -> enrol.\n\n**Catalogue**: filter by level or topic only when there are enough courses (more than about eight). Each card: title, one line outcome, length, level, price. Same image ratio for all.\n\n**Visual directions**: a textbook feel (serif, numbered chapters, margins with notes); a studio class feel (big photos of hands at work); a technical school (mono, grids, code or diagrams). Avoid the stock laptop and coffee photo.\n\n**Motion**: an accordion for modules, maybe progress indicators. Keep it light; people read course pages carefully.\n\n**Honesty**: never invent student counts, completion rates or \"rated 4.9\". Start dates and seats come from the product or event data.\n"
 },
 {
  "file": "entries/industry/industry-events-nightlife.md",
  "source": "---\nid: industry-events-nightlife\ntitle: Events, parties, festivals and venues\ncategory: industry\nsummary: The next date and the ticket button first, line ups and schedules as scannable lists, atmosphere through real photos and rhythm.\nintents: [build-site, plan-site]\ntags: [events, party, festival, club, nightlife, gig, concert, tickets, venue, line-up]\nindustries: [events, nightlife, venue, festival]\nphases: [concept, plan]\npriority: 4\nrelated: [nightlife, event_spotlight, schedule, tickets, motion-marquee]\nversion: 1\n---\n**Visitor**: deciding what to do this week, on a phone, often late. Date, place, price and ticket link must be readable in the first screen.\n\n**Structure**: next event with date, venue and Get tickets -> upcoming dates as a list (date, name, venue, price, ticket link, sold out state from real data) -> line up or hosts -> gallery of past nights -> venue info (address, doors, age, accessibility) -> FAQ -> newsletter for announcements.\n\n**Visual**: this is where loud is appropriate. Condensed display type at huge sizes, a marquee of dates, dark palettes with one hot accent, full bleed photos with grain. Still pick a concept: a jazz club and a techno night are not the same site.\n\n**Lists over cards**: a schedule reads faster as rows than as a grid of cards. Each row is one link target to the event page.\n\n**Motion**: rhythmic is fine (marquee, staggered entrances) but the date and button never move. Respect reduced motion.\n\n**Honesty**: no \"selling fast\" without sales data, no fake countdowns, line up only as announced. Ticket prices and availability come from products or events.\n"
 },
 {
  "file": "entries/industry/industry-fashion.md",
  "source": "---\nid: industry-fashion\ntitle: Fashion and apparel brands\ncategory: industry\nsummary: Image led shopping pages for clothing labels: lookbooks, collections, product grids from the store, size and fit, drops.\nintents: [build-site, plan-site, product-page, collection-page]\ntags: [fashion, apparel, clothing, streetwear, label, lookbook, drop, garments, wear]\nindustries: [fashion, apparel, clothing]\nphases: [concept, plan]\npriority: 5\nrelated: [apparel, luxury_fashion, style-fashion, component-product-showcase, storelib-products]\nversion: 1\n---\n**Visitor**: browsing with their eyes. Photography quality and how product images sit together matter more than any copy.\n\n**Structure**: a campaign image or short video with the current collection name -> the collection from the store in a grid that respects the photo ratio (4:5 or 3:4 for garments on body) -> a lookbook or editorial story -> brand line (who makes it, where) -> second collection or bestsellers from the store -> newsletter for drops.\n\n**Product grid rules**: one consistent image ratio, second image on hover only if the product has one, name and price in small type under the image, no card borders or shadows around photos, sold out from the product's real availability. Two columns on phones, three or four on desktop.\n\n**Product page**: large gallery (swipe on phones), name, price, variant pickers with real stock, size guide link if one exists, add to bag, materials and care from product fields. Do not invent fit notes.\n\n**Directions**: streetwear is not only black and red; try a technical catalogue look (mono specs, numbered garments) or a sunlit editorial (warm whites, serif). Luxury see `industry-luxury-brand`.\n\n**Never**: fake \"only 2 left\", made up reviews, discount banners the creator did not set, product prices typed into markup.\n"
 },
 {
  "file": "entries/industry/industry-film-video.md",
  "source": "---\nid: industry-film-video\ntitle: Film, video and production\ncategory: industry\nsummary: Cinematic stills and a reel with a visible pause; credits as real lists; dark, letterboxed, precise.\nintents: [build-site, plan-site, choose-style]\ntags: [film, video, production, director, cinematographer, editor, animation, studio]\nindustries: [film, video]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a producer or brand looking at the work and who did it.\n\n**Style**: dark cinematic with a precise grotesk. Seed: Second Reel.\n\n**Layout moves**: a muted reel as the hero with a real pause button; a project index where each row shows a still on hover; stills in 2.39:1 letterbox; credits rolling as a real list of roles and names; a screening or festival list only with supplied dates.\n\n**Type**: Schibsted Grotesk or League Gothic display, Work Sans or Karla text; credits in small tracked caps.\n\n**Motion**: cinematic but controlled: slow fades, clip path reveals; all off under reduced motion; video never autoplays with sound.\n\n**Imagery**: stills with grain, behind the scenes on set. **Avoid**: glowing gradients, festival laurels the work did not win, generic camera icons.\n"
 },
 {
  "file": "entries/industry/industry-fitness-coach.md",
  "source": "---\nid: industry-fitness-coach\ntitle: Fitness coach and personal trainer sites\ncategory: industry\nsummary: Structure, proof, offers and visual directions for personal trainers, strength coaches and online fitness programmes.\nintents: [build-site, plan-site, choose-style]\ntags: [fitness, coach, personal-trainer, gym, strength, training, workout, pt, athlete]\nindustries: [fitness, fitness-coach, personal-trainer, gym]\nphases: [concept, plan]\npriority: 5\nrelated: [coach, industry-coaching, storelib-bookings, storelib-programs-courses]\nversion: 1\n---\n**Visitor**: someone who has tried on their own and wants a person to follow. They judge on whether the coach looks credible for *their* body and goal, and how easy it is to start.\n\n**Structure**: hero with who it is for and the starting action (book a call, start the programme) -> the coach (a real photo, a real story, qualifications that exist) -> how it works (consult, plan, check ins) -> programmes or packages from the store -> results only if real (client quotes with consent, before and after only if supplied) -> schedule or booking -> FAQ (equipment, level, injuries, cancellation) -> action again.\n\n**Directions that are not the default** (the default is black, neon green, condensed caps, sweaty stock):\n- *Quiet strength*: cream, olive, serif display, slow natural light photos. For mobility, pre and postnatal, older clients.\n- *Training log*: off white, black rules, monospace numbers, a ticker of session times. For strength and powerlifting.\n- *Sunrise club*: warm coral and sand, rounded grotesk, outdoor group shots. For run clubs and bootcamps.\n- *Editorial athlete*: big cropped photography, narrow serif captions, magazine grid. For coaches with a strong personal image.\n\n**Proof rules**: no invented transformations, no \"500+ clients\" unless the creator said so. Prefer a short real quote with a first name and goal over a carousel of five vague ones.\n\n**Storelib**: programmes are digital products or courses; sessions are bookings; a members area is a community. Show the real price from the product.\n"
 },
 {
  "file": "entries/industry/industry-furniture-interior.md",
  "source": "---\nid: industry-furniture-interior\ntitle: Furniture, homeware and interiors\ncategory: industry\nsummary: Objects in real rooms, materials up close and dimensions drawn; a calm grid that changes scale on purpose.\nintents: [build-site, plan-site, choose-style]\ntags: [furniture, homeware, interior, lighting, textiles, decor, rugs]\nindustries: [furniture, interior, homeware]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: imagining an object in their own room: size, material, care, delivery, price.\n\n**Style**: contemporary ecommerce with editorial pacing; warm greys, oak, linen; an accent from a signature material. Seed: Showroom Floor.\n\n**Layout moves**: a product grid with uneven sizes (one large, several small) instead of equal tiles; room scenes between product rows; a materials library (wood, finish, fabric) as a horizontal gallery; dimensions as a small line drawing or a table; a hover image reveal list for collections.\n\n**Type**: Familjen Grotesk or Hanken Grotesk display, Karla text; numbers tabular for dimensions and prices.\n\n**Motion**: subtle: a second image on hover, a sticky product summary while the details scroll.\n\n**Imagery**: real rooms, daylight, material close ups, the workshop. **Avoid**: white cut outs only, 3D renders as photos, invented lead times, discount banners that are not real.\n"
 },
 {
  "file": "entries/industry/industry-hotel-travel.md",
  "source": "---\nid: industry-hotel-travel\ntitle: Hotels, guesthouses and retreats\ncategory: industry\nsummary: Sell the feeling of the stay: slow full screen images, rooms with one line each, booking always one tap away.\nintents: [build-site, plan-site, choose-style]\ntags: [hotel, guesthouse, retreat, travel, bnb, inn, resort, villa, hospitality]\nindustries: [hotel, travel, hospitality]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: planning a trip, comparing on a phone, wants rooms, prices, dates and how to get there.\n\n**Style**: luxury or light editorial; sand, linen, olive or sea tones taken from the place. Seed: Slow Stay.\n\n**Layout moves**: full screen photographs that hold still; each room introduced by an italic line and the view from its window; a sticky booking bar at the bottom on phones that goes to the real booking form or page; a map and the journey written as steps (train, taxi, walk); a seasonal calendar if the place changes through the year.\n\n**Type**: Instrument Serif or Cormorant Garamond italic for display, Instrument Sans or Jost for text, tiny tracked caps for labels.\n\n**Motion**: subtle: slow crossfades, a clip path reveal on scroll; never autoplay sound.\n\n**Imagery**: morning light, unmade beds, landscape through windows, nobody posing. **Avoid**: drone shots as the only image, \"luxury experience\" copy, fake star ratings, prices that are not real.\n"
 },
 {
  "file": "entries/industry/industry-jewellery.md",
  "source": "---\nid: industry-jewellery\ntitle: Jewellery and watches\ncategory: industry\nsummary: One piece per screen at real scale, macro then worn; precise type, hard light, no sparkle effects.\nintents: [build-site, plan-site, choose-style]\ntags: [jewellery, jewelry, rings, watches, goldsmith, silversmith, accessories]\nindustries: [jewellery, jewelry, luxury]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: comparing a considered purchase: material, size, price, delivery and returns.\n\n**Style**: fashion and luxury, quiet. Seed: Gold Standard.\n\n**Layout moves**: one piece per screen; macro detail followed by the piece worn; a ruler line showing real size; materials and care in a small table; size guide as an accordion; the site's own cart drawer with the engraving note if the product supports it.\n\n**Type**: Bodoni Moda caps or Italiana display with Jost text; tiny tracked caps for labels and prices.\n\n**Motion**: subtle: slow image settle, no glitter, no shimmer loops.\n\n**Imagery**: stone, skin and hard shadow, macro focus. **Avoid**: sparkle animations, gradient gold text, invented celebrity mentions.\n"
 },
 {
  "file": "entries/industry/industry-local-service.md",
  "source": "---\nid: industry-local-service\ntitle: Local services (trades, salons, clinics, studios)\ncategory: industry\nsummary: Sites for plumbers, salons, tattoo studios, tutors and clinics: service area, prices, availability and contact made obvious.\nintents: [build-site, plan-site]\ntags: [local, service, salon, barber, tattoo, plumber, cleaner, tutor, clinic, trades, repair, studio]\nindustries: [local-service, salon, trades]\nphases: [concept, plan]\npriority: 3\nrelated: [storelib-bookings, storelib-forms, header-sticky]\nversion: 1\n---\n**Visitor**: needs something done, wants to know if you cover their area, roughly what it costs and how fast they can get you.\n\n**Structure**: what you do and where, in the first line -> call or book button that is always reachable (sticky on phones) -> services with prices or \"from\" prices the creator gave -> examples of work (a salon's real cuts, a builder's real jobs) -> area covered and hours -> reviews only if real, with source -> FAQ -> contact.\n\n**Mobile**: tap to call (`<a href=\"tel:...\">`), tap for directions, booking in two taps. The phone is the main device.\n\n**Visual**: match the trade's own culture. A barber can be bold and graphic; a dental clinic calm and clinical; a tattoo studio dark with the artists' flash as imagery. Use the business's real photos; stock trades photos are instantly recognisable.\n\n**Don't**: invent certifications, years in business, \"5 star\" badges or review counts. If reviews live on another site, link to them rather than copying numbers.\n\n**Storelib**: appointments are bookings with real availability; quotes are forms with service type, area and photos upload if supported.\n"
 },
 {
  "file": "entries/industry/industry-luxury-brand.md",
  "source": "---\nid: industry-luxury-brand\ntitle: Luxury and premium brands\ncategory: industry\nsummary: Restraint, space, exceptional imagery and precise type; how premium brands sell without discounts, badges or noise.\nintents: [build-site, plan-site, choose-style]\ntags: [luxury, premium, high-end, jewellery, watches, fragrance, couture, boutique, atelier]\nindustries: [luxury, jewellery, fragrance, premium]\nphases: [concept, plan]\npriority: 4\nrelated: [luxury_fashion, quiet_luxury, style-luxury, typography-pairings]\nversion: 1\n---\n**Principle**: luxury is the absence of pressure. Fewer elements, more space, slower pace, exact details.\n\n**Structure**: a single image or film with the brand name and nothing else -> a collection or the craft story told in two or three spreads -> products from the store with large imagery, name and price in small type -> the atelier or maker -> appointments or contact (a private viewing is a booking) -> discreet newsletter.\n\n**Type**: a refined serif or a thin, wide sans for display, set with generous tracking in capitals for small labels (0.1em to 0.2em), sentence case for body. Small body sizes (15 to 16px) with large leading are fine on desktop; never below 16px on phones.\n\n**Colour**: ivory, bone, charcoal, black, or one deep brand colour (bottle green, oxblood, navy). Gold only as a hairline or in photography, never as a gradient fill.\n\n**Motion**: slow (600 to 900ms), eased out, image reveals with a mask, nothing bouncy.\n\n**Never**: discount banners, \"SALE\", countdowns, badges, emoji, review stars, pill buttons, more than one call to action per screen. Prices come from the store; do not hide them unless the creator asked.\n"
 },
 {
  "file": "entries/industry/industry-membership-community.md",
  "source": "---\nid: industry-membership-community\ntitle: Memberships and communities\ncategory: industry\nsummary: Selling access to a community or membership: what members actually get, what it feels like inside, price and how joining works.\nintents: [build-site, plan-site, membership]\ntags: [membership, community, members, club, subscription, patreon, private-group, circle]\nindustries: [community, membership, club]\nphases: [concept, plan]\npriority: 4\nrelated: [community, storelib-memberships, storelib-community]\nversion: 1\n---\n**Visitor**: wants to know what happens after paying. \"Join the community\" with no detail is the most common failure.\n\n**Structure**: who it is for and what members do together -> what you get, concretely and with frequency (weekly calls, monthly pack, private feed, discounts) -> a look inside: real screenshots or a description of a typical week, never fake member avatars -> the host -> price and billing period from the product -> how to leave (cancel any time, if true) -> FAQ -> join.\n\n**Tiers**: only if the store has them. Show tiers side by side with differences highlighted, not repeated features.\n\n**Visual**: a community is people; use the creator's real photos of events or members who agreed. Warmer palettes, readable type, less spectacle. A club for a niche (film photographers, runners) should borrow the niche's own visual culture.\n\n**Don't**: show member counts unless real (\"Join 10,000+ members\"), stacks of random avatar circles, generic \"network with like minded people\" copy.\n\n**Storelib**: a membership is a recurring product; the community is a Storelib community the membership unlocks. Link the join action to the real checkout or join flow and show the real price.\n"
 },
 {
  "file": "entries/industry/industry-music-producer.md",
  "source": "---\nid: industry-music-producer\ntitle: Music producers, beat makers and sample pack sellers\ncategory: industry\nsummary: Sound first pages for producers selling sample packs, presets, beats and mixing services, with audio previews, licence clarity and real credits.\nintents: [build-site, plan-site, product-page]\ntags: [music, producer, beats, sample-packs, samples, presets, loops, mixing, audio, dj, artist]\nindustries: [music, music-producer, beats, audio]\nphases: [concept, plan]\npriority: 5\nrelated: [music, digital_products, component-media-player, storelib-digital-downloads]\nversion: 1\n---\n**Visitor**: another musician deciding in seconds whether the sound fits their work. Hearing is the proof; reading is secondary.\n\n**Structure for a pack page**: pack name and cover art -> a play button that works without scrolling -> what is inside (counts, formats, BPM range, key labels, file size) from the product's own fields -> a demo track and a few individual previews -> licence in one plain paragraph (royalty free? credit needed?) -> price and buy -> other packs.\n\n**Home**: latest release or pack front and centre, a strip of covers, credits (artists worked with) only if real, services (mixing, custom beats) with how to enquire.\n\n**Visual directions**: cover art drives the palette; pull the accent from the current release. Options: *tape lab* (warm off white, monospace specs, waveform as a thin line, analogue grain); *night bus* (near black, one saturated accent, condensed display); *gallery* (white, big square covers in a strict grid, tiny captions). Avoid generic equaliser bar animations and purple neon by default.\n\n**Audio rules**: never autoplay with sound. One player at a time (starting one pauses the others). Show duration and a scrubbable progress bar, keyboard operable. Previews come from the product's files, never placeholder audio.\n\n**Storelib**: packs are digital products with downloads delivered after checkout; beats with different licences are variants with real prices.\n"
 },
 {
  "file": "entries/industry/industry-non-profit.md",
  "source": "---\nid: industry-non-profit\ntitle: Non-profits, charities and causes\ncategory: industry\nsummary: Plain, urgent, accessible: one clear action per screen and where the money goes, in real numbers only.\nintents: [build-site, plan-site, choose-style]\ntags: [non-profit, nonprofit, charity, cause, foundation, volunteer, ngo, campaign]\nindustries: [non-profit, charity]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a possible donor, volunteer or someone who needs help. Many on phones, some with low vision or slow connections.\n\n**Style**: editorial with warmth; a cream ground, a deep green or blue accent, high contrast everywhere. Seed: Common Ground.\n\n**Layout moves**: big plain statements; one action per section (give, volunteer, get help); a table of where money goes using only numbers the organisation supplied; stories as documentary sequences with names only when given; an accessible donation flow (amount chips, then the real product or checkout link).\n\n**Type**: Hanken Grotesk display with Atkinson Hyperlegible text; body 17 to 18px.\n\n**Motion**: subtle, never needed to understand anything.\n\n**Imagery**: real people, places and work, documentary. **Avoid**: stock suffering, invented impact numbers, progress bars toward goals that do not exist, counters that animate made up figures.\n"
 },
 {
  "file": "entries/industry/industry-outdoor-gear.md",
  "source": "---\nid: industry-outdoor-gear\ntitle: Outdoor, surf, bike and adventure\ncategory: industry\nsummary: Field guide energy: conditions, routes and specs as data, with wide landscapes and a small figure.\nintents: [build-site, plan-site, choose-style]\ntags: [outdoor, surf, bike, cycling, climbing, hiking, camping, adventure, ski]\nindustries: [outdoor, sport, travel]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: an enthusiast who reads specs, or a beginner who needs the right first kit or tour.\n\n**Style**: industrial with editorial pacing. Seed: Field Guide.\n\n**Layout moves**: spec tables for gear; routes or trips numbered with distance and difficulty from real data; a conditions strip only if the creator supplies data; a journal of trips as an editorial archive; a horizontal gallery of the place.\n\n**Type**: Barlow Condensed display, IBM Plex Sans text, IBM Plex Mono for numbers.\n\n**Motion**: subtle: parallax only on one landscape, off under reduced motion.\n\n**Imagery**: wide landscapes with a small figure, gear in use, weather. **Avoid**: extreme sports stock, invented weather widgets, adrenaline copy.\n"
 },
 {
  "file": "entries/industry/industry-photography.md",
  "source": "---\nid: industry-photography\ntitle: Photographers\ncategory: industry\nsummary: Galleries that show photos large and uncropped, booking or enquiry for sessions, prints as products, and chrome that gets out of the way.\nintents: [build-site, plan-site, gallery]\ntags: [photography, photographer, wedding, portrait, prints, gallery, shoot, photos]\nindustries: [photography, photographer]\nphases: [concept, plan]\npriority: 4\nrelated: [photographer, noir_gallery, component-gallery, layout-masonry]\nversion: 1\n---\n**Rule one**: never crop someone else's composition into a square card. Show photos at their own ratio, or in a grid whose row heights adapt (justified rows) so nothing is cut.\n\n**Structure**: one strong image or a short sequence as the opening (no text over faces) -> galleries by type (weddings, portraits, commercial) -> about with a portrait of the photographer -> packages with real prices or \"from\" prices the creator set -> enquiry or booking form with date, location, type -> prints shop if products exist.\n\n**Gallery**: lightbox with keyboard arrows, Escape to close, swipe on touch, focus returned to the thumbnail; captions optional. Lazy load everything after the first row. Neutral surroundings: near white or near black, thin type, no drop shadows or rounded corners on photos.\n\n**Directions**: a gallery wall (white, generous margins, tiny sans captions); a darkroom (charcoal, warm grey type, images glow by contrast only); a zine (mixed sizes, handwritten-like display used once, tape or paper edges sparingly).\n\n**Don't**: watermarks across the whole image, auto playing slideshows with dissolves every 3 seconds, music, right click blockers.\n"
 },
 {
  "file": "entries/industry/industry-plants-florist.md",
  "source": "---\nid: industry-plants-florist\ntitle: Plant shops, florists and gardens\ncategory: industry\nsummary: Care cards, seasons and real stock; leafy and calm, with the delivery area and cut off times visible.\nintents: [build-site, plan-site, choose-style]\ntags: [plants, florist, flowers, garden, nursery, botanical]\nindustries: [plants, florist]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: buying a gift by a deadline, or a plant for a particular room.\n\n**Style**: organic and gently playful. Seed: Green Room.\n\n**Layout moves**: care cards (light, water, pet safety) for every plant; a seasonal list of what is in; delivery area and order cut off time near the buy button; plant size shown against a hand or a chair; the site's own cart drawer with a gift note.\n\n**Type**: Fraunces with Lexend text, or Instrument Serif with Instrument Sans for a florist studio.\n\n**Motion**: subtle; petals do not fall.\n\n**Imagery**: plants in real homes, stems and roots, the shop's own arrangements. **Avoid**: green gradients, generic leaf icons beside every heading, invented same day promises.\n"
 },
 {
  "file": "entries/industry/industry-podcast-media.md",
  "source": "---\nid: industry-podcast-media\ntitle: Podcasts, radio and media\ncategory: industry\nsummary: Episodes first, with guest, length and a play control; conversational type, warm and dark.\nintents: [build-site, plan-site, choose-style]\ntags: [podcast, radio, media, show, episodes, interview]\nindustries: [podcast, media]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: wants the latest episode, then the archive, then where to subscribe.\n\n**Style**: creator with typography led energy. Seed: Booth Light.\n\n**Layout moves**: the newest episode as the hero with its own player or a link to it; an episode index (number, guest, length, date) with search of the site's own; guests as a strip of portraits; subscribe links only to the platforms the creator gave.\n\n**Type**: Red Hat Display throughout, or Bricolage Grotesque with Hanken Grotesk.\n\n**Motion**: subtle: a level meter only while something plays.\n\n**Imagery**: mics, guests mid laugh, the room. **Avoid**: fake download numbers, chart rankings that were not supplied, generic microphone icons in every heading.\n"
 },
 {
  "file": "entries/industry/industry-portfolio.md",
  "source": "---\nid: industry-portfolio\ntitle: Designer, developer and creative portfolios\ncategory: industry\nsummary: The work is the page. Project index, case study rhythm, contact, and how to make a portfolio memorable without gimmicks.\nintents: [build-site, plan-site, choose-style]\ntags: [portfolio, designer, illustrator, developer, architect, creative, case-study, work, freelancer]\nindustries: [portfolio, design, creative, freelance]\nphases: [concept, plan]\npriority: 4\nrelated: [style-portfolio, layout-masonry, layout-editorial-columns, industry-photography]\nversion: 1\n---\n**Visitor**: a client or hiring manager scanning for fit in under a minute, then reading one case study deeply.\n\n**Home**: name and what you do in one line -> the work, immediately. Options: a project index list (title, client, year, discipline) with a preview image on hover; a large image grid; a single featured project per screen. Then a short about and contact.\n\n**Case study rhythm**: title and one line outcome -> role, team, year in a small meta row -> the problem in two or three sentences -> large images in alternating widths (full, two up, inset with caption) -> what changed, with real results only -> next project link.\n\n**Make it memorable through one move**, not ten: a custom cursor label on project hover, a typographic index, an oversized name in the footer, a colour per project. Pick one.\n\n**Do**: fast loading images (srcset, lazy below the fold), captions that explain decisions, contact as an email link that works.\n**Don't**: skill bars and percentage charts, logo walls of clients you did not work with, a \"services\" grid of icons, long intros before the work, scroll jacking.\n"
 },
 {
  "file": "entries/industry/industry-professional-services.md",
  "source": "---\nid: industry-professional-services\ntitle: Consultants, lawyers, accountants and therapists\ncategory: industry\nsummary: Calm, plain and specific: who it is for, how it works, what it costs, and one way to get in touch.\nintents: [build-site, plan-site, choose-style]\ntags: [consulting, consultant, law, lawyer, accounting, accountant, therapist, therapy, counselling, finance, advisor]\nindustries: [consulting, law, therapy]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: someone with a problem, often anxious, wanting to know whether this person can help and what it will cost.\n\n**Style**: Swiss or editorial, quiet. Seed: Plain Counsel.\n\n**Layout moves**: the questions people actually ask as headings with answers right below (an accordion for the long tail); the process as numbered steps; prices written plainly if the creator gave them; a portrait and a short honest bio; one contact or booking action repeated, never five.\n\n**Type**: IBM Plex Serif or Literata display, IBM Plex Sans or Atkinson Hyperlegible text.\n\n**Motion**: none; trust comes from clarity.\n\n**Imagery**: the real people, their room, documents. **Avoid**: handshakes, skyline stock, scales of justice icons, \"tailored solutions\", invented case results.\n"
 },
 {
  "file": "entries/industry/industry-publishing-books.md",
  "source": "---\nid: industry-publishing-books\ntitle: Books, publishing, magazines and newsletters\ncategory: industry\nsummary: Type does the work: a catalogue or an issue, columns and footnotes, very few images.\nintents: [build-site, plan-site, choose-style]\ntags: [books, publishing, publisher, magazine, newsletter, writer, author, zine, journal]\nindustries: [publishing, books, writer]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a reader looking for the next thing to read or subscribe to; patient if the text is good.\n\n**Style**: editorial and typography led; paper white, ink black, one red or blue. Seeds: Reading Room, Paper and Ink.\n\n**Layout moves**: an issue style index on home (numbered, with authors and lengths); a catalogue list of titles with format, pages and price from the store; long reads in a 60 to 70 character column with marginal notes; a subscribe form that says exactly what arrives and how often; an archive by year.\n\n**Type**: Literata or Source Serif 4 for both display and text, or Newsreader with a mono for metadata; drop caps and small caps used properly.\n\n**Motion**: none; reading is the experience.\n\n**Imagery**: covers shot flat, spreads, the author's own photo. **Avoid**: carousels of covers, \"Join 10,000 readers\" without the number, card grids of articles with identical excerpts.\n"
 },
 {
  "file": "entries/industry/industry-record-label.md",
  "source": "---\nid: industry-record-label\ntitle: Record labels, bands and releases\ncategory: industry\nsummary: Releases as a crate you flip through, catalogue numbers and tracklists, loud type and real dates.\nintents: [build-site, plan-site, choose-style]\ntags: [record-label, label, band, vinyl, records, release, album, musician]\nindustries: [music, record-label]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a fan looking for the new release, tour dates or merch.\n\n**Style**: typography led and industrial, or dark cinematic for electronic labels. Seeds: Pressing Plant, Night Shift.\n\n**Layout moves**: a horizontal scroll crate of releases with catalogue numbers; a release page with tracklist in mono, formats and real prices; tour dates as a dense list (date, city, venue, ticket link only when supplied); an artist index with hover image reveal; a marquee of the newest release name.\n\n**Type**: Unbounded or League Gothic display, Work Sans or Karla text, Space Mono for catalogue numbers.\n\n**Motion**: expressive but optional: marquee, sleeves sliding; off under reduced motion.\n\n**Imagery**: sleeves shot flat, live photos, the label's own art. **Avoid**: fake streaming counts, generic waveform graphics, invented press quotes.\n"
 },
 {
  "file": "entries/industry/industry-restaurant.md",
  "source": "---\nid: industry-restaurant\ntitle: Restaurants, cafes and food businesses\ncategory: industry\nsummary: Hours, location, menu and booking first, then atmosphere; menus as real text, not images.\nintents: [build-site, plan-site]\ntags: [restaurant, cafe, bar, bakery, food, menu, coffee, bistro, takeaway, chef]\nindustries: [restaurant, food, hospitality, cafe]\nphases: [concept, plan]\npriority: 4\nrelated: [restaurant, menu, venue, storelib-bookings]\nversion: 1\n---\n**Visitor**: usually on a phone, often nearby, asking \"is it open, where is it, what is on the menu, can I book\".\n\n**Home**: a photo that shows the room or the food honestly -> today's hours and address in the first screen -> book a table or order (whichever exists) -> menu highlights or the full menu link -> the story (the people, the sourcing) -> location with map link -> footer with hours again.\n\n**Menu**: real text, not a PDF or image (searchable, translatable, accessible). Sections, dish names, short descriptions, prices from what the creator gave, dietary markers explained once. Set it like a printed menu: dot leaders or right aligned prices, a narrow measure.\n\n**Visual**: food photos in natural light, close; the room at service. Palette from the place (tiles, wood, signage). Typefaces with character: a bistro serif, a hand painted sign style used once, a utilitarian grotesk for a canteen.\n\n**Don't**: autoplay video with sound, hours hidden in the footer only, stock food, feature cards (\"Fresh ingredients\", \"Great service\"), fake review stars.\n\n**Storelib**: table booking as a booking form with real slots; gift cards and merch as products; events (wine nights) as events or products with dates.\n"
 },
 {
  "file": "entries/industry/industry-saas.md",
  "source": "---\nid: industry-saas\ntitle: Software products and apps\ncategory: industry\nsummary: Product sites that show the actual product, explain one job clearly and price honestly, avoiding the identical SaaS template.\nintents: [build-site, plan-site, pricing]\ntags: [saas, software, app, tool, startup, platform, product]\nindustries: [saas, software, app]\nphases: [concept, plan]\npriority: 3\nrelated: [saas, style-saas, anti-slop-identical-saas, component-pricing]\nversion: 1\n---\n**The trap**: centred badge, gradient headline, two buttons, a floating dashboard screenshot with glow, logo strip, three feature cards with icons, testimonial carousel, three tier pricing. Every model writes this. Do not.\n\n**Instead**\n- Lead with the job: \"Invoices that chase themselves\" plus a screenshot or short loop of the real product doing that job, at a readable size.\n- Explain with the product: annotated screenshots, a step through of one workflow, a before and after of the task. Real UI beats illustrations.\n- Features as a list grouped by job, with small screenshots, not 9 icon tiles.\n- Pricing from what is actually sold. If there is one plan, show one plan with what it includes.\n- Proof: real customer names with permission, real numbers from the creator.\n\n**Visual directions**: a documentation feel (mono details, precise grid, light theme); a tool for creatives (bold type, colour from the product UI); a calm utility (plenty of white, a single strong accent from the logo). Dark with neon is allowed when the product is genuinely a dark UI and the concept says so.\n\n**Storelib**: subscriptions are products with recurring prices; trials only if the product has one. A waitlist is a form, not a fake signup count.\n"
 },
 {
  "file": "entries/industry/industry-tattoo-barber.md",
  "source": "---\nid: industry-tattoo-barber\ntitle: Tattoo studios and barbers\ncategory: industry\nsummary: Flash sheets and healed work in dense grids, artists with their own pages and a booking that explains deposits.\nintents: [build-site, plan-site, choose-style]\ntags: [tattoo, barber, barbershop, piercing, studio]\nindustries: [tattoo, barber]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: wants to see the work, pick an artist and book, and know about deposits and aftercare.\n\n**Style**: dark with tall condensed type, or bright and graphic for a modern barber. Seed: Ink and Needle.\n\n**Layout moves**: a dense flash grid you can open one at a time; an artist index with hover image reveal; healed work shown honestly; booking as a plain form with deposit and cancellation written out; aftercare as an accordion.\n\n**Type**: League Gothic or Anton display with Karla text, Space Mono for prices and times.\n\n**Motion**: subtle; type can be loud, motion should not be.\n\n**Imagery**: real work on skin, the tools, the room. **Avoid**: skull clip art, generic razor icons, invented review counts.\n"
 },
 {
  "file": "entries/industry/industry-wedding-photography.md",
  "source": "---\nid: industry-wedding-photography\ntitle: Wedding and portrait photographers\ncategory: industry\nsummary: Stories as image sequences with one line each, packages in a table and availability by month.\nintents: [build-site, plan-site, choose-style]\ntags: [wedding, photographer, portrait, elopement, family-photos]\nindustries: [wedding, photography]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a couple deciding in a few minutes whether the photographer feels right, then checking dates and packages.\n\n**Style**: light editorial with portfolio pacing. Seed: Wedding Light.\n\n**Layout moves**: stories as sequences of frames in varied widths, each with one line; a packages table from real prices; availability by month if the creator supplies it; an enquiry form that asks for date and place; a short personal note in the photographer's voice.\n\n**Type**: Italiana or Instrument Serif display with Jost or Instrument Sans text.\n\n**Motion**: subtle: images reveal as they enter, nothing bounces.\n\n**Imagery**: candid, backlit, film colour. **Avoid**: watermark heavy galleries, invented magazine features, star ratings.\n"
 },
 {
  "file": "entries/industry/industry-wellness.md",
  "source": "---\nid: industry-wellness\ntitle: Wellness, yoga, therapy and holistic practice sites\ncategory: industry\nsummary: Calm without being beige mush; how to show practice, practitioner, schedule and booking honestly for yoga, massage, therapy and holistic health.\nintents: [build-site, plan-site, choose-style]\ntags: [wellness, yoga, pilates, meditation, massage, therapy, holistic, spa, breathwork, retreat]\nindustries: [wellness, yoga, spa, therapy]\nphases: [concept, plan]\npriority: 4\nrelated: [soft_care, organic_grove, style-organic, storelib-bookings]\nversion: 1\n---\n**Visitor**: wants to feel safe before booking. Trust comes from the practitioner, clear practicalities and a tone that does not oversell.\n\n**Structure**: hero with the practice and place (or online) -> what a session is like, in plain steps -> the practitioner -> offerings with duration and price from the store -> timetable or booking -> what to bring, accessibility, cancellation -> location and contact.\n\n**Visual**: avoid the default sage green plus beige plus script font. Options: a mineral palette (stone, slate, chalk) with a geometric sans; a warm terracotta and ink palette with a book serif; a deep forest night palette for evening classes and sound baths. Photography of real rooms, hands and light; never stock lotus poses.\n\n**Motion**: subtle. Slow fades (400 to 600ms), no bouncing, nothing that loops in the reading area. Breath based pacing is a cliché unless the brand is breathwork.\n\n**Copy**: no medical claims, no \"heal\", \"detox\" or \"cure\" unless the creator's own regulated practice states it. Describe sensations and logistics: \"75 minutes, mats provided, slow flow for beginners\".\n\n**Storelib**: classes and sessions are bookings with real slots; packs of classes are products; retreats are products or events with real dates. Never show available spots unless the booking data supplies them.\n"
 },
 {
  "file": "entries/industry/industry-wine-drinks.md",
  "source": "---\nid: industry-wine-drinks\ntitle: Wine, spirits, tea and drinks\ncategory: industry\nsummary: Bottles and terroir with specification cards; dark and patient or bright and graphic, never generic luxury.\nintents: [build-site, plan-site, choose-style]\ntags: [wine, winery, spirits, distillery, tea, brewery, beer, drinks, vineyard]\nindustries: [wine, drinks]\nphases: [concept, plan]\npriority: 4\nrelated: [core-visual-concept-first, typography-type-library]\nversion: 1\n---\n**Visitor**: a buyer or a fan who wants to know what is in the bottle and where it comes from.\n\n**Style**: luxury editorial, or a graphic label led look for natural wine and craft beer. Seed: Cellar Notes.\n\n**Layout moves**: each bottle as a tall panel with vintage, grape, soil, alcohol and size in a spec list; a map or a year by year vintage list; tasting events only with real dates; age confirmation only where the store needs it.\n\n**Type**: Gloock or Young Serif display with Spectral text; or Unbounded caps for a craft brewery.\n\n**Motion**: subtle: label close ups that settle; nothing that sloshes.\n\n**Imagery**: vineyards at dusk, cellar stone, hands and labels close. **Avoid**: gold gradients, invented medals and scores, \"award winning\" without the award.\n"
 },
 {
  "file": "entries/layout/layout-asymmetric-grid.md",
  "source": "---\nid: layout-asymmetric-grid\ntitle: Asymmetric grids\ncategory: layout\nsummary: Placing content off centre on a 12 column grid with deliberate empty columns, offsets and overlaps; specs and phone fallbacks.\nintents: [build-section, layout, choose-style]\ntags: [asymmetric, grid, 12-column, offset, off-centre, composition]\ncomponents: [grid]\nphases: [plan, build]\npriority: 4\nrelated: [style-swiss, style-editorial, layout-editorial-columns]\nversion: 1\n---\nAsymmetry gives tension and direction. It needs a grid to look deliberate rather than broken.\n\n**Grid**: 12 columns, gutters 16px (phone) to 24 to 32px (desktop), outer margins 16 to 20px on phones and at least 1 column on desktop.\n\n**Moves**\n- Text in columns 2 to 7, image in 8 to 12 starting lower (offset by 80 to 160px).\n- A heading that starts in column 1 and a paragraph that starts in column 5 below it.\n- An image that spans columns 1 to 8, with a caption in columns 10 to 12 aligned to its bottom.\n- Overlap: an image in 5 to 12 and a text box in 1 to 6 on the same row, the text box layered above with a solid background.\n\n```css\n.grid { display: grid; grid-template-columns: repeat(12, 1fr); column-gap: clamp(16px, 2.5vw, 32px); }\n.a { grid-column: 2 / span 6; }\n.b { grid-column: 8 / span 5; margin-top: clamp(40px, 8vw, 140px); }\n@media (max-width: 760px) { .a, .b { grid-column: 1 / -1; margin-top: 0; } }\n```\n\nOn phones, asymmetry comes from alignment and indentation (a caption indented by 25%), not from columns.\n"
 },
 {
  "file": "entries/layout/layout-bento.md",
  "source": "---\nid: layout-bento\ntitle: Bento grids (use sparingly)\ncategory: layout\nsummary: Mixed size tiles in one grid; when they help (a few genuinely different items) and when they are the generic AI default.\nintents: [build-section, layout]\ntags: [bento, tiles, grid, mosaic, feature-grid]\ncomponents: [grid, cards]\nphases: [plan, build, review]\npriority: 2\nrelated: [anti-slop-floating-cards, anti-slop-identical-saas]\nversion: 1\n---\n**Stance**: bento grids are one of the most overused machine layouts (especially for feature lists). Use one only when the items are genuinely different in kind and importance, and each tile has real content (a photo, a real product, a real quote).\n\n**Good uses**: a creator's home showing their latest video, a product, a community and a newsletter at different sizes; a portfolio overview with one hero project and several smaller ones.\n\n**Specs**: a 4 or 6 column grid with `grid-auto-rows` (e.g. 180 to 240px); 2 to 3 tile sizes; gaps 8 to 16px; one radius; no more than 6 to 8 tiles.\n\n```css\n.bento { display: grid; grid-template-columns: repeat(4, 1fr); grid-auto-rows: 200px; gap: 12px; }\n.bento .lg { grid-column: span 2; grid-row: span 2; }\n@media (max-width: 700px) { .bento { grid-template-columns: 1fr 1fr; grid-auto-rows: 160px; } }\n```\n\n**Don't**: fill tiles with icon plus heading plus line of text (\"Fast\", \"Secure\", \"Scalable\"). That is a feature list in disguise; use a plain list.\n"
 },
 {
  "file": "entries/layout/layout-editorial-columns.md",
  "source": "---\nid: layout-editorial-columns\ntitle: Editorial columns and long reads\ncategory: layout\nsummary: Magazine style text layouts: a reading column, side notes, pull quotes, inset and breakout images, and multi column text where it helps.\nintents: [build-section, layout, blog]\ntags: [editorial, columns, long-read, article, pull-quote, sidenotes, breakout]\ncomponents: [article, typography]\nphases: [build]\npriority: 3\nrelated: [style-editorial, typography-tracking-measure]\nversion: 1\n---\n**The named grid pattern** gives a reading column with breakout options:\n\n```css\n.article { display: grid; grid-template-columns: [full-start] minmax(16px, 1fr) [wide-start] minmax(0, 120px) [text-start] min(65ch, 100% - 32px) [text-end] minmax(0, 120px) [wide-end] minmax(16px, 1fr) [full-end]; }\n.article > * { grid-column: text; }\n.article > .wide { grid-column: wide; }\n.article > .full { grid-column: full; }\n```\n\n**Pull quotes**: set at 1.5 to 2x body, in italic or the display face, pulled into the margin on desktop; only real sentences from the text, never invented quotes.\n\n**Side notes**: on desktop, float notes into the right margin (`float: right; margin-right: -14rem; width: 12rem;`); on phones, render inline in a muted box.\n\n**Multi column text** (`columns: 2`) only for short, self contained text like an introduction or a menu; never for long text people must scroll up and down to read.\n\nBlog posts in Storelib come from the blog (`article.content`); style the content with element selectors scoped to the section.\n"
 },
 {
  "file": "entries/layout/layout-floating.md",
  "source": "---\nid: layout-floating\ntitle: Floating elements\ncategory: layout\nsummary: Floating badges, notes, stickers and media over content: where they add meaning, limits, and why most floating cards are slop.\nintents: [build-section, layout, review]\ntags: [floating, sticker, overlay, badge, absolute, floating-card]\ncomponents: [badge, card]\nphases: [build, review]\npriority: 2\nrelated: [anti-slop-floating-cards, layout-layered]\nversion: 1\n---\n**Earn it**: a floating element should carry real information tied to what it floats over: a sticker with the real price on a product photo, a caption pinned to a location on a map, a play button on a video, a \"New\" label from product data.\n\n**Limits**: one or two per viewport; never over faces or the main subject; never covering text.\n\n**Slop version**: hero screenshots surrounded by little cards (\"+45% conversions\", \"New sale!\", a fake notification), cards floating with a bobbing animation. The evaluator flags it unless the concept explains it.\n\n**Specs if used**: anchor to a corner of the parent with `position: absolute`, offset 12 to 24px, a solid background with contrast, a small shadow at most, no infinite float animation (if any motion, one entrance).\n\n**Phones**: floating items often collide; move them inline under the media on small screens.\n"
 },
 {
  "file": "entries/layout/layout-full-bleed.md",
  "source": "---\nid: layout-full-bleed\ntitle: Full bleed sections\ncategory: layout\nsummary: Edge to edge images and bands: when to use them, safe text placement, height rules with svh, and the content grid inside.\nintents: [design-hero, build-section, layout]\ntags: [full-bleed, edge-to-edge, full-width, hero, banner, immersive]\ncomponents: [hero, banner, image]\nphases: [plan, build]\npriority: 4\nrelated: [hero_immersive, layout-split]\nversion: 1\n---\n**Use for**: an opening image that is the experience (venues, fashion campaigns, landscapes), a rhythm break between dense sections, a closing call to action.\n\n**Height**: avoid `100vh` on phones (browser bars change it). Use `min-height: 100svh` for a full first screen, or 70 to 85svh to hint there is more below. Never fixed pixel heights that crop on tall phones.\n\n**Text on images**: place text where the image is calm (art direction), add a gradient scrim only behind the text area, and keep it inside the content grid so it aligns with the rest of the page.\n\n```css\n.bleed { position: relative; min-height: 85svh; display: grid; align-items: end; }\n.bleed img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.bleed .inner { position: relative; padding: clamp(24px, 5vw, 64px); max-width: 1200px; margin-inline: auto; width: 100%; }\n.bleed::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,.55), transparent 55%); }\n.bleed .inner { z-index: 1; }\n```\n\n**Art direction**: provide a different crop for phones with `<picture>` when the subject would be lost in a portrait crop. Use `object-position` to keep faces in frame.\n"
 },
 {
  "file": "entries/layout/layout-horizontal-scroll.md",
  "source": "---\nid: layout-horizontal-scroll\ntitle: Horizontal scroll rows\ncategory: layout\nsummary: Native horizontally scrolling rows with scroll snap for products, looks and testimonials; affordances, keyboard and no scroll jacking.\nintents: [build-section, layout, carousel]\ntags: [horizontal-scroll, scroll-snap, rail, slider, swipe, overflow]\ncomponents: [carousel, product-grid]\nphases: [build]\npriority: 3\nrelated: [component-carousel, responsive-mobile-first]\nversion: 1\n---\nPrefer a native scroll row over a JS carousel: it is accessible, works with touch and trackpads, and needs no library.\n\n```css\n.rail { display: grid; grid-auto-flow: column; grid-auto-columns: min(78%, 320px); gap: 16px; overflow-x: auto; scroll-snap-type: x mandatory; padding-inline: 16px; scroll-padding-inline: 16px; overscroll-behavior-x: contain; }\n.rail > * { scroll-snap-align: start; }\n.rail:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }\n@media (min-width: 1000px) { .rail { grid-auto-columns: calc((100% - 48px) / 4); } }\n```\n\n**Affordance**: show part of the next item (the 78% width above) so people know it scrolls. Optional previous and next buttons that call `scrollBy({ left: rail.clientWidth * .9, behavior: 'smooth' })` (instant under reduced motion).\n\n**Accessibility**: give the rail `tabindex=\"0\"`, `role=\"region\"` and an `aria-label` so keyboard users can scroll it; items stay in normal tab order.\n\n**Avoid**: vertical scroll converted into horizontal movement (scroll jacking) unless the concept is experimental and a normal fallback exists; hiding the scrollbar on desktop with no buttons.\n\n**Don't confuse**: the page itself must never scroll sideways; only the rail does.\n"
 },
 {
  "file": "entries/layout/layout-layered.md",
  "source": "---\nid: layout-layered\ntitle: Layered and overlapping compositions\ncategory: layout\nsummary: Overlapping images and text with z-order, negative margins and grid overlap, while keeping reading order and contrast safe.\nintents: [build-section, layout]\ntags: [layered, overlap, depth, collage, z-index, composition]\ncomponents: [image, hero]\nphases: [build]\npriority: 3\nrelated: [layout-asymmetric-grid, layout-floating]\nversion: 1\n---\n**Grid overlap** is more robust than absolute positioning: put two items in overlapping grid areas.\n\n```css\n.layer { display: grid; grid-template-columns: repeat(12, 1fr); }\n.layer .photo { grid-column: 4 / -1; grid-row: 1; }\n.layer .text { grid-column: 1 / 8; grid-row: 1; align-self: end; z-index: 1; background: var(--surface); padding: clamp(20px, 3vw, 40px); margin-bottom: -48px; }\n@media (max-width: 760px) { .layer .photo, .layer .text { grid-column: 1 / -1; } .layer .text { grid-row: 2; margin: -32px 16px 0; } }\n```\n\n**Rules**: text that overlaps an image needs a solid or near solid backing; DOM order follows reading order (heading before decorative image); overlaps are limited to one or two per page so they stay special.\n\n**Collage**: three or four images at different sizes with slight overlaps can tell a story (a studio, a trip). Fix their positions on a grid; do not randomise with JS.\n\n**Avoid**: overlapping interactive elements (links under images cannot be clicked), overlaps that collide at intermediate widths. Check 375, 768, 1024 and 1440.\n"
 },
 {
  "file": "entries/layout/layout-masonry.md",
  "source": "---\nid: layout-masonry\ntitle: Masonry and justified galleries\ncategory: layout\nsummary: Showing mixed aspect images without cropping, with CSS columns or a justified row layout, and reading order caveats.\nintents: [gallery, build-section, layout]\ntags: [masonry, pinterest, gallery, justified, mixed-ratio, columns]\ncomponents: [gallery, image]\nphases: [build]\npriority: 3\nrelated: [component-gallery, industry-photography]\nversion: 1\n---\n**CSS columns** (simplest, no JS): items flow top to bottom per column, which means reading order goes down columns, not across rows. Fine for photos, wrong for ordered content like a timeline.\n\n```css\n.masonry { columns: 3 280px; column-gap: 16px; }\n.masonry > * { break-inside: avoid; margin-bottom: 16px; }\n.masonry img { width: 100%; height: auto; display: block; }\n```\n\n**Justified rows** (row order preserved, nothing cropped): use flex with grow factors equal to each image's aspect ratio.\n\n```css\n.justified { display: flex; flex-wrap: wrap; gap: 8px; }\n.justified figure { flex-grow: calc(var(--w) / var(--h)); flex-basis: calc(220px * var(--w) / var(--h)); margin: 0; }\n.justified img { width: 100%; height: auto; display: block; }\n```\nSet `--w` and `--h` from the image's real dimensions (and use width and height attributes to avoid layout shift).\n\n**Phones**: two columns for small images, one for portfolios. Lazy load below the first screen.\n"
 },
 {
  "file": "entries/layout/layout-spacing-rhythm.md",
  "source": "---\nid: layout-spacing-rhythm\ntitle: Spacing scales and vertical rhythm\ncategory: layout\nsummary: A spacing scale, section padding by breakpoint, grouping by proximity, and avoiding both cramped and empty layouts.\nintents: [build-section, layout, review, fix-spacing]\ntags: [spacing, rhythm, padding, margin, whitespace, scale, gaps]\ncomponents: [section]\nphases: [plan, build, review]\npriority: 5\nrelated: [anti-slop-unbalanced-spacing, responsive-breakpoints]\nversion: 1\n---\n**Scale**: 4, 8, 12, 16, 24, 32, 48, 64, 96, 128. Use only these. Arbitrary values (13px, 37px, 22px) accumulate into visual noise; the evaluator counts them.\n\n**Section padding**: phones 48 to 72px top and bottom, desktop 80 to 160px. Use a fluid value: `padding-block: clamp(48px, 8vw, 128px)`. Keep it consistent; vary it deliberately (a tight band, a spacious hero) rather than randomly.\n\n**Proximity**: related items are closer than unrelated ones. Label to heading 8 to 12px, heading to body 12 to 24px, body to button 24 to 32px, between groups 48px or more.\n\n**Containers**: one main content width (1100 to 1280px) and one text width (60 to 70ch). Not five.\n\n**Check**: squint. Groups should read as groups. If two sections blur together, increase the gap or change the background; if the page feels empty, the content is probably too small, not the gaps too big.\n"
 },
 {
  "file": "entries/layout/layout-split.md",
  "source": "---\nid: layout-split\ntitle: Split layouts\ncategory: layout\nsummary: Two column compositions (text and image, image and image) with ratios beyond 50/50, stacking order on phones and sticky sides.\nintents: [build-section, layout, design-hero]\ntags: [split, two-column, side-by-side, image-text, 50-50]\ncomponents: [hero, image-with-text]\nphases: [plan, build]\npriority: 4\nrelated: [hero_split, image_with_text, layout-sticky-storytelling]\nversion: 1\n---\n**Ratios**: 50/50 is the default and the least interesting. Try 7/5 or 8/4 on a 12 column grid; let the image take the larger share for visual brands, the text for explanatory ones.\n\n**Alignment**: vertically centre short text against a tall image; top align long text. A split where text floats in the middle of a huge empty half looks unfinished; let the image dominate or add real content.\n\n**Stacking on phones**: decide the order on purpose. Usually image first for products and portfolios, text first for services where the promise matters. Use `order` only when the DOM order is already the reading order for screen readers; better to write the DOM in the phone order.\n\n**Breaking the box**: let the image bleed to the viewport edge on its side while the text stays on the grid:\n\n```css\n.split { display: grid; grid-template-columns: 1fr; gap: 32px; }\n@media (min-width: 900px) { .split { grid-template-columns: 7fr 5fr; gap: 64px; align-items: center; } }\n```\n\n**Alternating splits** down a page (image left, then right) are fine twice; four in a row becomes a template. Change the rhythm with a full width section between.\n"
 },
 {
  "file": "entries/layout/layout-sticky-storytelling.md",
  "source": "---\nid: layout-sticky-storytelling\ntitle: Sticky storytelling\ncategory: layout\nsummary: A pinned visual with steps scrolling beside it, built with position sticky (no scroll hijacking), and what to show on phones.\nintents: [build-section, layout, motion]\ntags: [sticky, scrollytelling, pinned, steps, process, story]\ncomponents: [process, steps]\nphases: [build]\npriority: 3\nrelated: [motion-sticky, layout-split, process]\nversion: 2\n---\n**Pattern**: a tall section; one side holds a sticky media panel, the other side has steps that scroll normally. As each step enters, the media changes.\n\n```css\n.story { display: grid; grid-template-columns: 1fr; gap: 32px; }\n@media (min-width: 900px) {\n  .story { grid-template-columns: 1fr 1fr; }\n  .story .media { position: sticky; top: calc(var(--header-h, 72px) + 24px); height: calc(100svh - var(--header-h, 72px) - 48px); }\n  .story .step { min-height: 70svh; display: flex; align-items: center; }\n}\n```\n\n**Switching media**: in a Storelib section there is no IntersectionObserver (the script runs in a sandbox on a copy of the markup). Put each step's image inside its step and make the media column sticky per step, or crossfade images with a view timeline on each step (`animation-timeline: view()`); without support, every image simply shows beside its step.\n\n**Phones**: drop the sticky panel. Put each step's image directly above its text. Sticky panels on small screens cover the content.\n\n**Rules**: no scroll hijacking or snapping that fights the user; each step has its own heading; reduced motion swaps media instantly.\n\n**Watch out**: `position: sticky` fails inside an ancestor with `overflow: hidden`; use `overflow: clip` on the ancestor instead if you need clipping.\n"
 },
 {
  "file": "entries/motion/motion-fades-slides.md",
  "source": "---\nid: motion-fades-slides\ntitle: Fades and slides on entry\ncategory: motion\nsummary: Entrance animations on scroll: distances, durations, CSS view timelines (a section script cannot observe the page), and keeping content visible without them.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, fade, slide, entrance, reveal, scroll-reveal, fade-up]\ncomponents: [motion]\nphases: [build, review]\npriority: 4\nrelated: [motion-principles, motion-stagger]\nversion: 2\n---\n**Spec**: opacity 0 to 1 plus translateY 12 to 24px; 400 to 600ms ease out; trigger when 15 to 20% of the element is visible; once only.\n\n**Visible without JS**: hide only after the script marks the page ready.\n\n```css\n@media (prefers-reduced-motion: no-preference) {\n  .js-motion [data-reveal] { opacity: 0; transform: translateY(16px); transition: opacity .5s cubic-bezier(.2,.7,.2,1), transform .5s cubic-bezier(.2,.7,.2,1); }\n  .js-motion [data-reveal].in { opacity: 1; transform: none; }\n}\n```\nIn a Storelib section use the CSS view timeline instead of a script: the script runs in a sandbox on a copy of the markup and an IntersectionObserver there never fires for the real page (motion-in-storelib-runtime, example ai_scroll_reveal):\n```css\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    [data-reveal] { animation: rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }\n    @keyframes rise { from { opacity: 0; transform: translateY(16px); } }\n  }\n}\n```\n\n**Restraint**: reveal section headings and media, not every paragraph. Slides from the side (translateX) only where direction means something (next step, incoming panel).\n"
 },
 {
  "file": "entries/motion/motion-hover.md",
  "source": "---\nid: motion-hover\ntitle: Hover effects\ncategory: motion\nsummary: Hover feedback for links, buttons, cards and images; guarded for hover devices, matched by focus, and quick.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, hover, pointer, interaction, link-hover, card-hover]\ncomponents: [motion]\nphases: [build, review]\npriority: 4\nrelated: [state-interactive-matrix, motion-micro-interactions]\nversion: 1\n---\n**Speed**: 120 to 200ms in, slightly faster out.\n\n**Guard**: `@media (hover: hover) and (pointer: fine)` so touch devices do not get sticky hover states.\n\n**Patterns**\n- Links: underline offset or thickness change; an underline that grows from left (`background-size` transition on a linear gradient underline).\n- Buttons: background shift 8 to 12%; neo brutal press; arrow nudges 2 to 4px.\n- Cards: image scale 1.03 inside a clip; title underline; no lifting cards with growing shadows everywhere.\n- Images: swap to a second image (products), or caption reveal.\n\n**Focus parity**: apply the same visible change on `:focus-visible`.\n\n**Never** hide essential actions behind hover (quick add must be reachable on touch and keyboard).\n"
 },
 {
  "file": "entries/motion/motion-image-transforms.md",
  "source": "---\nid: motion-image-transforms\ntitle: Image transforms and reveals\ncategory: motion\nsummary: Revealing and moving images: clip path wipes, mask reveals, slow scale, colour to full, and their costs.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, image, reveal, clip-path, mask, ken-burns, zoom]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-scroll, style-dark-cinematic]\nversion: 1\n---\n**Clip path wipe**: from `inset(100% 0 0 0)` to `inset(0)` over 700 to 900ms ease out. Elegant for editorial and luxury.\n\n**Slow scale**: image starts at scale 1.08 and settles to 1 over 1.2 to 1.6s on load or entry. Gives life to static photos without a carousel.\n\n**Colour to full**: greyscale to colour on hover for gallery grids (concept dependent; it can feel dated).\n\n**Costs**: animating `filter` and large clip paths repaints; keep to one or two images in view at a time; use `will-change: transform` only during the animation.\n\n**Reduced motion**: images simply appear. Never hide an image permanently behind an animation that might not run.\n"
 },
 {
  "file": "entries/motion/motion-in-storelib-runtime.md",
  "source": "---\nid: motion-in-storelib-runtime\ntitle: Motion and interaction inside Storelib's runtime\ncategory: motion\nsummary: What a section's script can and cannot do in the sandbox, and the CSS techniques to use instead: scroll-driven animation, :has(), details, popover, sticky, view transitions; reduced motion always.\nintents: [add-motion, add-interaction, build-section, fix-script]\ntags: [motion, sandbox, script, scroll-driven, animation-timeline, view-timeline, has, popover, details, view-transition, intersectionobserver, reduced-motion]\ncomponents: [motion]\nphases: [plan, build, repair]\npriority: 5\nrelated: [component-interactive-library, motion-scroll, motion-principles, debug-section-scripts]\nversion: 1\n---\n**The script's world**: a section's script runs in a sandboxed frame against a copy of its own markup. It can listen to clicks, input, change, keys, focus and toggle; it can change classes, attributes (aria-*, data-*, hidden, open, popover, inert, tabindex) and inline styles including custom properties; it can ask the page to scroll an element (storelib.scrollTo) or go to another section. It cannot read layout or scroll position, observe intersections, focus an element, play or pause a video, add markup, or use window, document, fetch, storage or timers (timers only with the timers capability).\n\n**So reach for CSS first**:\n- Reveals, parallax, progress bars, counters: `animation-timeline: view()` or a named `scroll-timeline`, inside `@supports (animation-timeline: view())` and `@media (prefers-reduced-motion: no-preference)`, with the final state as the default so nothing is hidden without support.\n- Tabs, filters, swatches: a radio group plus `:has(:checked)`; arrow keys work for free.\n- Accordions: `<details name=\"group\">` for one open at a time; `::details-content` with `interpolate-size: allow-keywords` for a height transition.\n- Menus, mega menus, dialogs: the popover attribute with `popovertarget` buttons; Escape and outside clicks close it, focus is handled by the browser.\n- Sticky storytelling and stacked panels: `position: sticky` with a top that grows per item.\n- Page to page: `@view-transition { navigation: auto; }` gives a cross document fade where supported; name one element with view-transition-name for a shared image.\n- Hover reveals: `@media (hover: hover) and (pointer: fine)` so touch gets a plain layout.\n\n**Use a script for state only**: a before and after split from a range input, a quantity stepper's label, a selected swatch's name. Keep it a few lines and make the markup work without it.\n\n**Always**: prefers-reduced-motion turns movement off; motion lasts 150 to 400ms for UI and never loops more than once per page outside a marquee; nothing essential depends on motion.\n"
 },
 {
  "file": "entries/motion/motion-loading.md",
  "source": "---\nid: motion-loading\ntitle: Loading motion\ncategory: motion\nsummary: Motion for waiting: spinners, shimmer, progress, and why full page preloaders hurt.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, loading, spinner, skeleton, progress, preloader]\ncomponents: [motion]\nphases: [build, review]\npriority: 2\nrelated: [component-loading, state-async]\nversion: 1\n---\n**Spinner**: 16 to 24px inside the busy control, rotating at about 0.8 to 1s per turn, `aria-hidden` with a text status beside it for assistive tech.\n\n**Shimmer**: low contrast sweep 1.2 to 1.6s, stopped under reduced motion.\n\n**Progress**: determinate when you know the progress (uploads, multi step jobs), with a percentage or step text.\n\n**Preloaders**: avoid full screen intros that hold content back. If the concept insists on an intro, keep it under 1.2s, skip on repeat visits (session storage), and never on reduced motion.\n"
 },
 {
  "file": "entries/motion/motion-marquee.md",
  "source": "---\nid: motion-marquee\ntitle: Marquees and tickers\ncategory: motion\nsummary: Infinite horizontal tickers for dates, words or real logos: seamless CSS loop, speed, pause control and reduced motion.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, marquee, ticker, scrolling-text, logo-strip, loop]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [industry-events-nightlife, marquee]\nversion: 1\n---\n**Content**: real information (dates, cities, class times, real client names) or a brand phrase. Not invented logos.\n\n**Seamless loop**: duplicate the content once (mark the copy `aria-hidden=\"true\"`) and translate the track by -50%.\n\n```css\n.marquee { overflow: clip; }\n.track { display: flex; width: max-content; gap: 48px; }\n@media (prefers-reduced-motion: no-preference) { .track { animation: run var(--speed, 30s) linear infinite; } }\n.marquee:hover .track, .marquee:focus-within .track { animation-play-state: paused; }\n@keyframes run { to { transform: translateX(-50%); } }\n```\n\n**Speed**: slow enough to read: about 40 to 80px per second. Set duration from content width.\n\n**Controls**: content that moves for more than 5 seconds needs a way to pause (WCAG 2.2.2). Hover and focus pause plus a pause button for long marquees.\n\n**Reduced motion**: static row, wrapping or scrollable.\n"
 },
 {
  "file": "entries/motion/motion-micro-interactions.md",
  "source": "---\nid: motion-micro-interactions\ntitle: Micro interactions\ncategory: motion\nsummary: Small feedback moments (add to cart, toggles, copy, like) that confirm actions quickly without becoming decoration.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, micro-interaction, feedback, toggle, like, add-to-cart, success]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-hover, state-interactive-matrix]\nversion: 1\n---\n**Good moments**: add to cart (button morphs to a check for 1.2s, cart count bumps), copying a code (label changes to \"Copied\"), toggling a switch (thumb slides 150ms), submitting a form (button to spinner to check).\n\n**Rules**: under 300ms for the core feedback; confirm with text as well as motion; announce via a status region when the result is not visible otherwise.\n\n```css\n.count[data-bump] { animation: bump .3s cubic-bezier(.34,1.56,.64,1); }\n@keyframes bump { 50% { transform: scale(1.25); } }\n@media (prefers-reduced-motion: reduce) { .count[data-bump] { animation: none; } }\n```\n\n**Avoid**: confetti for routine actions, sound effects, delays that make the user wait for the animation to finish before the next action.\n"
 },
 {
  "file": "entries/motion/motion-page-transitions.md",
  "source": "---\nid: motion-page-transitions\ntitle: Page transitions\ncategory: motion\nsummary: Transitions between pages with the View Transitions API, short durations and no blocking.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, page-transition, view-transitions, route, navigation]\ncomponents: [motion]\nphases: [build, review]\npriority: 2\nrelated: [motion-principles, header-fullscreen-menu]\nversion: 1\n---\n**Use the platform**: cross document view transitions (`@view-transition { navigation: auto; }`) give a fade between pages in supporting browsers with no JS; other browsers just navigate.\n\n```css\n@media (prefers-reduced-motion: no-preference) {\n  @view-transition { navigation: auto; }\n  ::view-transition-old(root), ::view-transition-new(root) { animation-duration: .25s; }\n}\n```\n\n**Shared elements**: give a product image and the product page hero the same `view-transition-name` for a morph. Names must be unique per page.\n\n**Rules**: under 300 to 400ms; never delay navigation waiting for an exit animation; no full screen wipes on every click unless the concept is experimental and fast.\n"
 },
 {
  "file": "entries/motion/motion-parallax.md",
  "source": "---\nid: motion-parallax\ntitle: Parallax\ncategory: motion\nsummary: Subtle depth on scroll: small offsets, transform only, CSS first, and disabled on reduced motion and low power.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, parallax, depth, scroll-depth, layers]\ncomponents: [motion]\nphases: [build, review]\npriority: 2\nrelated: [motion-scroll, motion-principles]\nversion: 1\n---\n**Subtle**: background images move 10 to 20% slower than the page; foreground decorations at most 40 to 80px offset over the section. Strong parallax causes motion sickness.\n\n**Implementation**: CSS scroll timelines where supported; otherwise a single rAF loop applying `translate3d` to a few elements. Never `background-attachment: fixed` (broken on iOS, costly).\n\n```css\n@supports (animation-timeline: view()) { @media (prefers-reduced-motion: no-preference) {\n  .para { animation: drift linear both; animation-timeline: view(); }\n  @keyframes drift { from { transform: translateY(-40px); } to { transform: translateY(40px); } }\n} }\n```\n\n**Limit** to one parallax element per section; disable on small screens if it causes jank.\n"
 },
 {
  "file": "entries/motion/motion-performance.md",
  "source": "---\nid: motion-performance\ntitle: Animation performance\ncategory: motion\nsummary: Keeping motion at 60fps on mid range phones: compositor friendly properties, layer limits, measuring, and what to cut first.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, performance, jank, fps, will-change, compositing, cls]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-principles, debug-layout-shift]\nversion: 2\n---\n- **Compositor only**: `transform`, `opacity` (and `filter` sparingly). Anything that changes layout (`width`, `margin`, `top`) or paint (`box-shadow`, `background-position` on large areas) costs per frame.\n- **will-change**: add right before an animation and remove after; permanent `will-change` on many elements wastes memory.\n- **Layers**: a handful of animated layers in view, not dozens.\n- **Blur and backdrop filters** are the most expensive; never animate their radius.\n- **Scroll handlers**: passive listeners, no layout reads in them; prefer scroll timelines (in a Storelib section the only option: its script cannot observe the page).\n- **Offscreen**: keep loops few and short; give videos native controls so a visitor can pause them (a section script cannot pause a video on the page).\n- **Measure**: Chrome performance panel with 4x CPU throttle; aim for no long tasks over 50ms during scroll.\n- **Cut order** when slow: parallax, then blur, then large clip paths, then staggered reveals.\n"
 },
 {
  "file": "entries/motion/motion-principles.md",
  "source": "---\nid: motion-principles\ntitle: Motion principles, reduced motion and performance\ncategory: motion\nsummary: The rules every animation follows: purpose, durations, easing, transform and opacity only, prefers-reduced-motion, and budgets.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, principles, reduced-motion, performance, easing, duration]\ncomponents: [motion]\nphases: [build, review]\npriority: 5\nrelated: [motion-performance, a11y-checklist]\nversion: 1\n---\n**Purpose**: motion explains (where something came from), confirms (a press), guides attention once, or sets mood at the concept's chosen stance. If it does none, remove it.\n\n**Durations**: micro interactions 100 to 200ms; small entrances 200 to 400ms; large reveals 500 to 900ms; never over about 1.2s for anything blocking content.\n\n**Easing**: enter with ease out (`cubic-bezier(.2,.7,.2,1)`), exit with ease in, moves with ease in out. Springs (overshoot) only for playful concepts and small elements.\n\n**Properties**: animate `transform` and `opacity`. Avoid animating `width`, `height`, `top`, `left`, `box-shadow`, `filter: blur` in loops.\n\n**Reduced motion is mandatory**:\n```css\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }\n}\n```\nBetter: write motion inside `@media (prefers-reduced-motion: no-preference)` so the default is still. Content must be fully visible without animation (never start at opacity 0 without a fallback).\n\n**Budget**: at most one looping animation in view at a time; nothing that moves while people read body text.\n"
 },
 {
  "file": "entries/motion/motion-scale.md",
  "source": "---\nid: motion-scale\ntitle: Scale animations\ncategory: motion\nsummary: Scaling on entry, hover and press: safe ranges, transform origin, avoiding blurry text and layout overlap.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, scale, zoom, grow, pop]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-hover, motion-image-transforms]\nversion: 1\n---\n**Ranges**: entrance from 0.96 to 1 (subtle) or 0.9 to 1 (expressive); hover 1.02 to 1.05 for cards and images; press 0.97 to 0.98.\n\n**Origin**: set `transform-origin` to where the element comes from (a menu from its button, a dialog from centre).\n\n**Text**: scaling text containers can blur glyphs mid animation; keep scale animations short on text or scale only the media.\n\n**Overflow**: images that scale on hover sit inside a clipping wrapper (`overflow: clip`) so they do not overlap neighbours.\n\n**Avoid**: scaling from 0 (feels like a pop up ad), bouncing scale on every element, scaling large sections (causes repaint of huge layers).\n"
 },
 {
  "file": "entries/motion/motion-scroll.md",
  "source": "---\nid: motion-scroll\ntitle: Scroll driven animation\ncategory: motion\nsummary: Animations tied to scroll position: CSS scroll and view timelines with fallbacks, limits, and never hijacking scroll.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, scroll, scroll-driven, scroll-timeline, progress, view-timeline]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-parallax, motion-sticky, layout-sticky-storytelling, motion-in-storelib-runtime]\nversion: 2\n---\n**Native first**: CSS `animation-timeline: view()` or `scroll()` runs off the main thread where supported. Wrap in `@supports` and give a static fallback.\n\n```css\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .img-reveal { animation: reveal linear both; animation-timeline: view(); animation-range: entry 0% cover 40%; }\n    @keyframes reveal { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }\n  }\n}\n```\n\n**No JS fallback in a Storelib section**: its script runs in a sandbox on a copy of the markup, so IntersectionObserver and scroll handlers see nothing of the real page (motion-in-storelib-runtime). The static final state is the fallback.\n\n**Never**: change scroll speed, snap the page against the user, or require scrolling to reveal essential text.\n"
 },
 {
  "file": "entries/motion/motion-stagger.md",
  "source": "---\nid: motion-stagger\ntitle: Staggered sequences\ncategory: motion\nsummary: Staggering lists and grids: delays per item, caps on total time, and order that follows reading.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, stagger, sequence, cascade, choreography]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-fades-slides, motion-principles]\nversion: 1\n---\n**Delay**: 40 to 80ms between items; cap the total sequence at about 400 to 600ms (beyond 8 items, stop increasing the delay).\n\n```css\n[data-reveal] { transition-delay: calc(min(var(--i, 0), 8) * 60ms); }\n```\nSet `--i` from the loop index (`style=\"--i: {{ forloop.index0 }}\"`).\n\n**Order**: follow reading order (left to right, top to bottom). For grids, stagger by row then column, or by diagonal for a softer wave.\n\n**Text reveals**: stagger words or lines, not letters, for anything longer than a short headline.\n\n**Re-entry**: animate once. Repeating staggered reveals on scroll up feels busy.\n"
 },
 {
  "file": "entries/motion/motion-sticky.md",
  "source": "---\nid: motion-sticky\ntitle: Sticky elements in motion\ncategory: motion\nsummary: Sticky panels, sticky add to cart bars and pinned media: offsets, stacking, and making sure they never cover content.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, sticky, pinned, sticky-header, sticky-cta, sticky-panel]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [layout-sticky-storytelling, header-sticky]\nversion: 1\n---\n**Sticky add to cart** (product pages, phones): appears when the main buy button scrolls out of view (observe it), slides up 200ms, includes price and the button, padding for the safe area. Hide when the footer or the main button is visible again.\n\n**Sticky side panel** (product details, course summary): `position: sticky; top: header height + 24px; align-self: start;` and a max height with its own scroll if tall.\n\n**Stacking cards**: sections that stick and stack as you scroll (each `position: sticky; top: N`) can show a process; keep to 3 to 5 items and make sure the last one releases.\n\n**Never** cover form fields, the cookie banner or the chat button; check that sticky elements do not overlap each other.\n"
 },
 {
  "file": "entries/motion/motion-text-reveals.md",
  "source": "---\nid: motion-text-reveals\ntitle: Text reveals\ncategory: motion\nsummary: Line and word reveals for headlines with accessible markup, timing, and when not to animate text.\nintents: [add-motion, build-section, animation]\ntags: [motion, animation, text, reveal, split-text, headline, typewriter, mask]\ncomponents: [motion]\nphases: [build, review]\npriority: 3\nrelated: [motion-stagger, typography-display]\nversion: 1\n---\n**Line mask reveal**: each line slides up from behind a mask (`overflow: clip` on a line wrapper, inner span from translateY(100%) to 0), 600 to 800ms, 60 to 90ms stagger.\n\n**Accessibility**: splitting text into spans can make screen readers read word by word. Keep the real text in the heading and hide the split copy from assistive tech:\n\n```html\n<h2 class=\"reveal\"><span class=\"sr-only\">Built for the long run</span><span aria-hidden=\"true\" class=\"lines\">...</span></h2>\n```\n\n**Limits**: headlines only (up to about 10 words). Never animate body text, prices, dates or legal copy. No typewriter effects for important information; they delay reading.\n\n**Editor**: text inside a reveal must still come from settings so the creator can edit it.\n"
 },
 {
  "file": "entries/responsive/responsive-breakpoints.md",
  "source": "---\nid: responsive-breakpoints\ntitle: Breakpoints, fluid values and container queries\ncategory: responsive\nsummary: Content driven breakpoints, a small standard set, fluid clamp values instead of many steps, and container queries for reusable sections.\nintents: [build-section, responsive, fix-mobile]\ntags: [breakpoints, media-queries, container-queries, clamp, fluid]\nphases: [build]\npriority: 4\nrelated: [responsive-mobile-first, typography-scale]\nversion: 1\n---\n**Breakpoints follow content**: add one where the layout breaks, not at device widths. A useful default set: 600px (large phones, two columns), 900px (tablets, splits), 1200px (desktop, full grid).\n\n**Fluid first**: spacing and display type with `clamp(min, preferred, max)` remove most breakpoints.\n\n**Container queries** let a section adapt to the width it is placed in (a product card in a sidebar vs a full row):\n\n```css\n.cards { container-type: inline-size; }\n@container (min-width: 640px) { .card { display: grid; grid-template-columns: 200px 1fr; } }\n```\n\n**Grids that need no breakpoints**: `grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr));`\n\n**Test widths**: 320, 375, 414, 768, 1024, 1280, 1440, 1920. Check the in-between widths too by resizing slowly.\n"
 },
 {
  "file": "entries/responsive/responsive-images.md",
  "source": "---\nid: responsive-images\ntitle: Responsive images and media\ncategory: responsive\nsummary: srcset and sizes, art direction with picture, aspect ratio boxes, lazy loading, and formats for fast pages.\nintents: [build-section, performance, images]\ntags: [images, srcset, sizes, picture, lazy-loading, aspect-ratio, art-direction]\ncomponents: [image, gallery, hero]\nphases: [build, repair]\npriority: 4\nrelated: [component-gallery, debug-layout-shift]\nversion: 1\n---\n```html\n<img src=\"photo-800.jpg\" srcset=\"photo-480.jpg 480w, photo-800.jpg 800w, photo-1400.jpg 1400w, photo-2000.jpg 2000w\" sizes=\"(min-width: 1200px) 50vw, 100vw\" width=\"1400\" height=\"1750\" alt=\"Coach adjusting a client's deadlift setup\" loading=\"lazy\" decoding=\"async\">\n```\n\n- **sizes** must reflect the rendered width, or the browser downloads the wrong file.\n- **Art direction**: `<picture>` with a portrait source for phones when the landscape crop would lose the subject.\n- **Ratios**: `aspect-ratio` on the container plus `object-fit: cover` and a sensible `object-position` (faces in frame).\n- **Priority**: the hero image `loading=\"eager\" fetchpriority=\"high\"`; everything below the fold lazy.\n- **Formats**: AVIF or WebP with JPEG fallback where the pipeline supports it; Storelib's asset filter handles sizing for uploaded images.\n- **Alt text**: describe what matters in context; empty `alt=\"\"` for decorative images.\n"
 },
 {
  "file": "entries/responsive/responsive-mobile-first.md",
  "source": "---\nid: responsive-mobile-first\ntitle: Designing the phone layout first\ncategory: responsive\nsummary: Decide per section what stacks, in what order, how text and images resize, and what becomes a scroll row, starting at 375px.\nintents: [build-section, fix-mobile, responsive]\ntags: [mobile, mobile-first, phone, responsive, stack, small-screen]\nphases: [plan, build, review]\npriority: 5\nrelated: [responsive-breakpoints, responsive-touch, anti-slop-weak-mobile]\nversion: 1\n---\nMost visitors to creator sites arrive from social apps on phones. Design 375px first, then add.\n\n**Per section, decide**\n- Stacking order (write the DOM in that order).\n- Which images crop, and to what ratio (portrait 4:5 often beats a squashed landscape).\n- Whether a grid becomes 1 column, 2 columns, or a horizontal scroll row.\n- Which text shrinks (display) and which does not (body stays 16 to 18px).\n- Which decorative elements disappear (floating details, big empty columns).\n- Spacing: section padding about 60% of desktop.\n\n**Base styles are the phone styles**; add `@media (min-width: ...)` for larger screens. Container queries (`@container`) are better for components that appear in different widths.\n\n**First screen on phones**: brand, what it is, the main action. If the hero image pushes the action down, shorten the image (`aspect-ratio: 4/5` or `min-height: 60svh`).\n\n**Never** let the page scroll sideways. Common causes: fixed widths, `100vw` (includes the scrollbar), long words, negative margins, wide tables.\n"
 },
 {
  "file": "entries/responsive/responsive-touch.md",
  "source": "---\nid: responsive-touch\ntitle: Touch targets, gestures and safe areas\ncategory: responsive\nsummary: Tap target sizes and spacing, hover alternatives, gesture etiquette, iOS safe areas and viewport units on phones.\nintents: [fix-mobile, build-component]\ntags: [touch, tap-target, gestures, safe-area, viewport, svh, ios]\nphases: [build, review]\npriority: 4\nrelated: [responsive-mobile-first, a11y-checklist]\nversion: 1\n---\n- **Tap targets**: at least 44x44px (24px is the WCAG minimum, 44 to 48 is the comfortable one); at least 8px between adjacent targets. Expand small icon links with padding.\n- **No hover dependence**: anything revealed on hover must be visible or tappable on touch.\n- **Gestures**: swipe only where people expect it (galleries, carousels, sheets), always with a button alternative. Do not override pinch zoom (`user-scalable=no` is forbidden).\n- **Safe areas**: fixed bars use `env(safe-area-inset-bottom)` and `env(safe-area-inset-top)`; the viewport meta needs `viewport-fit=cover` for them to be non zero.\n- **Viewport units**: `100vh` is wrong on mobile browsers with dynamic bars; use `svh` (small), `dvh` (dynamic, can cause jumps) or `lvh`. Storelib themes expose `var(--sl-vh)`.\n- **Inputs**: 16px font minimum to prevent iOS zoom; right `inputmode` for keyboards.\n"
 },
 {
  "file": "entries/state/state-async.md",
  "source": "---\nid: state-async\ntitle: Empty, loading, error and processing states for data\ncategory: state\nsummary: The states of anything that loads or lists data (products, posts, bookings): empty for visitors vs editors, skeletons, partial failure and retry.\nintents: [build-component, fix-states, review]\ntags: [empty-state, loading, error, processing, skeleton, retry, no-results]\ncomponents: [product-grid, list, search, booking]\nphases: [build, review]\npriority: 4\nrelated: [component-loading, storelib-honest-data]\nversion: 1\n---\n**Empty**\n- *For visitors*: if a section has nothing real to show (no products in the collection, no posts), hide the section. Do not show \"Coming soon\" filler unless the creator wrote it.\n- *For editors*: show a short instruction inside `{% if page.in_editor %}` (\"Your published products appear here\").\n- *No results* (search, filters): say what was searched, offer to clear filters, link to the full list.\n\n**Loading**: skeletons that match the final layout for lists; a spinner inside the control for actions.\n\n**Error**: say what failed in plain words, keep what did load, offer Retry. \"We could not load the timetable. Try again.\" Do not show raw error codes to visitors.\n\n**Processing**: long operations (payments, bookings) show a clear in progress state and prevent duplicate actions; never claim success before the server confirms.\n\n**Partial**: a booking slot that was taken meanwhile: explain and show the next available, rather than a generic failure.\n"
 },
 {
  "file": "entries/state/state-form-validation.md",
  "source": "---\nid: state-form-validation\ntitle: Form validation, submitted and error states\ncategory: state\nsummary: When to validate, how errors look and are announced, error summaries, success and submitted states, and preserving input.\nintents: [build-component, forms, fix-states]\ntags: [validation, error, success, submitted, invalid, required, form-states]\ncomponents: [form, input]\nphases: [build, review]\npriority: 4\nrelated: [component-forms, component-inputs]\nversion: 1\n---\n**Timing**: validate on submit first. After a field has been submitted invalid, re-validate it as the user types so the error clears as soon as it is fixed. Do not show errors on fields the user has not reached.\n\n**Error state of a field**\n```html\n<input id=\"email\" aria-invalid=\"true\" aria-describedby=\"email-error\">\n<p id=\"email-error\" class=\"error\">Enter an email like name@example.com</p>\n```\nMessages say how to fix it, not just \"Invalid\". Red border plus an icon plus the text; colour alone is not enough.\n\n**Error summary**: on submit with errors, show a box at the top (\"There are 2 problems\") with links to each field, move focus to it (`tabindex=\"-1\"` then `.focus()`).\n\n**Required**: mark optional fields instead when most are required; or mark required with text, not just an asterisk.\n\n**Submitting**: button disabled with \"Sending\", inputs readonly, `aria-busy` on the form. Guard against double submit.\n\n**Submitted / success**: replace the form or show a confirmation panel with what happens next; move focus to it; offer a way to submit another if relevant.\n\n**Server error**: keep everything typed; show a retry; never clear the form.\n"
 },
 {
  "file": "entries/state/state-interactive-matrix.md",
  "source": "---\nid: state-interactive-matrix\ntitle: The interactive state matrix\ncategory: state\nsummary: Every state an interactive element needs (default, hover, active, focus-visible, disabled, loading, selected, expanded, collapsed) with how each should look and be announced.\nintents: [build-component, review, fix-states]\ntags: [states, hover, focus, active, disabled, selected, expanded, collapsed, pressed]\ncomponents: [button, link, tabs, accordion, card, input]\nphases: [build, review]\npriority: 5\nrelated: [component-buttons, a11y-keyboard-focus]\nversion: 1\n---\n| State | Visual | Semantics |\n| --- | --- | --- |\n| Default | clear affordance (looks clickable) | real element |\n| Hover | small change: colour 8 to 12%, underline, border | none (pointer only, guard with `@media (hover: hover)`) |\n| Active / pressed | darker or 1px shift, immediate | `aria-pressed` for toggles |\n| Focus visible | 2px outline, 2 to 4px offset, 3:1 contrast | `:focus-visible`, never `outline: none` without a replacement |\n| Disabled | muted, no hover, `cursor: not-allowed` | `disabled` or `aria-disabled=\"true\"` (keeps it focusable for explanation) |\n| Loading / processing | spinner or label change, fixed width | `aria-busy=\"true\"`, live status text |\n| Selected | filled or marked, not colour only | `aria-selected` or `aria-current` |\n| Expanded / collapsed | icon rotates or changes | `aria-expanded` on the control |\n| Success | check plus text | status message |\n| Error | icon plus text plus colour | `aria-invalid`, message linked by `aria-describedby` |\n\n**Rules**: hover must never be the only way to reveal content or actions (touch has no hover). Focus and hover can share a style but focus must be at least as visible. Every state change that happens without a page load and matters to the user is announced.\n\n```css\n@media (hover: hover) { .link:hover { text-decoration-thickness: 2px; } }\n.link:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; border-radius: 2px; }\n```\n"
 },
 {
  "file": "entries/storelib/storelib-bookings.md",
  "source": "---\nid: storelib-bookings\ntitle: Bookings and appointments\ncategory: storelib\nsummary: Presenting sessions, classes and appointments that use Storelib booking forms: what to show before the booking step and what never to fake.\nintents: [booking, build-section, contact]\ntags: [bookings, appointments, sessions, classes, calendar, schedule, availability]\ncomponents: [form, calendar, button]\ncapabilities: [bookings]\nphases: [plan, build]\npriority: 4\nrelated: [storelib-forms, industry-fitness-coach, industry-wellness, schedule]\nversion: 1\n---\n**Before the booking step** people need: what the session is, duration, where (address or online), price or \"free first call\" as the creator set it, who runs it, cancellation terms. Put these next to the book button.\n\n**The booking itself** happens in the creator's published booking form (Storelib Forms handles slots, time zones, double booking protection and optional payment). The capabilities report how many booking forms exist. Link or place that form; the page's job is to get people there with the right expectations.\n\n**Never**: draw a fake calendar or time slot grid, show \"3 spots left\", or promise availability. If no booking form exists, use an enquiry form or contact link and say how the creator will reply.\n\n**Schedules** (class timetables) are content the creator edits as blocks, or real event data; label them \"Typical week\" if they are not live availability.\n"
 },
 {
  "file": "entries/storelib/storelib-checkout-cta.md",
  "source": "---\nid: storelib-checkout-cta\ntitle: Checkout and buy calls to action\ncategory: storelib\nsummary: Where buy buttons go, wording by product type, cart drawer vs direct checkout, and honest pricing next to every buy action.\nintents: [product-page, build-section, conversion]\ntags: [checkout, buy-button, cta, cart, add-to-bag, conversion, purchase]\ncomponents: [button, cart, drawer]\ncapabilities: [products]\nphases: [plan, build]\npriority: 5\nrelated: [storelib-products, component-buttons, component-drawer]\nversion: 1\n---\n**Wording by product**\n- Physical goods: \"Add to bag\" or \"Add to cart\" (cart flow, people buy several).\n- A single digital product, course or pack: \"Buy now\" or \"Get the pack\" straight to `checkout_url` (one item flows are faster).\n- Memberships and subscriptions: \"Join for {{ price }} a month\" with the real price and period.\n- Bookings: \"Book a session\" or \"Choose a time\".\n\n**Placement**: one primary buy action per product view; repeat at the end of long sales pages; a sticky bar on phones for long product pages.\n\n**Next to every buy action**: the real price, what happens next (instant download, ships in N days only if the creator states it), and the refund or cancellation policy link if one exists.\n\n**Cart**: sections can use the built-in drawer (`data-storelib-cart`) or their own panel (`data-storelib-cart-panel`). The checkout itself is Storelib's, priced again on the server; nothing a section prints can change what is charged.\n\n**Never**: fake urgency (\"Offer ends in 09:59\"), pre-ticked add ons, hidden fees language, discount codes the creator did not create.\n"
 },
 {
  "file": "entries/storelib/storelib-community.md",
  "source": "---\nid: storelib-community\ntitle: Communities on Storelib sites\ncategory: storelib\nsummary: Showing a Storelib community with the community picker: what it is, how to join, and what visitors can and cannot see.\nintents: [membership, build-section, community]\ntags: [community, members, join, forum, group, community-picker]\ncomponents: [card]\ncapabilities: [community]\nphases: [plan, build]\npriority: 3\nrelated: [industry-membership-community, storelib-memberships]\nversion: 1\n---\n**Binding**: a section points at a real community with a `community_picker` setting; only communities that are published, public and not hidden are offered (capabilities lists them). The AI builder binds the first one to a community card when one exists.\n\n**Present**: the community's name and purpose, who it is for, what happens inside (posts, events, chats) in concrete terms, whether it is free or part of a membership, and the join action.\n\n**Privacy**: never show member names, avatars or posts from a private community on the public site. Do not fabricate activity (\"12 people online\").\n\n**Visual**: real photos from community events if the creator has them; otherwise typography and a clear description beat stock group photos.\n"
 },
 {
  "file": "entries/storelib/storelib-digital-downloads.md",
  "source": "---\nid: storelib-digital-downloads\ntitle: Digital downloads and packs\ncategory: storelib\nsummary: Selling files (sample packs, templates, ebooks, presets): previews, contents list, formats, licence and instant delivery messaging.\nintents: [product-page, build-section]\ntags: [digital, downloads, files, sample-packs, templates, presets, ebook, licence]\ncomponents: [product-showcase, media-player]\ncapabilities: [digital]\nphases: [plan, build]\npriority: 4\nrelated: [industry-music-producer, industry-digital-creator, storelib-products]\nversion: 1\n---\n**Show before buying**: real previews (audio clips, page spreads, screenshots, before and after for presets), the contents list (counts, formats, file size, compatibility) from product fields or the creator's description, and the licence in plain words.\n\n**Delivery line**: \"Download right after checkout. We also email you the link.\" Only if that is how the product is set up (Storelib digital products deliver files after purchase).\n\n**Variants**: different licences or formats as variants with real prices; explain the difference in a short table.\n\n**Buy**: one item purchase goes straight to `checkout_url`; bundles are their own products.\n\n**Never**: invent file counts, BPM ranges, \"used by top producers\", or download numbers.\n"
 },
 {
  "file": "entries/storelib/storelib-editable-components.md",
  "source": "---\nid: storelib-editable-components\ntitle: Code backed components that stay editable\ncategory: storelib\nsummary: How AI written custom components expose every word, link, image and choice as editable settings or blocks so creators can change them in the visual editor without code.\nintents: [build-component, build-section, edit]\ntags: [editable, settings, schema, manifest, blocks, custom-component, props, visual-editor]\ncomponents: [section, schema]\nphases: [plan, build, review]\npriority: 5\nrelated: [core-iteration, storelib-honest-data, blocks]\nversion: 1\n---\nA generated component is only useful if the creator can keep editing it. Its source is preserved; its content lives in settings.\n\n**Expose as settings** (one per thing a creator would change): headings and body text (text or richtext), images (image_picker), links (url), menus (link_list), products (product_picker, product_list, collection_picker), community (community_picker), colours that should be changeable (color defaulting to a scheme colour), layout choices (select with named options), sizes and speeds (range with sensible min, max, step).\n\n**Expose as blocks**: any list the creator grows: questions, quotes, slides, team members, timeline steps. Never `question_1`, `question_2` settings.\n\n**Defaults and presets**: fill them so the component looks finished when added; defaults are content the creator would plausibly have (from the brief), never fake proof.\n\n**Keep design decisions in code**: exact spacing, easing, grid tracks. A setting is a merchant choice (\"Image position: left or right\"), not a CSS property (\"flex-direction\").\n\n**On edit**: a follow up that changes content edits setting values, not source; a structural change keeps existing setting ids so the creator's values survive.\n"
 },
 {
  "file": "entries/storelib/storelib-forms.md",
  "source": "---\nid: storelib-forms\ntitle: Forms and email capture on Storelib\ncategory: storelib\nsummary: Subscribe forms that reach the creator's subscribers, published Storelib forms for enquiries, and the states the form runtime sets.\nintents: [forms, newsletter, contact, build-section]\ntags: [forms, newsletter, subscribe, contact, enquiry, email-capture, lead]\ncomponents: [form, input]\nphases: [plan, build]\npriority: 4\nrelated: [component-forms, state-form-validation, footer-newsletter]\nversion: 1\n---\n**Email sign up**: `<form data-storelib-form=\"subscribe\">` with `<input type=\"email\" name=\"email\">` (and `name=\"name\"` if asked) and a visible label. No script, no action URL: submissions go to the creator's Subscribers. The runtime sets `data-state=\"sending\" | \"done\" | \"error\"` on the form for styling, and an element marked `data-storelib-success` (hidden) is shown on success.\n\n```css\nform[data-state=\"sending\"] button { opacity: .6; pointer-events: none; }\nform[data-state=\"error\"] .error { display: block; }\n```\n\n**Other mailing services**: set the action and `data-storelib-form=\"native\"`.\n\n**Enquiries, applications, bookings**: the creator builds these in Storelib Forms (with booking questions, rules, payment). The capabilities tell the agent how many published forms and booking forms exist. Link or place the real form; do not imitate one with a fake form that posts nowhere.\n\n**Copy**: say what happens after submitting and how often emails come.\n"
 },
 {
  "file": "entries/storelib/storelib-honest-data.md",
  "source": "---\nid: storelib-honest-data\ntitle: Never fake data on a Storelib site\ncategory: storelib\nsummary: Everything factual (products, prices, stock, reviews, numbers, logos, dates, availability, members) comes from the store or the creator; what to do when it does not exist.\nintents: [build-site, generate-page, review, write-copy]\ntags: [honesty, real-data, fake-data, placeholder, empty-state, proof, prices]\nphases: [plan, build, review]\npriority: 5\nrelated: [anti-slop-fake-proof, state-async, store-binding]\nversion: 1\n---\n**Rule**: the agent never invents a fact a visitor could rely on. That includes product names, prices, compare at prices, stock and \"only N left\", ratings and review counts, testimonials and their names, customer or press logos, follower or member counts, years in business, certifications, event dates and seats, booking availability, discount codes, and delivery promises.\n\n**Where facts come from**\n- Products, prices, variants, availability, checkout links: the store (product, collection and product_list settings; never typed).\n- Communities, published forms and booking forms, blog posts: the site's capabilities (lib/website-builder/ai-site/capabilities.ts).\n- Quotes, credentials, press: only what the creator wrote in the brief or their profile.\n\n**When something is missing**\n1. Leave the section out of the generated page, or\n2. Include it with an editor only prompt inside `{% if page.in_editor %}` so the creator can fill it, and nothing is shown to visitors.\n\n**Copy that implies facts** is also data: \"Our bestselling pack\", \"Loved by thousands\", \"Award winning\". Remove it unless true.\n\nThe fill step checks prices and numbers against what the store allows (`allowedFacts`); generated sections that type products by hand are refused at save.\n"
 },
 {
  "file": "entries/storelib/storelib-memberships.md",
  "source": "---\nid: storelib-memberships\ntitle: Selling memberships honestly\ncategory: storelib\nsummary: Presenting recurring memberships: concrete benefits, real price and period, what unlocks after joining, cancelling, and no fake member counts.\nintents: [membership, pricing, build-section]\ntags: [membership, subscription, recurring, members, tiers, join]\ncomponents: [pricing]\ncapabilities: [memberships]\nphases: [plan, build]\npriority: 4\nrelated: [industry-membership-community, component-pricing, storelib-community]\nversion: 1\n---\n**Show**: the membership's name, real price and billing period from the product, what members get with frequency (\"a new sample pack every month\", \"two live Q&As a month\"), what unlocks immediately after joining (community access, archive, discounts), and how to cancel if the creator offers cancel any time.\n\n**Tiers**: only the tiers that exist as products. Compare them by differences, not by repeating shared benefits in each column.\n\n**Proof**: real member quotes if supplied. Never \"Join 5,000 members\" without data.\n\n**Join flow**: the action goes to the membership's real checkout. After joining, link people to where the benefit lives (the community, the downloads page).\n\n**Avoid**: \"Exclusive\", \"VIP\", \"inner circle\" language without concrete benefits; countdowns to price rises that are not scheduled.\n"
 },
 {
  "file": "entries/storelib/storelib-own-chrome.md",
  "source": "---\nid: storelib-own-chrome\ntitle: A free site's own header, footer, cart drawer, search and switches\ncategory: storelib\nsummary: On a free site the host draws no built-in chrome; the site's own header and footer use the page's hooks for the cart drawer, search window, menus, language and currency, so they look like the concept and still use live data.\nintents: [build-header, build-footer, build-site, add-cart, add-search]\ntags: [header, footer, cart drawer, cart, search, search panel, language, locale, currency, selector, switcher, hooks, own chrome, free site, mega menu, mobile menu]\ncomponents: [header, footer, drawer, navigation]\ncapabilities: []\nphases: [plan, build]\npriority: 5\nrelated: [component-interactive-library, header-mobile-menu, storelib-checkout-cta, core-links-and-actions]\nversion: 1\n---\n**Free site**: when the site's chrome is the AI's own (blank mode, agent jobs), the page draws no built-in header, footer, announcement bar, breadcrumbs, cart drawer, search window, language or currency switcher, cookie bar or floating UI. Your header (schema kind header) and footer (kind footer) are the site's chrome on every page. Write both, always.\n\n**Hooks the page wires for your markup** (no script needed):\n- Menu: a link_list setting (default main-menu) looped with `settings.menu.links` and `link.links`; your own mobile menu with a popover, or `data-storelib-menu` for the built-in drawer.\n- Cart: `data-storelib-cart` on the button, `data-storelib-cart-count` for the badge (`[data-count=\"0\"]` hides it). Your own drawer: an element with `data-storelib-cart-panel` in the same section (the page sets `data-open=\"true\"` or `\"false\"`, aria-hidden and inert), inside it `data-storelib-cart-lines` holding ONE hidden `data-storelib-cart-line` pattern with `data-line-title`, `-variant`, `-price`, `-qty`, `-image`, `-url` and the buttons `data-line-inc`, `-dec`, `-remove`; plus `data-storelib-cart-subtotal`, `data-storelib-cart-empty`, `data-storelib-cart-filled`, `data-storelib-checkout`, `data-storelib-cart-close`.\n- Search: your own window is an element with `data-storelib-search-panel` in the section; its `data-storelib-search` buttons open it instead of the built-in one. Inside: `data-storelib-search-input`, `data-storelib-search-results` holding ONE hidden `data-storelib-search-result` with `data-result-title`, `-price`, `-image` (img), `-url` (link), `-kind`; and `data-storelib-search-empty`, `-loading`, `-close`.\n- Language: `data-storelib-locale-list` holding ONE hidden `data-storelib-locale-option` with `data-option-label` and `data-option-code`; the page copies it per language, marks the active one `aria-current=\"true\"`, switches on click, writes the active label into `data-storelib-locale-current`, and hides the list when the site has one language. Currency: the same with `data-storelib-currency-list`, `-option`, `-current`.\n- Sign up: a form with `data-storelib-form=\"subscribe\"`, an email input named email, a submit button, and a `data-storelib-success hidden` message.\n\n**Always link the plain page too**: the cart button is a link to `routes.cart_url` and search to `routes.search_url`, so they work before the page's script loads.\n\n**Design**: the header is the first thing a visitor reads; make it belong to the concept (a type led bar, a split logo, a side rail, a floating pill only if the concept is playful). Footers can carry the brand name set huge, the sign up, menus and switches. The working example is ai_site_header and ai_site_footer (component-interactive-library).\n"
 },
 {
  "file": "entries/storelib/storelib-products.md",
  "source": "---\nid: storelib-products\ntitle: Presenting Storelib products\ncategory: storelib\nsummary: How sections read products (shop, collection, chosen list, single product), what each card prints, and the add to cart and checkout hooks.\nintents: [product-page, collection-page, build-section]\ntags: [products, product-grid, collection, product-picker, add-to-cart, shop]\ncomponents: [product-card, product-grid, product-showcase]\ncapabilities: [products]\nphases: [plan, build]\npriority: 5\nrelated: [store-binding, component-product-showcase, storelib-checkout-cta]\nversion: 1\n---\n**Choosing which products** (a section setting, chosen in the sidebar): a select `source` with `shop` (all published products, `{% for block in products limit: settings.product_count %}`), `collection` (a collection_picker), or `chosen` (a product_list). One featured product uses a product_picker.\n\n**A card prints** `block.settings.title`, `.price` (already formatted, print it as is), `.compare_price`, `.image | asset` (with width, height, alt), `.url | url`, `.available`, `.tag` (\"Sold out\" or empty), `.variants`, `.checkout_url`.\n\n**Buying**\n- Add to cart: `<button type=\"button\" data-storelib-add-to-cart=\"{{ block.id }}\" ...>` inside `{% if block.settings.available %}`.\n- Straight to checkout (single product pages, digital products): link to `checkout_url`.\n\n**Design guidance**: one image ratio per grid; price close to the name; sold out shown as text, not hidden; quick add only for products without options.\n\n**Never**: type a product name, price, photo or \"Sold out\" into markup, defaults or presets; give a product a price setting; compute discounts.\n"
 },
 {
  "file": "entries/storelib/storelib-programs-courses.md",
  "source": "---\nid: storelib-programs-courses\ntitle: Courses and programmes on Storelib\ncategory: storelib\nsummary: Course products on the site: outcome, curriculum from the real modules, format, price and enrolment; nothing invented about students or results.\nintents: [product-page, course-page, build-section]\ntags: [courses, programme, curriculum, modules, lessons, enrol, cohort]\ncomponents: [accordion, pricing]\ncapabilities: [courses]\nphases: [plan, build]\npriority: 4\nrelated: [industry-education, curriculum, component-accordion]\nversion: 1\n---\n**Course page content from the product**: title, price, description, images; modules and lessons where the product exposes them. If the curriculum is not available as data, write it as blocks the creator edits, not invented module names presented as final.\n\n**Format details** (self paced, live, start date, length) only from the product or the creator's brief.\n\n**Enrol**: straight to the course's checkout. If the course is free, the action still uses the real flow.\n\n**After purchase**: say where the course is accessed (the creator's Storelib account area), in one line.\n\n**Avoid**: \"Join 3,000 students\", completion stats, \"Certificate included\" unless real, testimonials written by the model.\n"
 },
 {
  "file": "entries/style/style-agency.md",
  "source": "---\nid: style-agency\ntitle: Agency and studio style\ncategory: style\nsummary: Confident statement type, big work imagery and a distinctive interaction or two; the frame stays quieter than the work.\nintents: [choose-style, build-site, redesign]\ntags: [agency, studio, bold, statement, case-studies, creative-studio]\nstyles: [agency, studio]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-agency, layout-asymmetric-grid]\nversion: 1\n---\n**Signals**: an opening statement set very large (80 to 200px on desktop, clamp down for phones), a project index, large case study images, a custom interaction (hover previews, cursor labels) used consistently.\n\n**Type**: one display family with personality, used big; a neutral text face. Tight leading on display (0.9 to 1.05).\n\n**Layout**: asymmetric grids, generous margins, images at different scales, text that sometimes overlaps images (with contrast protection).\n\n**Motion**: purposeful and consistent: one reveal style for headings, one for images, one hover treatment. Page transitions only if they are fast (under 400ms) and never block reading.\n\n**Don't**: use every trend at once. Pick one hero idea. Avoid generic \"We are a creative studio\" headlines; state a point of view or the actual offer.\n\n**Combines with**: Swiss (precise studio), dark cinematic (production companies), typography led (branding studios).\n"
 },
 {
  "file": "entries/style/style-brutalism.md",
  "source": "---\nid: style-brutalism\ntitle: Brutalism\ncategory: style\nsummary: Raw, honest, unpolished web: default looking elements, system or mono type, visible structure, hard contrast, deliberate roughness.\nintents: [choose-style, build-site, redesign]\ntags: [brutalism, brutalist, raw, system-fonts, unpolished, web-brutalism]\nstyles: [brutalism, brutalist]\nphases: [concept, plan, build]\npriority: 3\nrelated: [style-neo-brutalism, style-industrial]\nversion: 1\n---\n**What it is**: exposing the material of the web. Underlined blue links, system fonts, visible borders, tables, plain buttons, little or no decoration.\n\n**Specs**: system UI or monospace type; borders 1 to 2px solid black; radius 0; no shadows; backgrounds white, grey or one flat colour; hover states as inversions (black background, white text).\n\n**Use for**: artists, independent publishers, music collectives, experimental studios, anything that wants to read as anti corporate.\n\n**Keep it usable**: brutal is a look, not permission to fail accessibility. Contrast still passes, focus is still visible (a thick outline suits the style), tap targets still 44px, text still readable at 16px or larger.\n\n**Don't**: mistake chaos for brutalism. The structure is plain and obvious; there is nothing random about it.\n\n```css\na { color: #00e; text-decoration: underline; text-underline-offset: 2px; }\na:hover { background: #000; color: #fff; }\nbutton { font: inherit; border: 2px solid #000; background: #fff; padding: 10px 16px; border-radius: 0; }\n```\n"
 },
 {
  "file": "entries/style/style-colourful-flat.md",
  "source": "---\nid: style-colourful-flat\ntitle: Colourful and flat\ncategory: style\nsummary: Confident flat colour fields, hard edges and shadows, cut out objects; joyful without gradients or glass.\nintents: [choose-style, build-site, redesign]\ntags: [colourful, colorful, flat, bold-colour, colour-blocking, playful, pop]\nstyles: [colourful, flat, playful]\nphases: [concept, plan, build]\npriority: 3\nrelated: [core-inspiration, core-visual-concept-first]\nversion: 1\n---\n**Signals**: whole sections in one saturated colour; a palette of three or four flat colours used as fields, not accents everywhere; hard offset shadows; cut out product shots; thick borders.\n\n**Layouts**: colour changes at each section to mark chapters; a sticker like badge only where it carries real news; large type knocked out of colour fields.\n\n**Type**: Soft rounded, Wide display or Characterful grotesk systems.\n\n**Do**: check text contrast on each colour field (4.5:1); keep one neutral for long text.\n\n**Don't**: purple to blue gradients, glassmorphism, blurred blobs, emoji as icons; those are a different, overused look.\n\n**Combines with**: playful, neo-brutalism, kids and education, food, community.\n"
 },
 {
  "file": "entries/style/style-combining.md",
  "source": "---\nid: style-combining\ntitle: Combining styles into one concept\ncategory: style\nsummary: How to mix two or three styles with a primary and secondary role, which pairs work, which clash, and how to resolve conflicts between their rules.\nintents: [choose-style, build-site, redesign]\ntags: [combine, mix, hybrid, styles, concept, direction]\nstyles: [any]\nphases: [concept]\npriority: 5\nrelated: [core-visual-concept-first, core-diversity]\nversion: 1\n---\nA concept usually combines styles. Give each one a role so their rules do not fight.\n\n- **Primary style** decides structure: grid, spacing, type scale, density.\n- **Secondary style** decides surface: colour, imagery treatment, one or two signature details.\n- **Accent style** (optional) supplies a single move: a marquee, a hover, a texture.\n\n**Pairs that work**\n- Editorial + luxury: magazine structure, luxury pace and palette.\n- Swiss + industrial: grid discipline with mono specs and a safety accent.\n- Minimalism + dark cinematic: few elements, dramatic imagery.\n- Neo brutalism + playful: thick outlines, bright fills, springy buttons.\n- Organic + light editorial: warm paper, serif reading type, natural photography.\n- Typography led + agency: statement type with project index.\n\n**Pairs that clash** (pick one): luxury + neo brutalism (pressure vs calm); glassmorphism + brutalism (translucent polish vs raw honesty); neumorphism + dark cinematic (soft low contrast on dark is unreadable).\n\n**Resolving conflicts**: when two rules disagree, the primary style wins for layout and type; the secondary wins for colour and imagery. Write the resolution into the concept (\"radius 0 everywhere except the playful sticker buttons\") so every section follows the same answer.\n\nNever combine more than three. Four styles is no style.\n"
 },
 {
  "file": "entries/style/style-contemporary-ecommerce.md",
  "source": "---\nid: style-contemporary-ecommerce\ntitle: Contemporary ecommerce\ncategory: style\nsummary: Clean modern shops: confident product imagery, fast scannable grids, clear variant and cart UI, brand personality in type and colour rather than ornaments.\nintents: [choose-style, build-site, redesign]\ntags: [ecommerce, shop, store, retail, dtc, product-grid, catalogue]\nstyles: [contemporary-ecommerce, ecommerce, shop]\nphases: [concept, plan, build]\npriority: 3\nrelated: [ecommerce, component-product-showcase, storelib-products]\nversion: 1\n---\n**Signals**: product grids with consistent image ratios on light neutral backgrounds (`#f3f2ef` behind cut out products works well), small type for name and price, brand personality in the header, hero and one accent, quick add buttons that appear on hover (desktop) and stay visible (touch).\n\n**Product grid**: 2 columns at phone, 3 at tablet, 4 at desktop; 12 to 24px gaps; name 14 to 15px, price 14px tabular; colour swatches only if the product has colour variants.\n\n**Product page**: gallery left (60%), details right sticky on desktop; variant pickers as buttons, not selects, when there are few options; add to cart full width on phones; shipping and returns as an accordion from real policies.\n\n**Cart**: a drawer with line items, quantity steppers, subtotal and checkout; empty state with a link back to the shop.\n\n**Avoid**: fake scarcity, fake reviews, popups in the first five seconds, carousels as the main way to browse.\n"
 },
 {
  "file": "entries/style/style-creator.md",
  "source": "---\nid: style-creator\ntitle: Creator sites\ncategory: style\nsummary: Personality first sites for creators: their face, their voice, their latest thing and every way to support or buy, organised by priority.\nintents: [choose-style, build-site, redesign]\ntags: [creator, youtuber, influencer, personal, link-in-bio, newsletter, audience]\nstyles: [creator, personal, influencer]\nphases: [concept, plan, build]\npriority: 3\nrelated: [creator, industry-digital-creator, storelib-products]\nversion: 1\n---\n**Visitor**: a fan or a new follower arriving from social. Usually on a phone, short attention, wants the latest thing and a way to support.\n\n**Structure**: the creator (photo, name, one line) -> the newest or main offer (product, course, membership, community) -> other offers in priority order -> latest content (videos, posts from the blog) -> newsletter -> socials.\n\n**Visual**: borrow the creator's channel identity: their colours, thumbnail style, typeface. A creator site should feel like their videos, not like a template.\n\n**Do**: big tap targets, offers with real prices, a short about in their own voice.\n\n**Don't**: invent follower counts, brand logos (\"as seen on\") that are not real, or a wall of identical link buttons when the store has richer content to show.\n"
 },
 {
  "file": "entries/style/style-dark-cinematic.md",
  "source": "---\nid: style-dark-cinematic\ntitle: Dark cinematic\ncategory: style\nsummary: Near black canvases, film-like imagery, light used as accent and slow dramatic reveals; atmosphere without unreadable contrast.\nintents: [choose-style, build-site, redesign]\ntags: [dark, cinematic, film, moody, night, noir, dramatic]\nstyles: [dark-cinematic, dark, cinematic]\nphases: [concept, plan, build]\npriority: 3\nrelated: [noir_gallery, midnight_tech, motion-image-transforms]\nversion: 1\n---\n**Signals**: backgrounds `#0b0b0c` to `#151515` (not pure black for large areas), off white text `#ecebe8`, imagery with deep shadows, letterbox crops (2.39:1 or 21:9), slow reveals, grain or subtle vignette.\n\n**Contrast**: body text at least 4.5:1 against the darkest part behind it. Grey text on black is the classic failure; `#8a8a8a` on `#0b0b0c` is about 5.8:1 and is the lowest comfortable muted tone.\n\n**Light as accent**: one warm or cool accent (amber `#e0a050`, ice `#9fd3ff`) used for actions and small details. No neon glow halos.\n\n**Video**: muted, `playsinline`, poster image, paused when off screen, a pause control. Do not autoplay on reduced motion.\n\n**Motion**: 600 to 1000ms reveals, clip-path wipes, slow scale (1.06 to 1) on images. Text appears after the image, never before.\n\n**Combines with**: editorial (film journal), luxury (fragrance, night collections), events.\n"
 },
 {
  "file": "entries/style/style-editorial.md",
  "source": "---\nid: style-editorial\ntitle: Editorial\ncategory: style\nsummary: Magazine thinking: strong typographic hierarchy, columns, captions, pull quotes and image spreads that pace a story.\nintents: [choose-style, build-site, redesign]\ntags: [editorial, magazine, journal, serif, columns, print]\nstyles: [editorial, magazine]\nphases: [concept, plan, build]\npriority: 3\nrelated: [editorial_ink, layout-editorial-columns, style-light-editorial]\nversion: 1\n---\n**Signals**: a display serif or a characterful grotesk at large sizes, a clear text column (60 to 72 characters), captions, bylines, issue or section labels that carry information, images with varied widths.\n\n**Layout**: a 12 column grid where text sits in 6 to 7 columns offset from the left; images alternate between full bleed, inset with caption and two up. Use rules (1px lines) to separate, not cards.\n\n**Type moves**: drop caps on long reads, pull quotes set at 1.5 to 2x body in italic, small caps for labels, tabular numerals in data.\n\n**Do**: write real captions; they are part of the design. Vary rhythm: a dense text spread followed by a full image.\n\n**Don't**: fake magazine furniture (\"Issue 01\", \"Vol. 3\") unless it means something to the brand. Do not centre every text block.\n\n**Combines with**: luxury (slower, more space), Swiss (grid discipline, sans display), fashion (image led lookbook spreads), dark cinematic (night editions).\n"
 },
 {
  "file": "entries/style/style-experimental.md",
  "source": "---\nid: style-experimental\ntitle: Experimental\ncategory: style\nsummary: Unusual layouts, interactions and type for art, music and culture, with a usable core underneath.\nintents: [choose-style, build-site, redesign]\ntags: [experimental, avant-garde, unconventional, art, weird, generative]\nstyles: [experimental, avant-garde]\nphases: [concept, plan, build]\npriority: 3\nrelated: [style-brutalism, style-typography-led]\nversion: 1\n---\n**What it allows**: breaking the grid, overlapping elements, unconventional navigation, cursor effects, generative visuals, unusual scroll behaviour.\n\n**What it still requires**: a normal, focusable link list somewhere (often the footer) so every page is reachable; readable text for anything that must be read (dates, prices, legal); reduced motion alternatives; no trap for keyboard users; acceptable performance on mid range phones.\n\n**Method**: be experimental in one or two layers (layout and type, or motion and imagery) and conventional in the rest (forms, cart, checkout are never experimental).\n\n**Good fits**: musicians, galleries, festivals, art schools, independent labels.\n\n**Don't**: ship heavy canvas or WebGL backgrounds without a static fallback and a pause; run animations that cause jank on scroll; hide content behind mystery meat navigation with no labels.\n"
 },
 {
  "file": "entries/style/style-fashion.md",
  "source": "---\nid: style-fashion\ntitle: Fashion style\ncategory: style\nsummary: Campaign imagery at full size, tight type, editorial cropping and product grids that never fight the photos.\nintents: [choose-style, build-site, redesign]\ntags: [fashion, lookbook, campaign, runway, editorial-fashion, apparel]\nstyles: [fashion, lookbook]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-fashion, luxury_fashion, style-editorial]\nversion: 1\n---\n**Signals**: full bleed campaign photography, small uppercase navigation, product grids with no visible containers, a wide display face or a condensed sans, captions with product names that link to products.\n\n**Lookbook pattern**: a sequence of large images, each with a small caption listing the pieces (linked to real products). Alternate full bleed and two up. On phones, swipe horizontally within a look.\n\n**Type**: navigation and labels 11 to 13px caps, tracking 0.08 to 0.14em; product names 13 to 15px; display used sparingly and big.\n\n**Colour**: from the season's campaign; neutrals for the frame. A collection can recolour the header and accent.\n\n**Motion**: image hover swaps to the second product image (crossfade 200 to 300ms); slow scale on campaign images; marquee for a drop announcement.\n\n**Avoid**: rounded product cards, shadows, star ratings, sticker badges, stock models.\n"
 },
 {
  "file": "entries/style/style-fitness.md",
  "source": "---\nid: style-fitness\ntitle: Fitness style\ncategory: style\nsummary: Energy through scale, rhythm and real bodies in motion, with directions beyond black and neon.\nintents: [choose-style, build-site, redesign]\ntags: [fitness, athletic, sport, gym, energy, performance, training]\nstyles: [fitness, athletic, sport]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-fitness-coach, bold_signal]\nversion: 1\n---\n**Signals**: real people training, high contrast, condensed or heavy display type, numbers used visually (sets, reps, times), rhythm from marquees or schedules.\n\n**Beyond the default**: the default is black, neon green and all caps condensed. Alternatives: a lab style (white, mono numbers, measurement rules) for performance coaches; a sunrise club style (warm coral, sand, rounded grotesk) for community training; a heritage boxing gym style (cream, red, slab serif, poster layouts).\n\n**Type**: display heavy or condensed at 56 to 140px; body 16 to 18px; tabular numerals for schedules and stats.\n\n**Imagery**: crop tight on effort (hands, chalk, breath), use motion blur sparingly, no stock models posing with dumbbells.\n\n**Motion**: quick (150 to 250ms) and snappy; counters only for real numbers; marquee for class times.\n\n**Don't**: before and after photos without consent and source, fake stats, shouty copy in every heading.\n"
 },
 {
  "file": "entries/style/style-glassmorphism.md",
  "source": "---\nid: style-glassmorphism\ntitle: Glassmorphism (when it is asked for)\ncategory: style\nsummary: Frosted translucent panels over rich backgrounds; only when the concept calls for it, with readable contrast and a solid fallback.\nintents: [choose-style, build-site, redesign]\ntags: [glassmorphism, glass, frosted, blur, translucent, backdrop]\nstyles: [glassmorphism, glass, frosted]\nphases: [concept, plan, build]\npriority: 3\nrelated: [anti-slop-relative-judgement, style-dark-cinematic]\nversion: 1\n---\n**Default stance**: avoided unless the brief or concept asks, because it is one of the most common machine defaults. When it is chosen, do it well.\n\n**Needs a real background**: glass only reads over a photo, video or a colourful field. Over a flat grey it is just a faint box.\n\n**Specs**: `backdrop-filter: blur(16px) saturate(140%)`, background `rgba(255,255,255,.12)` to `.2` on dark or `rgba(255,255,255,.55)` to `.7` on light, 1px border `rgba(255,255,255,.25)`, radius 12 to 20px.\n\n**Contrast**: test text against the busiest part of the background behind the panel. Increase panel opacity until body text passes 4.5:1.\n\n**Fallback and performance**: `@supports not (backdrop-filter: blur(1px))` gives a solid background; avoid more than two or three blurred layers on screen (blur is costly on phones); never animate the blur radius.\n\n```css\n.glass { background: rgba(255,255,255,.6); }\n@supports (backdrop-filter: blur(1px)) { .glass { background: rgba(255,255,255,.18); backdrop-filter: blur(16px) saturate(140%); } }\n```\n"
 },
 {
  "file": "entries/style/style-grid-led.md",
  "source": "---\nid: style-grid-led\ntitle: Grid led\ncategory: style\nsummary: A visible structure: columns, hairlines, numbered cells and aligned captions; information dense and calm, like a well set catalogue.\nintents: [choose-style, build-site, redesign]\ntags: [grid, grid-layout, swiss, catalogue, hairline, modular, index]\nstyles: [grid, swiss]\nphases: [concept, plan, build]\npriority: 3\nrelated: [core-inspiration, core-visual-concept-first]\nversion: 1\n---\n**Signals**: a 12 column grid you can feel; 1px rules between rows and columns; numbers and labels in small caps or mono; images cropped to grid units; text and images aligned on the same lines.\n\n**Layouts**: an index table of projects or products; a two column spec sheet; a modular grid where one cell spans two for emphasis (not a bento of equal cards); a sticky left column with section numbers.\n\n**Type**: Swiss grotesk or Newsprint systems (typography-type-library); tabular numerals; tight display tracking.\n\n**Do**: let density vary: a sparse statement row after a dense table.\n\n**Don't**: put every item in an equal rounded card; the grid is lines and alignment, not boxes.\n\n**Combines with**: swiss, editorial, industrial, architecture and shop catalogues.\n"
 },
 {
  "file": "entries/style/style-illustrative.md",
  "source": "---\nid: style-illustrative\ntitle: Illustrative\ncategory: style\nsummary: Drawings, diagrams and hand made marks as the identity; works when the illustration is specific to the business.\nintents: [choose-style, build-site, redesign]\ntags: [illustrative, illustration, drawing, hand-drawn, diagram, sketch]\nstyles: [illustrative]\nphases: [concept, plan, build]\npriority: 3\nrelated: [core-inspiration, core-visual-concept-first]\nversion: 1\n---\n**Signals**: one illustration style throughout (line weight, palette, perspective); diagrams that explain how the product or service works; hand drawn lines connecting sections; a mascot only if the brand has one.\n\n**Layouts**: a large illustrated opening with the real offer next to it; process explained as a drawn sequence; spot drawings in margins instead of icons.\n\n**Type**: a soft serif or rounded grotesk; labels hand set only if lettering is part of the brand.\n\n**Do**: use the creator's own illustration or plain SVG drawn for this site; give each meaningful drawing alt text.\n\n**Don't**: generic blob people, isometric stock scenes, a different icon set per section.\n\n**Combines with**: playful, education, publishing, children's products, community.\n"
 },
 {
  "file": "entries/style/style-industrial.md",
  "source": "---\nid: style-industrial\ntitle: Industrial and technical\ncategory: style\nsummary: Utilitarian aesthetics: monospace data, labels and codes, rules and grids, raw materials, safety colour accents.\nintents: [choose-style, build-site, redesign]\ntags: [industrial, technical, utilitarian, mono, specs, engineering, workwear]\nstyles: [industrial, technical, utilitarian]\nphases: [concept, plan, build]\npriority: 3\nrelated: [style-swiss, style-brutalism, studio_mono]\nversion: 1\n---\n**Signals**: monospace or DIN-like type, part numbers and spec tables, thin rules and grid lines, concrete or metal photography, safety orange `#ff5a1f` or hi-vis yellow `#e6ff00` as the single accent on grey or off white.\n\n**Use for**: workwear, tools, hardware, bikes, coffee roasters, producers selling gear, technical courses.\n\n**Components**: spec tables with tabular numbers; labels like `REF 004 / 240G`; buttons as rectangles with mono caps; status chips only when they carry real state (in stock from data).\n\n**Layout**: dense information is fine when organised. Use a strict grid, consistent column widths for numbers, and plenty of contrast.\n\n**Don't**: invent technical specs. Every number shown comes from the product's fields.\n"
 },
 {
  "file": "entries/style/style-light-editorial.md",
  "source": "---\nid: style-light-editorial\ntitle: Light editorial\ncategory: style\nsummary: Paper white or warm white pages, serif reading type, generous text columns and quiet colour: a bright, literary feel.\nintents: [choose-style, build-site, redesign]\ntags: [light-editorial, paper, bright, serif, journal, literary]\nstyles: [light-editorial, editorial, paper]\nphases: [concept, plan, build]\npriority: 3\nrelated: [editorial_ink, style-editorial]\nversion: 1\n---\n**Signals**: warm white background (`#fbfaf7` or `#f7f4ee`), near black ink (`#1b1a17`), a book serif for body at 18 to 20px, a display serif or grotesk for headings, hairline rules, captions in a small sans.\n\n**Measure**: 60 to 70 characters, line height 1.55 to 1.7 for body. Paragraph spacing equal to line height; no indents unless set like a book.\n\n**Colour**: one muted accent (ink blue `#2a4a7f`, brick `#9a3b26`) for links and small markers. Links underlined with offset 3px and thickness 1px.\n\n**Use for**: writers, newsletters, publishers, thoughtful brands, course creators with long sales pages.\n\n**Avoid**: grey body text below 4.5:1, centred long text, cards around articles.\n"
 },
 {
  "file": "entries/style/style-luxury.md",
  "source": "---\nid: style-luxury\ntitle: Luxury\ncategory: style\nsummary: Space, slowness and precision: refined serif or wide sans, muted deep palette, large photography, no urgency devices.\nintents: [choose-style, build-site, redesign]\ntags: [luxury, premium, refined, elegant, high-end, quiet-luxury]\nstyles: [luxury, premium]\nphases: [concept, plan, build]\npriority: 3\nrelated: [quiet_luxury, industry-luxury-brand]\nversion: 1\n---\n**Signals**: large uninterrupted imagery, generous margins (section padding 120 to 200px desktop), small precise type, capitals with wide tracking for labels, slow eased motion.\n\n**Type**: display in a high contrast serif or a light wide grotesk at 40 to 96px; labels 11 to 13px caps at 0.12 to 0.2em tracking; body 16px with 1.6 to 1.7 line height.\n\n**Palette**: ivory `#f5f1ea`, charcoal `#1d1c1a`, one deep colour (oxblood `#5a1a1a`, bottle `#1f3a2e`). Accent only on hover and focus lines, never as large fills.\n\n**Components**: text buttons with an underline or thin outlined buttons (1px, radius 0); product cards without borders; image reveals with clip-path masks.\n\n**Avoid**: badges, sale tags, stars, pills, more than one call to action per screen, gold gradients, glow.\n\n**Combines with**: editorial (magazine spreads with luxury pacing), minimalism, dark cinematic (for fragrance or night collections).\n"
 },
 {
  "file": "entries/style/style-minimalism.md",
  "source": "---\nid: style-minimalism\ntitle: Minimalism\ncategory: style\nsummary: Few elements, strict spacing and one typeface doing all the work; minimal means every element has a job, not empty space as decoration.\nintents: [choose-style, build-site, redesign]\ntags: [minimal, minimalism, clean, whitespace, restraint, simple]\nstyles: [minimalism, minimal]\nphases: [concept, plan, build]\npriority: 3\nrelated: [nordic_calm, style-swiss]\nversion: 1\n---\n**What it is**: reduction with intent. The page has fewer things, and each is placed exactly.\n\n**Specs**: one family (two weights) or two closely related; a type scale with 4 to 5 sizes; an 8px spacing scale used strictly; one accent or none; borders 1px at low contrast; radius 0 to 4px.\n\n**Do**: let alignment create structure (a shared left edge, a baseline rhythm). Use real content density; a minimal product grid still shows name and price clearly. Make interaction states visible even if subtle (underline offset change, 1px border darkening).\n\n**Don't**: confuse emptiness with minimalism. Huge gaps between unrelated items break grouping. Grey text at 3:1 on white fails contrast; minimal does not mean faint.\n\n**Combines with**: editorial (minimal grid plus a serif display), luxury (minimal plus slow motion and fine photography), Swiss (minimal plus a hard grid and asymmetric type).\n\n```css\n:root { --space: 8px; --text: #111; --muted: #555; --rule: #e6e6e6; }\nh1 { font-size: clamp(2rem, 4vw + 1rem, 3.5rem); font-weight: 500; letter-spacing: -0.02em; }\n```\n"
 },
 {
  "file": "entries/style/style-neo-brutalism.md",
  "source": "---\nid: style-neo-brutalism\ntitle: Neo brutalism\ncategory: style\nsummary: Bright flat colour, thick black outlines, hard offset shadows and chunky type; friendly and loud.\nintents: [choose-style, build-site, redesign]\ntags: [neo-brutalism, neobrutalism, bold, offset-shadow, flat-colour, playful-brutal]\nstyles: [neo-brutalism, neobrutalism]\nphases: [concept, plan, build]\npriority: 3\nrelated: [style-brutalism, style-playful, bold_signal]\nversion: 1\n---\n**Signals**: 2 to 3px black borders on everything interactive, hard offset shadows (`4px 4px 0 #000`, no blur), saturated flat fills (yellow `#ffd84d`, pink `#ff7ab6`, cyan `#5ce1e6`), chunky grotesk or rounded display, slight radius (0 to 8px).\n\n**Interaction**: buttons press down: on active, move by the shadow offset and remove the shadow. Hover can lift by 2px. This makes it feel physical.\n\n```css\n.btn { border: 3px solid #111; box-shadow: 4px 4px 0 #111; transition: transform .12s, box-shadow .12s; }\n.btn:hover { transform: translate(-1px,-1px); box-shadow: 5px 5px 0 #111; }\n.btn:active { transform: translate(4px,4px); box-shadow: 0 0 0 #111; }\n@media (prefers-reduced-motion: reduce) { .btn { transition: none; } }\n```\n\n**Use for**: creators with playful brands, indie products, kids and education, zines.\n\n**Limits**: two or three fill colours, not seven. Body text stays on a calm background. Offset shadows on everything becomes noise; reserve them for interactive elements and one or two feature panels.\n"
 },
 {
  "file": "entries/style/style-neumorphism.md",
  "source": "---\nid: style-neumorphism\ntitle: Neumorphism (when it is asked for)\ncategory: style\nsummary: Soft extruded surfaces made with paired light and dark shadows; low contrast by nature, so use sparingly and fix affordances.\nintents: [choose-style, build-site, redesign]\ntags: [neumorphism, soft-ui, embossed, extruded, soft-shadow]\nstyles: [neumorphism, soft-ui]\nphases: [concept, plan, build]\npriority: 3\nrelated: [anti-slop-relative-judgement, color-contrast-rules]\nversion: 1\n---\n**Default stance**: rarely right for a whole site; its low contrast hurts readability and makes buttons hard to see. Use for one tactile element (a player control, a toggle) or when explicitly asked.\n\n**Specs**: background and element share one colour (e.g. `#e8ebef`); shadows `8px 8px 16px #c5c8cc, -8px -8px 16px #ffffff`; pressed state uses inset shadows; radius 12 to 24px.\n\n**Fix the affordance**: interactive elements need something beyond shadow: a text label with full contrast, an icon at 3:1, and a visible focus ring (2px solid accent with offset). Disabled must look different from enabled by more than shadow.\n\n**Don't**: build forms with neumorphic inputs only (borders invisible), or rely on shadow alone for state.\n"
 },
 {
  "file": "entries/style/style-organic.md",
  "source": "---\nid: style-organic\ntitle: Organic and natural\ncategory: style\nsummary: Earth tones, natural textures, soft irregular shapes and handmade details; warmth without kitsch.\nintents: [choose-style, build-site, redesign]\ntags: [organic, natural, earthy, botanical, handmade, craft, sustainable]\nstyles: [organic, natural, earthy]\nphases: [concept, plan, build]\npriority: 3\nrelated: [organic_grove, desert_bloom, style-wellness]\nversion: 1\n---\n**Signals**: earth palettes (clay `#c46b4a`, moss `#5b6b3a`, sand `#e8dcc8`, bark `#3b2f26`), paper textures used lightly, irregular image masks (arches, soft blobs used once), a warm serif or a humanist sans, photography of materials and hands.\n\n**Use for**: ceramics, food producers, florists, sustainable brands, herbalists, craft courses.\n\n**Shapes**: an arch top image (`border-radius: 999px 999px 0 0`) or one hand drawn divider is enough. Do not mask every image differently.\n\n**Motion**: slow, gentle, mostly fades; a slight rotation on hover for objects can feel handmade.\n\n**Don't**: leaf icons beside every heading, \"eco\" green gradients, unverified sustainability claims (carbon neutral, 100% organic) unless the creator states them.\n"
 },
 {
  "file": "entries/style/style-photographic.md",
  "source": "---\nid: style-photographic\ntitle: Photographic\ncategory: style\nsummary: The photographs carry the site: big, uncropped or deliberately cropped, few words, captions as part of the design.\nintents: [choose-style, build-site, redesign]\ntags: [photographic, photography, fullscreen, image-led, full-bleed, imagery]\nstyles: [photographic, photography]\nphases: [concept, plan, build]\npriority: 3\nrelated: [core-inspiration, core-visual-concept-first]\nversion: 1\n---\n**Signals**: full bleed and full screen images, images shown at their own ratio, sequences that pace like a book, small precise captions, almost no interface chrome.\n\n**Layouts**: one image per screen; diptychs; a horizontal sequence (example ai_hscroll_gallery); a text index with hover image reveal (ai_hover_reveal_list); a slow parallax band (ai_parallax_media) once per page at most.\n\n**Type**: small and exact (Gallery label system) or a single large italic serif statement.\n\n**Do**: use the creator's own photographs; write alt text that says what is in the picture; size images with width and height to avoid layout shift.\n\n**Don't**: dark overlays on every image, stock photography, text over busy parts of a photo without a scrim.\n\n**Combines with**: minimalism, portfolio, luxury, travel and hotels, food.\n"
 },
 {
  "file": "entries/style/style-playful.md",
  "source": "---\nid: style-playful\ntitle: Playful\ncategory: style\nsummary: Bright colour, rounded shapes, bouncy micro interactions and characterful type, kept organised by a tight system.\nintents: [choose-style, build-site, redesign]\ntags: [playful, fun, colourful, friendly, quirky, rounded, bright]\nstyles: [playful, fun]\nphases: [concept, plan, build]\npriority: 3\nrelated: [playful_pop, style-neo-brutalism]\nversion: 1\n---\n**Signals**: two or three saturated colours on a light base, rounded radius (12 to 24px) or pill buttons, a rounded or quirky display face, illustrations or stickers made for the brand, springy hover states.\n\n**System keeps it from chaos**: a fixed palette (background, ink, 2 to 3 fills), one radius value per component type, one shadow style, consistent icon stroke width.\n\n**Motion**: springy (cubic-bezier(.34,1.56,.64,1)) at 200 to 350ms for small elements only; wiggles and bounces on hover are fine for one or two signature elements, not every card.\n\n**Good fits**: kids brands, snacks, games, community clubs, creator merch, education for beginners.\n\n**Don't**: use random emoji as icons, rainbow gradients by default, or comic sans style fonts for body text.\n"
 },
 {
  "file": "entries/style/style-portfolio.md",
  "source": "---\nid: style-portfolio\ntitle: Portfolio style\ncategory: style\nsummary: Frameworks for showing work: index lists, image grids, single project per view; consistency of presentation is the style.\nintents: [choose-style, build-site, redesign]\ntags: [portfolio, work, index, case-study, personal]\nstyles: [portfolio]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-portfolio, layout-masonry]\nversion: 1\n---\n**Three proven shapes**\n1. **Index list**: rows of project title, client, year, discipline in a tabular layout; hover or focus shows a preview image. Very fast to scan; works for large bodies of work.\n2. **Grid**: images at a consistent ratio (or masonry for mixed), small captions under each. Best for visual disciplines.\n3. **Sequence**: one project per viewport height, large image, title and a single line. Best for few, strong projects.\n\n**Specs**: captions 13 to 14px; project titles 18 to 24px in the grid; case study headings 40 to 72px. Image ratio rules: pick one (4:5, 3:2, 16:10) for the grid and stick to it unless using masonry.\n\n**Do**: keep chrome minimal so the work carries colour. Make every project reachable by keyboard with a visible focus state.\n\n**Don't**: autoplaying carousels, skill bars, scroll hijacking, preloaders that hide the work for seconds.\n"
 },
 {
  "file": "entries/style/style-premium-personal-brand.md",
  "source": "---\nid: style-premium-personal-brand\ntitle: Premium personal brand\ncategory: style\nsummary: Polished personal sites for authors, speakers and experts: a strong portrait, editorial typography and clear ways to hire or buy.\nintents: [choose-style, build-site, redesign]\ntags: [personal-brand, speaker, author, founder, expert, thought-leader, premium]\nstyles: [premium-personal-brand, personal-brand]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-coaching, style-editorial, style-luxury]\nversion: 1\n---\n**Signals**: a professionally lit portrait at large size, an editorial serif or refined grotesk, a restrained palette taken from the person's wardrobe or book covers, selected appearances and writing as proof.\n\n**Structure**: name and what they are known for -> the main offer (book, speaking, advisory, course) -> selected work or appearances (real) -> about -> writing or newsletter -> contact for bookings with what to include.\n\n**Moves that feel premium**: a portrait that bleeds off one edge with the name set across it; a list of talks as an elegant index with years; quotes from real press in italic serif.\n\n**Don't**: \"World renowned\", \"visionary\" or invented logos of media outlets. Do not add a fake stats strip (countries, audiences reached) unless the person supplied the numbers.\n"
 },
 {
  "file": "entries/style/style-saas.md",
  "source": "---\nid: style-saas\ntitle: SaaS product style, done well\ncategory: style\nsummary: Product led sites that show the real interface with precise type and restraint, instead of the gradient, glow and icon grid template.\nintents: [choose-style, build-site, redesign]\ntags: [saas, product, app, startup, software, interface]\nstyles: [saas, product, startup]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-saas, anti-slop-identical-saas, midnight_tech]\nversion: 1\n---\n**Good SaaS style is product photography for software**: the UI is the hero, shown large, crisp and annotated.\n\n**Specs**: one sans (Inter, Geist-like, or a grotesk with character) with tabular numerals; a 4px or 8px spacing scale; neutral surfaces; one brand accent from the product's own UI; radius matching the product UI (often 6 to 10px).\n\n**Do**: real screenshots at 1x or 2x with `srcset`; short looping clips of a workflow (muted, no autoplay on slow connections, poster image); feature sections that alternate text and screenshot with real captions; a changelog or docs link as proof of activity.\n\n**Don't**: purple to blue gradients, glowing orbs behind the hero, a fake dashboard of random charts, nine feature icons, \"Trusted by\" logos without permission.\n\n**Variations**: a docs-like engineering style (mono labels, thin rules, light background), a creative tool style (bold colour, big type, playful), an enterprise style (calm navy and white, dense information, comparison tables).\n"
 },
 {
  "file": "entries/style/style-swiss.md",
  "source": "---\nid: style-swiss\ntitle: Swiss and International style\ncategory: style\nsummary: A visible grid, asymmetric layouts, a neo grotesk, flush left ragged right text and objective imagery.\nintents: [choose-style, build-site, redesign]\ntags: [swiss, international, grid, helvetica, modernist, rational, asymmetric]\nstyles: [swiss, international, grid]\nphases: [concept, plan, build]\npriority: 3\nrelated: [swiss_grid, layout-asymmetric-grid, style-minimalism]\nversion: 1\n---\n**Signals**: everything locks to a column grid; type is flush left, ragged right; hierarchy through size and weight, not colour; generous negative space on one side; numbers and labels used structurally.\n\n**Specs**: 12 column grid, 24px gutters, margins at least one column; a neo grotesk (Inter, Helvetica-like, Neue Haas-like families available in the theme) in 2 to 3 weights; scale ratio about 1.333; headlines tight (-0.02 to -0.03em), body 0.\n\n**Colour**: black, white, one primary (signal red `#e2231a`, blue `#0046ad`) used in blocks or for one element per screen.\n\n**Moves**: oversized numerals as section markers when the order matters, rotated vertical labels, rules spanning the grid, images cropped to grid units.\n\n**Don't**: centre layouts, add drop shadows, rounded corners, decorative icons.\n\n**Combines with**: editorial, brutalism (Swiss grid with raw elements), industrial (technical specs and mono).\n"
 },
 {
  "file": "entries/style/style-typography-led.md",
  "source": "---\nid: style-typography-led\ntitle: Typography led\ncategory: style\nsummary: Type is the image: oversized headlines, careful kerning, mixed weights and widths; few or no photos.\nintents: [choose-style, build-site, redesign]\ntags: [typography, type-led, typographic, big-type, lettering, type-driven]\nstyles: [typography-led, type-led]\nphases: [concept, plan, build]\npriority: 3\nrelated: [typography-display, typography-scale, style-swiss]\nversion: 1\n---\n**When**: brands without strong photography, writers, studios, events, manifestos.\n\n**Moves**: headlines at 10 to 20vw that run edge to edge; mixing a serif italic with a grotesk in one line; outlined or hollow type used once; numbers as giant graphic elements; text set on a path or vertically for labels.\n\n**Specs**: display line height 0.85 to 1.0; tracking -0.02 to -0.05em at large sizes; fluid sizes with `clamp()`; `text-wrap: balance` on headings; check that the longest word fits at 320px (use `overflow-wrap: anywhere` as a fallback, or reduce size).\n\n```css\n.display { font-size: clamp(3rem, 12vw, 12rem); line-height: .9; letter-spacing: -.04em; text-wrap: balance; }\n```\n\n**Don't**: let giant type push the action below three screens on phones. Keep the call to action visible in the first view.\n"
 },
 {
  "file": "entries/style/style-unusual-layout.md",
  "source": "---\nid: style-unusual-layout\ntitle: Unusual layout\ncategory: style\nsummary: Layouts that break the centred column on purpose: offsets, overlaps, side rails, rotated labels, text that hangs; memorable when held to a grid underneath.\nintents: [choose-style, build-site, redesign]\ntags: [unusual-layout, experimental, offset, overlap, asymmetry, side-rail, broken-grid]\nstyles: [unusual-layout, experimental]\nphases: [concept, plan, build]\npriority: 3\nrelated: [core-inspiration, core-visual-concept-first]\nversion: 1\n---\n**Signals**: content hanging from an off centre axis; an image overlapping the next section by a few rows; a vertical side rail with the site name or the section number; captions rotated 90 degrees in a margin; a headline that crosses two columns.\n\n**Rules**: the strangeness needs a hidden grid (12 columns, a baseline) so it reads as intended. One or two unusual moves per page, repeated as a motif, not a different trick per section. On phones it collapses into a clear single column with one surviving signature (the rail becomes a top label, the overlap stays small).\n\n**Do**: test every overlap at 375px; keep text on solid ground; keep focus order the visual order.\n\n**Don't**: overlap text with text, rotate body copy, or make navigation hard to find.\n\n**Combines with**: typography-led, portfolio, agency, fashion.\n"
 },
 {
  "file": "entries/style/style-wellness.md",
  "source": "---\nid: style-wellness\ntitle: Wellness style\ncategory: style\nsummary: Calm, readable and warm without the beige and script cliché: soft contrast surfaces, honest photography, gentle motion.\nintents: [choose-style, build-site, redesign]\ntags: [wellness, calm, soft, gentle, spa, mindful, natural]\nstyles: [wellness, calm, soft]\nphases: [concept, plan, build]\npriority: 3\nrelated: [industry-wellness, soft_care, style-organic]\nversion: 1\n---\n**Signals**: soft but readable contrast (text still 4.5:1), warm or mineral neutrals, rounded but not pill shaped components (8 to 16px), humanist sans or a gentle serif, natural light photography, slow fades.\n\n**Palettes that are not sage and beige**: stone and slate (`#e9e6e1`, `#3e4644`); clay and ink (`#efe3d6`, `#2b2522`, accent `#b5643c`); night bath (`#1e2a2a`, `#d9e2dc`, accent `#c9a46a`).\n\n**Type**: a humanist sans for UI and body at 17 to 18px; display in a soft serif. Avoid script fonts for anything longer than a word.\n\n**Motion**: fades and small upward drifts (8 to 12px) at 400 to 600ms; no bounces, no parallax shaking.\n\n**Do**: make practicalities easy to find (time, place, price, what to bring). Calm comes from clarity.\n\n**Don't**: lotus icons, gradient blobs, stock meditation photos, vague healing claims.\n"
 },
 {
  "file": "entries/typography/typography-display.md",
  "source": "---\nid: typography-display\ntitle: Display type and big headlines\ncategory: typography\nsummary: Using oversized type safely: fitting long words, mixed styles in a heading, outlined text, and keeping the action in view on phones.\nintents: [design-hero, fix-typography, choose-style]\ntags: [display, headline, big-type, hero-type, oversized, outline-text]\ncomponents: [hero, typography]\nphases: [build, review]\npriority: 4\nrelated: [style-typography-led, typography-scale]\nversion: 1\n---\n**Size**: big type works when the words are few. A five word heading can be 12vw; a fourteen word heading cannot. Write the heading first, then size it.\n\n**Fitting**: check the longest word at 320px. German, Dutch and product names break layouts. Use `overflow-wrap: anywhere` as a safety net and lower the clamp minimum until the longest word fits.\n\n**Mixed styles**: one line can mix a serif italic and a grotesk, or two weights. Mark it with real elements so it stays editable:\n\n```html\n<h1 class=\"display\">Strength for <em>the long run</em></h1>\n```\n```css\n.display em { font-family: var(--font-serif); font-style: italic; font-weight: 400; }\n```\n\n**Outlined text**: `-webkit-text-stroke: 1.5px currentColor; color: transparent;` fails contrast for reading; use it for one decorative word next to solid text, never for content people must read.\n\n**Phones**: a giant heading must not push the primary action below the first screen. Measure: heading plus subline plus button within about 560px of height at 375px wide.\n\n**Don't**: gradient text by default, all caps sentences longer than four words, letter spacing above 0 on large display lowercase.\n"
 },
 {
  "file": "entries/typography/typography-hierarchy-labels.md",
  "source": "---\nid: typography-hierarchy-labels\ntitle: Labels, eyebrows, captions and meta text\ncategory: typography\nsummary: When small text above or below a heading earns its place, how to style it, and how to avoid the eyebrow chip habit.\nintents: [build-section, fix-typography, review]\ntags: [eyebrow, label, caption, meta, kicker, small-text]\ncomponents: [typography, badge]\nphases: [build, review]\npriority: 3\nrelated: [anti-slop-pill-badges, typography-tracking-measure]\nversion: 1\n---\nSmall text is useful when it carries information the heading does not: a date, a category, a step number that matters, a location, a price, a reading time.\n\n**Earns its place**: \"Saturday 14 June, Leeds\" above an event name. \"Module 3 of 8\" above a lesson title. \"Photo: Ana Ruiz\" under an image.\n\n**Does not**: \"Our services\" above a heading that says \"Services\". \"Features\" above \"Everything you need\". Numbered markers 01, 02, 03 on sections that are not sequential.\n\n**Styling**: 12 to 14px, either uppercase with +0.08 to +0.14em tracking or sentence case in a muted colour that still passes 4.5:1. Plain text, not a pill or chip with a background. Keep 8 to 12px between label and heading.\n\n**Captions**: 13 to 14px, muted, max 60ch, directly under the image with 8px gap. Credit photographers when the image came from an open licence that needs it.\n"
 },
 {
  "file": "entries/typography/typography-loading.md",
  "source": "---\nid: typography-loading\ntitle: Web font loading and performance\ncategory: typography\nsummary: How many font files to load, font-display, preloading, fallbacks with matched metrics, and avoiding layout shift.\nintents: [performance, build-site, debug]\ntags: [font-loading, performance, font-display, cls, fallback, preload]\ncomponents: [typography]\nphases: [build, repair]\npriority: 3\nrelated: [debug-layout-shift, typography-pairings]\nversion: 1\n---\n- **Budget**: at most 4 font files on first load (for example display 600, body 400, body 400 italic, body 700). A variable font counts as one file per axis set.\n- **font-display**: `swap` for body text so text shows immediately; `optional` for decorative display faces on slow connections.\n- **Preload** only the one or two files used above the fold: `<link rel=\"preload\" as=\"font\" type=\"font/woff2\" href=\"...\" crossorigin>`.\n- **Fallback metrics**: define a fallback with adjusted metrics to avoid layout shift when the web font arrives.\n\n```css\n@font-face { font-family: \"Body Fallback\"; src: local(\"Arial\"); size-adjust: 104%; ascent-override: 92%; descent-override: 24%; }\nbody { font-family: \"Inter\", \"Body Fallback\", system-ui, sans-serif; }\n```\n\n- **Subsetting**: use the Latin subset unless the site needs other scripts; check the creator's language.\n- In Storelib sections, use the theme's font settings or families the theme loads; do not add arbitrary remote font URLs from section code.\n"
 },
 {
  "file": "entries/typography/typography-pairings.md",
  "source": "---\nid: typography-pairings\ntitle: Font pairings that work, by mood\ncategory: typography\nsummary: Concrete display and body pairings grouped by mood, with weights and rules for when to use one family instead of two.\nintents: [choose-fonts, choose-style, build-site]\ntags: [fonts, pairing, typeface, serif, sans, mono, google-fonts]\ncomponents: [typography]\nphases: [concept, plan]\npriority: 5\nrelated: [typography-type-library, typography-scale, typography-loading]\nversion: 2\n---\nUse families the theme can load (the Typography list; typography-type-library has complete systems). Pair by contrast of structure, not by two similar sans serifs. The display face is never a default (Inter, Roboto, Poppins, Montserrat, Open Sans, Lato, system-ui) unless the creator asked for it.\n\n| Mood | Display | Body | Notes |\n| --- | --- | --- | --- |\n| Editorial, literary | Instrument Serif italic, Fraunces, Playfair Display, DM Serif Display | Instrument Sans, Source Serif 4 | serif display at 400 to 600, body 400 |\n| Luxury | Cormorant Garamond, Bodoni Moda, Italiana | Jost | caps labels tracked 0.15em to 0.22em |\n| Swiss, precise | Inter Tight, Archivo | Inter Tight, Work Sans | one family, weights 400/600, tracking -0.04em on display |\n| Bold, sporty | Anton, Barlow Condensed, Bebas Neue, League Gothic | Archivo, IBM Plex Sans | condensed display only above 40px |\n| Industrial, technical | Space Grotesk, JetBrains Mono | IBM Plex Sans, IBM Plex Mono for data | mono for numbers, codes, labels |\n| Warm, friendly | Fraunces soft, Young Serif, Fredoka | Karla, Nunito Sans, Libre Franklin | larger body (17 to 18px) |\n| Playful, art school | Syne, Bricolage Grotesque, Unbounded | Familjen Grotesk, Hanken Grotesk, Work Sans | one expressive weight only |\n| Brutal, zine | Space Mono, JetBrains Mono | the same family | default looking on purpose, but a chosen mono |\n| Clear, accessible | Literata | Atkinson Hyperlegible, Lexend | services and non-profits |\n\n**One family is often better**: a variable grotesk with a weight range covers display and text and loads faster.\n\n**Rules**: at most two families plus an optional mono. Body face must have regular and bold. Check the display face at the longest real heading and at 320px wide. Do not use a script or decorative face for anything people must read in full.\n"
 },
 {
  "file": "entries/typography/typography-scale.md",
  "source": "---\nid: typography-scale\ntitle: Type scales and fluid sizes\ncategory: typography\nsummary: Choosing a modular ratio, a limited set of sizes, fluid clamp values, and the number of sizes a page should use.\nintents: [choose-fonts, build-section, fix-typography]\ntags: [type-scale, font-size, clamp, fluid, hierarchy, modular-scale]\ncomponents: [typography]\nphases: [plan, build, review]\npriority: 5\nrelated: [typography-pairings, anti-slop-typography-chaos]\nversion: 1\n---\n**Pick a ratio by density**: 1.2 (minor third) for dense UI and shops, 1.25 to 1.333 for most sites, 1.5 to 1.618 for type led and editorial heroes.\n\n**Limit the sizes**: a page uses about 6 to 8 distinct font sizes total. More than 10 reads as inconsistent; the evaluator flags it.\n\n**Example scale (1.25, base 16px)**: 12, 14, 16, 20, 25, 31, 39, 49, 61. Use 13 or 14 for captions and labels, 16 to 18 for body, then jump to display sizes.\n\n**Fluid sizes**: interpolate between phone and desktop with `clamp()`. Keep body fixed (16 to 18px) and make headings fluid.\n\n```css\n:root {\n  --step-0: 1rem;\n  --step-1: clamp(1.15rem, 1.05rem + .5vw, 1.35rem);\n  --step-2: clamp(1.4rem, 1.2rem + 1vw, 1.9rem);\n  --step-3: clamp(1.8rem, 1.4rem + 2vw, 2.8rem);\n  --step-4: clamp(2.3rem, 1.6rem + 3.5vw, 4.2rem);\n  --step-5: clamp(2.8rem, 1.6rem + 6vw, 6.5rem);\n}\n```\n\n**Line height** falls as size rises: body 1.5 to 1.7, subheads 1.25 to 1.35, display 0.95 to 1.1.\n\n**Hierarchy is more than size**: use weight, case, colour and space. A label in 12px caps tracked out can outrank 16px body without being bigger.\n"
 },
 {
  "file": "entries/typography/typography-tracking-measure.md",
  "source": "---\nid: typography-tracking-measure\ntitle: Tracking, measure and line height\ncategory: typography\nsummary: Letter spacing by size and case, comfortable line lengths, paragraph spacing and wrapping rules with exact values.\nintents: [fix-typography, build-section]\ntags: [tracking, letter-spacing, measure, line-length, line-height, wrapping, kerning]\ncomponents: [typography]\nphases: [build, review]\npriority: 4\nrelated: [typography-scale]\nversion: 1\n---\n**Tracking (letter-spacing)**\n- Display 48px and up: -0.01 to -0.04em (tighter as it grows; condensed faces need less).\n- Body 15 to 20px: 0 (never track body text out).\n- Small caps and uppercase labels 11 to 14px: +0.06 to +0.16em. Uppercase always needs positive tracking.\n- Monospace: 0 or slightly negative at display sizes.\n\n**Measure**: 45 to 75 characters per line for body, 60 to 68 ideal. Set with `max-width: 65ch` on the text block, not on the section.\n\n**Line height**: body 1.5 to 1.7 (longer measure needs more); headings 1.0 to 1.25; captions 1.4.\n\n**Paragraph spacing**: margin equal to about one line (1em to 1.5em). No first line indent on the web unless it is a book style concept.\n\n**Wrapping**: `text-wrap: balance` on headings of up to about 6 lines; `text-wrap: pretty` on paragraphs to avoid single word last lines; `hyphens: auto` only with a `lang` attribute and narrow columns.\n\n**Numbers**: `font-variant-numeric: tabular-nums` in prices, tables, schedules and counters so columns align and counters do not jitter.\n"
 },
 {
  "file": "entries/typography/typography-type-library.md",
  "source": "---\nid: typography-type-library\ntitle: The type library: complete type systems that load\ncategory: typography\nsummary: Curated display, text and label pairings by voice and mood, all loadable on Storelib, with weights, tracking, leading and a fluid clamp() scale; Inter, Roboto, Poppins and friends never as the display face.\nintents: [choose-fonts, choose-style, build-site, redesign]\ntags: [fonts, type, typography, pairing, type-library, type-scale, clamp, tracking, serif, grotesk, mono, condensed, display, inter, poppins, montserrat]\ncomponents: [typography]\nphases: [concept, plan, build, review]\npriority: 5\nrelated: [typography-pairings, typography-scale, typography-tracking-measure, anti-slop-typography-chaos, anti-slop-default-fonts]\nversion: 1\n---\n**Rule**: the display face carries the personality. Inter, Roboto, Open Sans, Lato, Montserrat, Poppins, Plus Jakarta Sans, Raleway, Arial, Helvetica and system-ui as the display face read as \"nobody chose this\" and are refused by the concept check and the anti-slop check, unless the creator named one (then the concept says allow \"default-fonts\"). They are fine as body text. Every family below is in the Typography list, so set_tokens fonts loads it for real.\n\n**Serif**\n- Editorial italic: Instrument Serif 400 italic display (tracking -0.02em, leading 0.95), Instrument Sans text, DM Mono caps labels; ratio 1.5. Headlines huge, one or two words a line; never bold the serif.\n- Newsprint: Source Serif 4 600 for display and 400 for text, IBM Plex Mono for bylines; ratio 1.333.\n- Soft serif: Fraunces 400 display, Karla text at 17px; ratio 1.333. Warm services, food, wellness.\n- High contrast fashion: Bodoni Moda 500 caps display (only above 40px), Jost text, Jost caps labels tracked 0.18em; ratio 1.618.\n- Heritage press: Young Serif display, Libre Franklin text and tracked caps labels; ratio 1.333.\n- Luxe whisper: Cormorant Garamond italic display, Jost 300 text, tiny caps tracked 0.22em; ratio 1.5.\n- Modern classic: DM Serif Display, DM Sans text; ratio 1.414. A personal brand pairing.\n\n**Grotesk**\n- Swiss grotesk: Inter Tight 600 display at -0.045em, leading 0.9, JetBrains Mono labels; ratio 1.618. Flush left, numbered sections.\n- Characterful grotesk: Bricolage Grotesque 700 display at -0.035em, Hanken Grotesk text; ratio 1.5.\n- News gothic: Schibsted Grotesk 800 headlines, 400 text, IBM Plex Mono dates; ratio 1.5.\n- Wide display: Unbounded 700 caps for two or three words, Work Sans text, Space Mono labels.\n- Art school: Syne 700 display, Familjen Grotesk text; ratio 1.618.\n- Gallery label: Instrument Sans 500 small and exact beside big images, DM Mono captions; ratio 1.25.\n\n**Condensed**\n- Poster condensed: Anton caps (leading 0.88) filling the width, Archivo text, Archivo Narrow caps labels; ratio 1.618.\n- Athletic numerals: Barlow Condensed 700 caps for times and prices, IBM Plex Sans text; ratio 1.5.\n- Gothic poster: League Gothic caps stacked tall, Karla text, Space Mono dates; ratio 1.75.\n\n**Mono, humanist, rounded**\n- Terminal: JetBrains Mono 700 display at -0.04em, IBM Plex Sans text. Spec tables in mono.\n- Typewriter zine: Space Mono for everything, hierarchy from size and one colour.\n- Humanist clear: Literata 500 display, Atkinson Hyperlegible text; for services where clarity is the point.\n- Soft rounded: Fredoka 600 display, Nunito Sans text; flat colour and hard shadows, not gradients.\n\n**The scale**: fluid steps with clamp(), so a 96px headline is about 44px on a phone without a breakpoint. For ratio 1.333 between 360px and 1440px wide:\n`--step-0: 1rem; --step-1: clamp(1.2rem, 1.155rem + 0.197vi, 1.333rem); --step-2: clamp(1.44rem, 1.327rem + 0.5vi, 1.777rem); --step-3: clamp(1.727rem, 1.513rem + 0.95vi, 2.369rem); --step-4: clamp(2.072rem, 1.711rem + 1.608vi, 3.157rem); --step-5: clamp(2.486rem, 1.912rem + 2.552vi, 4.209rem); --step-6: clamp(2.983rem, 2.107rem + 3.892vi, 5.61rem);`\nDisplay gets its own tracking (negative for large lowercase, positive for caps and small labels), its own leading (0.86 to 1.05) and a chosen weight. Text stays 16 to 18px at 1.5 to 1.7. Numbers in prices, times and tables use font-variant-numeric: tabular-nums.\n\n**How to apply**: set_tokens fonts { heading, body, accent } with the system's families; in components read var(--theme-font-heading) and var(--theme-font-body) with a real stack behind (serif, sans-serif or monospace), set the steps on the section root, and never hard code a family the tokens did not set.\n"
 }
]
